CREATE OR REPLACE FUNCTION lubricenter_private.add_service_priced(p_order_id uuid, p_business_area text, p_description text, p_base_ref numeric, p_customer_ref numeric, p_worker_share_override_ref numeric DEFAULT NULL::numeric, p_alexis_bonus_enabled boolean DEFAULT false, p_denomination text DEFAULT 'REF'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b numeric; op numeric; factor numeric:=1; item uuid;
begin
 perform public.require_auth();
 perform 1 from public.orders where id=p_order_id for update;
 perform public.assert_order_open(p_order_id);
 if p_denomination not in ('REF','USD') or p_denomination is null then raise exception 'Selecciona REF BCV o USD pactado'; end if;
 if p_base_ref is null or p_customer_ref is null or p_base_ref::text in ('NaN','Infinity','-Infinity') or p_customer_ref::text in ('NaN','Infinity','-Infinity') or p_worker_share_override_ref::text in ('NaN','Infinity','-Infinity') then raise exception 'Monto inválido'; end if;
 select bcv_rate,operative_rate into b,op from public.get_order_rates(p_order_id);
 if b is null or op is null or b<=0 or op<=0 then raise exception 'Faltan tasas válidas'; end if;
 if p_denomination='USD' then factor:=op/b; end if;
 item:=public.add_service_item(p_order_id,p_business_area,p_description,p_base_ref*factor,p_customer_ref*factor,p_worker_share_override_ref*factor,p_alexis_bonus_enabled);
 if p_denomination='USD' then
  update public.order_items set price_denomination='USD',agreed_usd=p_customer_ref,
   charged_ves_amount=round(p_customer_ref*op,2),charged_ref_amount=round(p_customer_ref*factor,4)
  where id=item;
 end if;
 return item;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.allocate_order_number()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n bigint;
begin
 perform public.require_auth();
 update lubricenter_private.order_number_counter set last_number=last_number+1 where singleton returning last_number into n;
 if n is null then raise exception 'No está configurado el contador de órdenes'; end if;
 return n;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.apply_business_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d timestamptz; s text;
begin
 if TG_TABLE_NAME='orders' then
  if TG_OP='INSERT' then
   new.business_at:=coalesce(new.business_at,nullif(current_setting('lubricenter.business_at',true),'')::timestamptz);
   if new.business_at is not null then new.opened_at:=new.business_at; end if;
  end if;
  if new.business_at>now()+interval '5 minutes' then raise exception 'La fecha de venta no puede estar en el futuro'; end if;
  if new.status='CLOSED' and new.business_at is not null then new.closed_at:=new.business_at; end if;
 elsif TG_TABLE_NAME='payments' then
  select business_at,status into d,s from public.orders where id=new.order_id;
  if s='OPEN' and d is not null and coalesce(current_setting('lubricenter.revision',true),'')<>'yes' then new.paid_at:=d; end if;
 elsif TG_TABLE_NAME='payroll_accruals' then
  select coalesce(o.business_at,o.closed_at),o.corrects_order_id::text into d,s from public.orders o join public.order_items i on i.order_id=o.id where i.id=new.source_order_item_id;
  if s is null and d is not null then new.occurred_at:=d; end if;
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.apply_notion_pricing(p_bcv numeric, p_operative numeric, p_products jsonb, p_synced_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item jsonb; v_name text; v_key text; v_price numeric;
  v_seen text[] := array[]::text[];
  v_catalog_count integer := 0; v_product_changes integer := 0;
  v_retired integer := 0; v_rate_changes integer := 0; v_latest numeric;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('lubricenter-notion-pricing', 0));

  if p_bcv is null or p_bcv <= 0 or p_bcv > 1000000 then
    raise exception 'La tasa BCV recibida no es válida';
  end if;
  if p_operative is null or p_operative <= 0 or p_operative > 1000000 then
    raise exception 'La tasa operativa recibida no es válida';
  end if;
  if p_synced_at is null or p_synced_at > now() + interval '5 minutes' then
    raise exception 'La fecha de sincronización no es válida';
  end if;
  if coalesce((select value #>> '{}' from public.app_settings where key='catalog_authority'),'NOTION') <> 'LUBRICENTER_OS'
     and (p_products is null or pg_catalog.jsonb_typeof(p_products) <> 'array'
     or pg_catalog.jsonb_array_length(p_products) < 1
     or pg_catalog.jsonb_array_length(p_products) > 500) then
    raise exception 'El catálogo debe contener entre 1 y 500 productos';
  end if;

  if coalesce((select s.value #>> '{}' from public.app_settings s where s.key='catalog_authority'),'NOTION') <> 'LUBRICENTER_OS' then
  for v_item in select value from pg_catalog.jsonb_array_elements(p_products)
  loop
    v_name := pg_catalog.btrim(coalesce(v_item ->> 'name', ''));
    v_key := pg_catalog.lower(v_name);
    if v_name = '' then raise exception 'Hay un producto sin nombre'; end if;
    if v_key = any(v_seen) then raise exception 'El catálogo contiene el producto repetido: %', v_name; end if;

    begin
      v_price := (v_item ->> 'base_usd')::numeric;
    exception when others then
      raise exception 'El precio de % no es numérico', v_name;
    end;
    if v_price is null or v_price < 0 or v_price > 1000000 then
      raise exception 'El precio de % no es válido', v_name;
    end if;

    if exists (
      select 1 from public.products p
      where pg_catalog.lower(pg_catalog.btrim(p.name)) = v_key
        and (p.name, p.category, p.available, p.active, p.cash_usd_base_price, p.notes, p.image_url, p.catalog_source)
          is distinct from
            (v_name, nullif(pg_catalog.btrim(v_item ->> 'category'), ''), true, true, v_price,
             nullif(pg_catalog.btrim(v_item ->> 'description'), ''),
             nullif(pg_catalog.btrim(v_item ->> 'image_url'), ''), 'Notion · Nuestros Productos')
    ) or not exists (
      select 1 from public.products p where pg_catalog.lower(pg_catalog.btrim(p.name)) = v_key
    ) then v_product_changes := v_product_changes + 1; end if;

    insert into public.products (
      name, category, available, active, cash_usd_base_price, notes, image_url,
      catalog_source, catalog_synced_at, updated_at
    ) values (
      v_name, nullif(pg_catalog.btrim(v_item ->> 'category'), ''), true, true, v_price,
      nullif(pg_catalog.btrim(v_item ->> 'description'), ''),
      nullif(pg_catalog.btrim(v_item ->> 'image_url'), ''),
      'Notion · Nuestros Productos', p_synced_at, p_synced_at
    )
    on conflict (pg_catalog.lower(pg_catalog.btrim(name))) do update set
      name = excluded.name, category = excluded.category, available = true, active = true,
      cash_usd_base_price = excluded.cash_usd_base_price, notes = excluded.notes,
      image_url = excluded.image_url, catalog_source = excluded.catalog_source,
      catalog_synced_at = excluded.catalog_synced_at, updated_at = excluded.updated_at;

    v_seen := pg_catalog.array_append(v_seen, v_key);
    v_catalog_count := v_catalog_count + 1;
  end loop;

  update public.products p
  set available = false, catalog_synced_at = p_synced_at, updated_at = p_synced_at
  where p.catalog_source = 'Notion · Nuestros Productos'
    and not (pg_catalog.lower(pg_catalog.btrim(p.name)) = any(v_seen)) and p.available;
  get diagnostics v_retired = row_count;
  v_product_changes := v_product_changes + v_retired;

  else
    -- Notion continues to update exchange rates but is no longer permitted to change items.
    select count(*) into v_catalog_count from public.products where active and available;
  end if;

  select er.value into v_latest from public.exchange_rates er
  where er.rate_type = 'BCV' order by er.effective_at desc, er.created_at desc limit 1;
  if v_latest is distinct from p_bcv then
    insert into public.exchange_rates(rate_type, value, effective_at, source, created_by)
    values ('BCV', p_bcv, p_synced_at, 'Notion · Tasas', null);
    v_rate_changes := v_rate_changes + 1;
  end if;

  select er.value into v_latest from public.exchange_rates er
  where er.rate_type = 'OPERATIVE' order by er.effective_at desc, er.created_at desc limit 1;
  if v_latest is distinct from p_operative then
    insert into public.exchange_rates(rate_type, value, effective_at, source, created_by)
    values ('OPERATIVE', p_operative, p_synced_at, 'Notion · Tasas', null);
    v_rate_changes := v_rate_changes + 1;
  end if;

  if coalesce((select s.value #>> '{}' from public.app_settings s where s.key='catalog_authority'),'NOTION') <> 'LUBRICENTER_OS' then
  insert into public.integration_sync_state(source_key, last_verified_at, last_success_payload, updated_at)
  values ('notion_catalog', p_synced_at,
    pg_catalog.jsonb_build_object('products', v_catalog_count, 'changed', v_product_changes), p_synced_at)
  on conflict (source_key) do update set last_verified_at = excluded.last_verified_at,
    last_success_payload = excluded.last_success_payload, updated_at = excluded.updated_at;

  end if;

  insert into public.integration_sync_state(source_key, last_verified_at, last_success_payload, updated_at)
  values ('notion_rates', p_synced_at,
    pg_catalog.jsonb_build_object('BCV', p_bcv, 'OPERATIVE', p_operative, 'changed', v_rate_changes), p_synced_at)
  on conflict (source_key) do update set last_verified_at = excluded.last_verified_at,
    last_success_payload = excluded.last_success_payload, updated_at = excluded.updated_at;

  insert into public.audit_events(event_type, entity_type, entity_id, data, actor_id)
  values ('NOTION_PRICING_SYNCED', 'integration_sync_state', null,
    pg_catalog.jsonb_build_object('products', v_catalog_count, 'product_changes', v_product_changes,
      'rate_changes', v_rate_changes, 'bcv', p_bcv, 'operative', p_operative, 'synced_at', p_synced_at),
    auth.uid());

  return pg_catalog.jsonb_build_object('ok', true, 'products', v_catalog_count,
    'product_changes', v_product_changes, 'rate_changes', v_rate_changes, 'synced_at', p_synced_at);
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.assert_stock_sale_allowed(p_kind text, p_label text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_kind = 'CATALOG' then
    raise exception 'INVENTARIO_ÚNICO: "%" no está en el inventario. Búscalo en Inventario o pide que lo creen allí.', p_label;
  end if;
  if coalesce((select value #>> '{}' from public.app_settings where key = 'inventory_strict_mode'), 'false') <> 'true' then
    return;
  end if;
  if p_kind = 'MANUAL' then
    if not lubricenter_private.staff_can('inventory.override') then
      raise exception 'INVENTARIO_ESTRICTO: solo un administrador puede vender "%" sin descontar inventario.', p_label using errcode = '42501';
    end if;
    insert into public.audit_events(event_type, entity_type, data, actor_id)
    values ('inventory.override_sale', 'order_item', jsonb_build_object('description', p_label), auth.uid());
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.bcv_official_record(p_value numeric, p_value_date date, p_html text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior_value numeric; last_value numeric; result jsonb; today_local date:=(now() at time zone 'America/Caracas')::date;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Solo el captador oficial puede registrar evidencia'; end if;
 if p_value is null or p_value<=0 or p_value>=1000000 or p_value::text in ('NaN','Infinity','-Infinity')
 or p_value_date is null or p_value_date<today_local-14 or p_value_date>today_local+10
 or p_html is null or octet_length(p_html) not between 10 and 2000000 then raise exception 'Captura oficial inválida'; end if;
 perform pg_advisory_xact_lock(hashtextextended('lubricenter-bcv-official-observer',0));
 select usd_ves into prior_value from lubricenter_private.bcv_official_observations where value_date=p_value_date;
 if prior_value is not null and prior_value<>p_value then raise exception 'Conflicto en publicación oficial BCV para %',p_value_date; end if;
 select usd_ves into last_value from lubricenter_private.bcv_official_observations order by value_date desc limit 1;
 if last_value is not null and abs(p_value/last_value-1)>0.12 then raise exception 'Variación oficial BCV superior a 12%%: requiere revisión'; end if;
 insert into lubricenter_private.bcv_official_observations(value_date,usd_ves,source_url,evidence_sha256,evidence_html)
 values(p_value_date,p_value,'https://www.bcv.org.ve/',encode(sha256(convert_to(p_html,'UTF8')),'hex'),p_html)
 on conflict(value_date) do update set last_seen_at=now(),capture_count=bcv_official_observations.capture_count+1;
 insert into lubricenter_private.bcv_official_observer_state(id,last_attempt_at,last_success_at,last_error)
 values(true,now(),now(),null) on conflict(id) do update set last_attempt_at=now(),last_success_at=now(),last_error=null;
 -- The bridge is installed only with the coordinated native release.
 if to_regprocedure('lubricenter_private.bcv_promote_official_observation(date)') is not null then
  execute 'select lubricenter_private.bcv_promote_official_observation($1)' using p_value_date;
 end if;
 select jsonb_build_object('ok',true,'provider','BCV_OFFICIAL','usd_ves',usd_ves,'fecha_valor',value_date,
 'first_seen_at',first_seen_at,'last_seen_at',last_seen_at,'evidence_sha256',evidence_sha256,
 'mode',case when to_regprocedure('lubricenter_private.bcv_promote_official_observation(date)') is null then 'OBSERVER' else 'NATIVE_BRIDGE' end)
 into result from lubricenter_private.bcv_official_observations where value_date=p_value_date;
 return result;
end$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.bcv_official_record_failure(p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if auth.role() is distinct from 'service_role' then raise exception 'Solo el captador oficial'; end if;
 insert into lubricenter_private.bcv_official_observer_state(id,last_attempt_at,last_error)
 values(true,now(),left(p_error,400)) on conflict(id) do update set last_attempt_at=now(),last_error=excluded.last_error;
end$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.cancel_order(p_order_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.orders; m record; a record;
begin
 perform lubricenter_private.require_order_admin();
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Explica el motivo de la anulación (al menos 5 caracteres)'; end if;
 select * into o from public.orders where id=p_order_id for update;
 if not found then raise exception 'Venta no encontrada'; end if;
 if o.status='CANCELLED' then return; end if;
 -- Lock installment writers too; their functions lock installment then sale.
 perform 1 from public.cashea_installments where cashea_sale_id in(select id from public.cashea_sales where order_id=p_order_id) order by id for update;
 perform 1 from public.cashea_sales where order_id=p_order_id for update;
 perform 1 from public.receivables where order_id=p_order_id for update;
 perform set_config('lubricenter.order_id',p_order_id::text,true);
 perform set_config('lubricenter.reason',trim(p_reason),true);
 perform set_config('lubricenter.order_cancel_flow','yes',true);
 perform lubricenter_private.return_order_stock(p_order_id,'Anulación '||o.order_number||': '||p_reason);
 for m in select am.* from public.account_movements am join public.payments p on p.id=am.source_payment_id where p.order_id=p_order_id loop
  insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,note,reference,occurred_at)
  values(m.account_id,case when m.direction='IN' then 'OUT' else 'IN' end,'ADJUSTMENT',m.currency,m.amount_original,m.value_ves,'ORDER_REVERSAL','Anulación '||o.order_number||': '||p_reason,m.id::text,m.occurred_at);
 end loop;
 for a in select pa.* from public.payroll_accruals pa join public.order_items i on i.id=pa.source_order_item_id where i.order_id=p_order_id for update of pa loop
  if a.payroll_run_id is null then delete from public.payroll_accruals where id=a.id;
  elsif a.amount_ref>0 then
   insert into public.payroll_adjustments(employee_id,adjustment_type,amount_ref,note,occurred_on)
   values(a.employee_id,'OTHER',-a.amount_ref,'Reversión de comisión liquidada · '||o.order_number||' · '||p_reason,(now() at time zone 'America/Caracas')::date);
  end if;
 end loop;
 update public.receivables set status='CANCELLED',outstanding_ves=0,closed_at=now() where order_id=p_order_id;
 update public.cashea_sales set status='CANCELLED' where order_id=p_order_id;
 -- Suppress pending CRM without pretending that a message was sent.
 delete from public.customer_followups where order_id=p_order_id and status<>'SENT';
 update public.orders set status='CANCELLED',cancellation_reason=trim(p_reason),cancelled_at=now() where id=p_order_id;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('order.cancelled','order',p_order_id,jsonb_build_object('reason',p_reason,'cash_and_stock_reversed',true));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.cancel_order_to_balance(p_order_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.orders; m record; a record; p public.payments;
  v_pocket text; v_units numeric(18,2); v_entry uuid;
begin
  perform lubricenter_private.require_order_admin();
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Explica el motivo de la anulación (al menos 5 caracteres)'; end if;
  select * into o from public.orders where id=p_order_id for update;
  if not found then raise exception 'Venta no encontrada'; end if;
  if o.status='CANCELLED' then return; end if;
  if o.status<>'CLOSED' then raise exception 'Esta opción corresponde a ventas cerradas'; end if;
  if o.customer_id is null then raise exception 'Asocia un cliente antes de conservar el cobro como saldo a favor'; end if;
  if exists(select 1 from public.cashea_sales where order_id=p_order_id) then
    raise exception 'Las ventas Cashea requieren una revisión manual antes de crear saldo a favor';
  end if;
  if exists(select 1 from public.receivables where order_id=p_order_id) then
    raise exception 'La venta tiene Crédito LC; revisa sus cobros antes de anularla con saldo a favor';
  end if;
  perform set_config('lubricenter.order_id',p_order_id::text,true);
  perform set_config('lubricenter.reason',trim(p_reason),true);
  perform set_config('lubricenter.order_cancel_flow','yes',true);
 perform lubricenter_private.return_order_stock(p_order_id,'Anulación '||o.order_number||': '||p_reason);
  for a in select pa.* from public.payroll_accruals pa join public.order_items i
    on i.id=pa.source_order_item_id where i.order_id=p_order_id for update of pa loop
    if a.payroll_run_id is null then delete from public.payroll_accruals where id=a.id;
    elsif a.amount_ref>0 then
      insert into public.payroll_adjustments(employee_id,adjustment_type,amount_ref,note,occurred_on)
      values(a.employee_id,'OTHER',-a.amount_ref,
        'Reversión de comisión liquidada · '||o.order_number||' · '||p_reason,
        (now() at time zone 'America/Caracas')::date);
    end if;
  end loop;
  for p in select * from public.payments where order_id=p_order_id order by id loop
    if p.method in ('CUSTOMER_BALANCE_USD','CUSTOMER_BALANCE_BCV') then continue; end if;
    v_pocket:=case when p.currency='USD' then 'USD' else 'VES_BCV' end;
    v_units:=case when p.currency='USD' then p.amount_original
      else round(p.amount_original/p.bcv_rate_snapshot,2) end;
    if v_units<=0 then raise exception 'Un cobro es menor al mínimo acreditable; revisa la venta'; end if;
    insert into public.customer_balance_accounts(customer_id,pocket)
      values(o.customer_id,v_pocket) on conflict do nothing;
    perform 1 from public.customer_balance_accounts
      where customer_id=o.customer_id and pocket=v_pocket for update;
    update public.customer_balance_accounts set balance_usd=balance_usd+v_units,updated_at=now()
      where customer_id=o.customer_id and pocket=v_pocket;
    insert into public.customer_balance_movements(
      customer_id,pocket,movement_type,origin,delta_usd,amount_original,currency,value_ves,
      bcv_rate_snapshot,operative_rate_snapshot,method,reference,note,order_id,payment_id
    ) values (
      o.customer_id,v_pocket,'DEPOSIT','CANCELLED_SALE',v_units,p.amount_original,p.currency,p.value_ves,
      p.bcv_rate_snapshot,p.operative_rate_snapshot,p.method,p.reference,
      'Cobro conservado al anular '||o.order_number||' · '||trim(p_reason),p_order_id,p.id
    ) returning id into v_entry;
    insert into public.audit_events(event_type,entity_type,entity_id,data)
      values('customer_balance.cancelled_sale_credit','customer_balance_movement',v_entry,
        jsonb_build_object('order_id',p_order_id,'payment_id',p.id,'customer_id',o.customer_id,
          'pocket',v_pocket,'units_usd',v_units,'cash_movement_reversed',false));
  end loop;
  delete from public.customer_followups where order_id=p_order_id and status<>'SENT';
  update public.orders set status='CANCELLED',cancellation_reason=trim(p_reason),cancelled_at=now()
    where id=p_order_id;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
    values('order.cancelled','order',p_order_id,
      jsonb_build_object('reason',p_reason,'cash_and_stock_reversed',false,
        'cash_retained_as_customer_balance',true,'stock_reversed',true));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.capture_order_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b jsonb; a jsonb; d jsonb; oid uuid; actor text;
begin
 if TG_OP<>'INSERT' then b:=to_jsonb(old); end if;
 if TG_OP<>'DELETE' then a:=to_jsonb(new); end if;
 d:=coalesce(a,b);
 if TG_TABLE_NAME='orders' then oid:=(d->>'id')::uuid;
 elsif d ? 'order_id' then oid:=(d->>'order_id')::uuid;
 elsif TG_TABLE_NAME='inventory_movements' then select order_id into oid from public.order_items where id=(d->>'order_item_id')::uuid;
 elsif TG_TABLE_NAME='account_movements' then
  select order_id into oid from public.payments where id=(d->>'source_payment_id')::uuid;
  oid:=coalesce(oid,nullif(current_setting('lubricenter.order_id',true),'')::uuid);
 elsif TG_TABLE_NAME='payroll_accruals' then select order_id into oid from public.order_items where id=(d->>'source_order_item_id')::uuid;
 elsif TG_TABLE_NAME='cashea_installments' then select order_id into oid from public.cashea_sales where id=(d->>'cashea_sale_id')::uuid;
 else oid:=nullif(current_setting('lubricenter.order_id',true),'')::uuid;
 end if;
 if oid is not null and a is distinct from b then
  select email into actor from auth.users where id=auth.uid();
  insert into public.order_history(order_id,entity_type,entity_id,action,before_data,after_data,reason,actor_id,actor_email)
  values(oid,TG_TABLE_NAME,(d->>'id')::uuid,TG_OP,b,a,nullif(current_setting('lubricenter.reason',true),''),auth.uid(),actor);
 end if;
 return coalesce(new,old);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.catalog_prepare_inventory_item(p_product_id uuid, p_sku text, p_brand text DEFAULT NULL::text, p_unit text DEFAULT 'UND'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.products; item_id uuid;
begin
 perform lubricenter_private.require_order_admin();
 if not exists(select 1 from public.app_settings where key='catalog_authority' and value #>> '{}'='LUBRICENTER_OS') then
   raise exception 'La administración nativa del catálogo todavía no está activa';
 end if;
 if nullif(trim(p_sku),'') is null or length(trim(p_sku))>100
   or coalesce(p_unit,'') not in ('UND','L','GAL','KG') then
   raise exception 'Indica código y unidad válidos';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('catalog-inventory:'||lower(trim(p_sku))||':'||lower(trim(coalesce(p_brand,''))),0));
 select * into p from public.products where id=p_product_id for update;
 if not found then raise exception 'Producto no encontrado'; end if;
 select id into item_id from public.inventory_items where product_id=p_product_id limit 1;
 if item_id is not null then return item_id; end if;
 select id into item_id from public.inventory_items where lower(trim(sku))=lower(trim(p_sku))
   and lower(trim(coalesce(brand,'')))=lower(trim(coalesce(p_brand,''))) for update;
 if item_id is not null then
   if exists(select 1 from public.inventory_items where id=item_id and product_id is not null and product_id<>p_product_id) then
     raise exception 'Ese código ya está vinculado a otro producto';
   end if;
   update public.inventory_items set product_id=p_product_id,updated_at=now() where id=item_id;
 else
   insert into public.inventory_items(sku,brand,description,category,unit,product_id,
    source_cost_ref,source_stock_imported,needs_review,cost_missing,source_name)
   values(trim(p_sku),nullif(trim(p_brand),''),p.name,p.category,p_unit,p.id,0,0,true,true,'Lubricenter OS')
   returning id into item_id;
 end if;
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('catalog.inventory_prepared','inventory_item',item_id,jsonb_build_object('product_id',p.id,'stock_changed',false,'actor',auth.uid()));
 return item_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.catalog_register_invoice_items(p_supplier_name text, p_invoice_number text, p_currency text, p_invoice_date date, p_lines jsonb, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_intake uuid;v_row jsonb;v_name text;v_sku text;v_category text;
 v_quantity numeric;v_cost numeric;v_existing public.products%rowtype;
 v_id uuid;v_created integer:=0;v_matched integer:=0;
begin
 perform lubricenter_private.require_order_admin();
 if (select s.value#>>'{}' from public.app_settings s where key='catalog_authority')<>'LUBRICENTER_OS'
 then raise exception 'El catálogo todavía no se administra aquí'; end if;
 if length(btrim(coalesce(p_supplier_name,'')))<2 or length(btrim(p_supplier_name))>180
 or length(btrim(coalesce(p_invoice_number,'')))<1 or length(btrim(p_invoice_number))>100
 then raise exception 'Indica proveedor y número de factura'; end if;
 if p_currency not in ('USD','VES') then raise exception 'Moneda de factura inválida'; end if;
 if p_invoice_date> (now() at time zone 'America/Caracas')::date
 then raise exception 'Fecha de factura futura'; end if;
 if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<1 or jsonb_array_length(p_lines)>150
 then raise exception 'La factura debe contener entre 1 y 150 artículos'; end if;
 perform pg_advisory_xact_lock(hashtextextended('lubricenter-native-catalog',0));
 insert into public.catalog_invoice_intakes(supplier_name,invoice_number,currency,invoice_date,note,created_by)
 values(btrim(p_supplier_name),btrim(p_invoice_number),p_currency,p_invoice_date,
  nullif(btrim(coalesce(p_note,'')),''),auth.uid()) returning id into v_intake;
 for v_row in select value from jsonb_array_elements(p_lines) loop
   v_name:=btrim(coalesce(v_row->>'name',''));
   v_category:=nullif(btrim(coalesce(v_row->>'category','')),'');
   v_sku:=nullif(btrim(coalesce(v_row->>'sku','')),'');
   if length(v_name)<2 or length(v_name)>180 or length(coalesce(v_sku,''))>100 or length(coalesce(v_category,''))>120
   then raise exception 'Una línea tiene un nombre, código o categoría inválido'; end if;
   begin
    v_quantity:=(v_row->>'quantity')::numeric;
    v_cost:=(v_row->>'unit_cost')::numeric;
   exception when others then raise exception 'Revisa las cantidades y costos numéricos de la factura'; end;
   if v_quantity is null or v_quantity<=0 or v_quantity>1000000
      or v_cost is null or v_cost<0 or v_cost>1000000
   then raise exception 'Cantidad o costo inválido en %',v_name; end if;
   select * into v_existing from public.products where lower(btrim(name))=lower(v_name) limit 1;
   if found then
     v_id:=v_existing.id;v_matched:=v_matched+1;
   else
     insert into public.products(name,category,filter_code,cash_usd_base_price,
       active,available,catalog_source,notes)
     values(v_name,v_category,v_sku,0,false,false,'Lubricenter OS',
       'Pendiente de fijar precio de venta. Captado de factura '||p_invoice_number)
     returning id into v_id;
     insert into public.catalog_product_changes(product_id,actor_id,before_state,after_state)
     select v_id,auth.uid(),null,to_jsonb(p) from public.products p where id=v_id;
     v_created:=v_created+1;
   end if;
   insert into public.catalog_invoice_intake_lines(intake_id,product_id,sku,quantity_in_invoice,unit_cost_original,existing_catalog_product)
   values(v_intake,v_id,v_sku,v_quantity,v_cost,v_existing.id is not null);
   v_existing:=null;
 end loop;
 insert into public.audit_events(event_type,entity_type,entity_id,actor_id,data)
 values('catalog.invoice_intake','catalog_invoice_intakes',v_intake,auth.uid(),
   jsonb_build_object('supplier',p_supplier_name,'invoice',p_invoice_number,
   'created',v_created,'existing',v_matched,'lines',jsonb_array_length(p_lines),
   'not_posted_to_inventory',true,'not_posted_to_accounts',true));
 return jsonb_build_object('intake_id',v_intake,'created',v_created,'matched',v_matched,
 'stock_changed',false,'prices_changed',false);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.catalog_save_product(p_id uuid, p_name text, p_category text, p_filter_code text, p_usd numeric, p_notes text, p_image_url text, p_available boolean, p_active boolean, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.products%rowtype;v_new public.products%rowtype;
 v_name text:=btrim(coalesce(p_name,''));v_category text:=nullif(btrim(coalesce(p_category,'')),'');
 v_filter text:=nullif(btrim(coalesce(p_filter_code,'')),'');
 v_notes text:=nullif(btrim(coalesce(p_notes,'')),'');
 v_photo text:=nullif(btrim(coalesce(p_image_url,'')),'');
begin
 perform lubricenter_private.require_order_admin();
 if coalesce((select s.value #>> '{}' from public.app_settings s where s.key='catalog_authority'),'NOTION')<>'LUBRICENTER_OS'
 then raise exception 'El catálogo aún no es administrado por Lubricenter OS'; end if;
 if length(v_name)<2 or length(v_name)>180 then raise exception 'Nombre inválido: usa entre 2 y 180 caracteres'; end if;
 if length(coalesce(v_category,''))>120 or length(coalesce(v_filter,''))>100 or length(coalesce(v_notes,''))>3000
 then raise exception 'Categoría, código o descripción demasiado largos'; end if;
 if v_photo is not null and (length(v_photo)>1800 or v_photo !~* '^https://[^[:space:]]+$')
 then raise exception 'La fotografía debe tener una URL HTTPS válida'; end if;
 if p_usd is null or p_usd<0 or p_usd>1000000 or p_usd::text in ('NaN','Infinity','-Infinity')
 then raise exception 'Precio USD inválido'; end if;
 if coalesce(p_active,false) and coalesce(p_available,false) and p_usd<=0
 then raise exception 'No publiques un producto sin precio de venta'; end if;
 perform pg_advisory_xact_lock(hashtextextended('lubricenter-native-catalog',0));
 if p_id is not null then
  select * into v_old from public.products where id=p_id for update;
  if not found then raise exception 'El producto ya no existe'; end if;
  if p_expected_updated_at is null or p_expected_updated_at is distinct from v_old.updated_at
  then raise exception 'El artículo fue modificado: actualiza la página antes de guardar'; end if;
 end if;
 if exists(select 1 from public.products p
  where lower(btrim(p.name))=lower(v_name) and (p_id is null or p.id<>p_id))
 then raise exception 'Ya existe un producto con ese nombre'; end if;
 if p_id is null then
  insert into public.products(name,category,filter_code,cash_usd_base_price,notes,image_url,
   active,available,catalog_source)
  values(v_name,v_category,v_filter,p_usd,v_notes,v_photo,
   coalesce(p_active,true),coalesce(p_active,true) and coalesce(p_available,true),'Lubricenter OS')
  returning * into v_new;
 else
  update public.products set name=v_name,category=v_category,filter_code=v_filter,
   cash_usd_base_price=p_usd,notes=v_notes,image_url=v_photo,
   active=coalesce(p_active,false),
   available=coalesce(p_active,false) and coalesce(p_available,false),
   catalog_source='Lubricenter OS'
  where id=p_id returning * into v_new;
 end if;
 insert into public.catalog_product_changes(product_id,actor_id,before_state,after_state)
 values(v_new.id,auth.uid(),case when p_id is null then null else to_jsonb(v_old) end,to_jsonb(v_new));
 insert into public.audit_events(event_type,entity_type,entity_id,actor_id,data)
 values('catalog.product_saved','products',v_new.id,auth.uid(),
   jsonb_build_object('before',case when p_id is null then null else to_jsonb(v_old) end,'after',to_jsonb(v_new)));
 return jsonb_build_object('id',v_new.id,'new',p_id is null,'active',v_new.active,'name',v_new.name);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.catalog_stock_item(p_order uuid, p_product uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n int; iid uuid;
begin
 perform public.require_auth();
 select count(*),(array_agg(id order by id))[1] into n,iid
   from public.inventory_items where product_id=p_product and active and merged_into is null;
 if n>1 then raise exception 'Este producto de catálogo corresponde a varios SKU. Selecciona el código exacto desde inventario'; end if;
 return iid;
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.close_order_cashea(p_order_id uuid, p_initial_percent numeric, p_initial_payment_method text, p_payment_reference text DEFAULT NULL::text, p_cashea_reference text DEFAULT NULL::text, p_expected_total_ves numeric DEFAULT NULL::numeric, p_expected_total_ref numeric DEFAULT NULL::numeric, p_expected_bcv numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders; v_sale uuid; v_total_ref numeric; v_total_ves numeric;
  v_bcv numeric; v_op numeric; v_paid numeric; v_initial_ref numeric; v_initial_ves numeric;
  v_extra numeric; v_financed numeric; v_commission numeric; v_min numeric;
  v_method text := upper(coalesce(p_initial_payment_method,''));
  v_part numeric; v_date date := (now() at time zone 'America/Caracas')::date;
  i public.order_items;
begin
  perform public.require_auth();
  select * into v_order from public.orders where id=p_order_id for update;
  if not found then raise exception 'Orden no encontrada'; end if;
  select id into v_sale from public.cashea_sales where order_id=p_order_id;
  if v_sale is not null then return v_sale; end if;
  if v_order.status <> 'OPEN' then raise exception 'La orden ya está cerrada o cancelada'; end if;
  v_date := (coalesce(v_order.business_at,now()) at time zone 'America/Caracas')::date;
  perform public.validate_order_ready_to_close(p_order_id);
  if exists(select 1 from public.receivables where order_id=p_order_id) then raise exception 'La orden ya tiene Crédito LC. Revisa el registro antes de usar Cashea'; end if;
  if p_initial_percent is null or p_initial_percent <= 0 or p_initial_percent > 100 or p_initial_percent::text in ('NaN','Infinity','-Infinity') then raise exception 'Indica una inicial mayor que 0 y hasta 100 por ciento'; end if;
  if v_method not in ('CASH_USD','CASH_VES','MOBILE_PAYMENT','TRANSFER_BDV','TRANSFER_BNC') then raise exception 'Selecciona cómo recibiste la inicial'; end if;
  select coalesce(sum(charged_ref_amount),0),coalesce(sum(charged_ves_amount),0) into v_total_ref,v_total_ves from public.order_items where order_id=p_order_id;
  if v_total_ves<=0 then raise exception 'Agrega productos o trabajos antes de cobrar'; end if;
  if p_expected_total_ves is null or p_expected_total_ref is null or abs(p_expected_total_ves-v_total_ves)>0.01 or abs(p_expected_total_ref-v_total_ref)>0.0001 then raise exception 'El total cambió. Actualiza la orden y revisa la inicial antes de confirmar'; end if;
  select bcv_rate,operative_rate into v_bcv,v_op from public.get_order_rates(p_order_id);
  if v_bcv is null or v_bcv<=0 or v_op is null or v_op<=0 then raise exception 'Actualiza las tasas antes de cobrar con Cashea'; end if;
  if p_expected_bcv is null or p_expected_bcv<>v_bcv then raise exception 'La tasa BCV cambió. Vuelve a abrir Cashea para revisar la inicial'; end if;
  select coalesce((select (value #>> '{}')::numeric from public.app_settings where key='cashea_commission_percent'),4) into v_commission;
  select coalesce((select (value #>> '{}')::numeric from public.app_settings where key='cashea_minimum_ref'),25) into v_min;
  if v_total_ref<v_min then raise exception 'Cashea requiere al menos REF %',v_min; end if;
  v_initial_ref := round(v_total_ref*p_initial_percent/100,4);
  v_initial_ves := round(v_initial_ref*v_bcv,2);
  v_financed := round(v_total_ref-v_initial_ref,4);
  select coalesce(sum(value_ves),0) into v_paid from public.payments where order_id=p_order_id;
  if v_paid>v_initial_ves+0.01 then raise exception 'Los pagos registrados superan la inicial en Bs %. Ajusta el porcentaje o corrige el pago antes de confirmar',round(v_paid-v_initial_ves,2); end if;
  v_extra := greatest(round(v_initial_ves-v_paid,2),0);
  if v_extra>0 then
    insert into public.payments(order_id,method,currency,amount_original,bcv_rate_snapshot,operative_rate_snapshot,value_ves,value_ref,reference,paid_at)
    values(p_order_id,v_method,case when v_method='CASH_USD' then 'USD' else 'VES' end,case when v_method='CASH_USD' then round(v_extra/v_bcv,4) else v_extra end,v_bcv,v_op,v_extra,round(v_extra/v_bcv,4),nullif(trim(p_payment_reference),''),now());
  end if;
  insert into public.cashea_sales(order_id,status,initial_percent,commission_percent,gross_ref,gross_ves_snapshot,initial_ref,initial_ves_snapshot,financed_ref,commission_ref,commission_ves_snapshot,bcv_rate_snapshot,initial_payment_method,cashea_reference)
  values(p_order_id,case when v_financed<=0.01 then 'SETTLED' else 'ACTIVE' end,p_initial_percent,v_commission,v_total_ref,v_total_ves,v_initial_ref,v_initial_ves,v_financed,round(v_total_ref*v_commission/100,4),round(v_total_ref*v_commission/100*v_bcv,2),v_bcv,v_method,nullif(trim(p_cashea_reference),'')) returning id into v_sale;
  if v_financed>0.01 then
    v_part:=round(v_financed/3,4);
    insert into public.cashea_installments(cashea_sale_id,installment_no,due_date,amount_ref,amount_ves_snapshot)
    values(v_sale,1,v_date+14,v_part,round(v_part*v_bcv,2)),(v_sale,2,v_date+28,v_part,round(v_part*v_bcv,2)),(v_sale,3,v_date+42,v_financed-2*v_part,round((v_financed-2*v_part)*v_bcv,2));
  end if;
  update public.orders set status='CLOSED',closed_at=now(),total_ves=round(v_total_ves,2),total_ref=round(v_total_ref,4),total_cash_usd_equivalent=round((select coalesce(sum(charged_ves_amount/nullif(operative_rate_snapshot,0)),0) from public.order_items where order_id=p_order_id),4) where id=p_order_id;
  for i in select * from public.order_items where order_id=p_order_id loop
    if i.business_area='WORKSHOP' and coalesce(i.worker_share_ref_snapshot,0)>0 then
      insert into public.payroll_accruals(employee_id,source_order_item_id,source_type,amount_ref,description,occurred_at) values(i.worker_employee_id,i.id,'WORKSHOP_COMMISSION',i.worker_share_ref_snapshot,'Taller · '||i.description,now()) on conflict do nothing;
    end if;
    if i.business_area='WORKSHOP' and coalesce(i.assistant_bonus_ref_snapshot,0)>0 then
      insert into public.payroll_accruals(employee_id,source_order_item_id,source_type,amount_ref,description,occurred_at) values(i.assistant_bonus_employee_id,i.id,'ASSISTANT_BONUS',i.assistant_bonus_ref_snapshot,'Bono ayudante · '||i.description,now()) on conflict do nothing;
    end if;
    if i.business_area='ELECTROAUTO' and coalesce(i.worker_share_ref_snapshot,0)>0 then
      insert into public.payroll_accruals(employee_id,source_order_item_id,source_type,amount_ref,description,occurred_at) values(i.worker_employee_id,i.id,'ELECTROAUTO_COMMISSION',i.worker_share_ref_snapshot,'Electroauto · '||i.description,now()) on conflict do nothing;
    end if;
  end loop;
  insert into public.integration_events(event_type,aggregate_type,aggregate_id,payload) values('order.closed','order',p_order_id,jsonb_build_object('order_number',v_order.order_number,'payment_status','CASHEA','cashea_sale_id',v_sale,'total_ves',v_total_ves,'total_ref',v_total_ref));
  insert into public.audit_events(event_type,entity_type,entity_id,data) values('order.closed_cashea','order',p_order_id,jsonb_build_object('cashea_sale_id',v_sale,'initial_ref',v_initial_ref,'financed_ref',v_financed,'previous_payments_ves',v_paid));
  return v_sale;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.close_order_cashea_split(p_order_id uuid, p_initial_percent numeric, p_initial_payments jsonb, p_cashea_reference text, p_expected_total_ves numeric, p_expected_total_ref numeric, p_expected_bcv numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders;
  v_bcv numeric; v_op numeric;
  v_total_ves numeric; v_total_ref numeric; v_initial_ves numeric;
  v_paid numeric; v_new_paid numeric := 0;
  v_row jsonb; v_method text; v_amount_text text; v_amount numeric;
  v_ves numeric; v_currency text; v_reference text; v_code text; v_seen int := 0;
  v_sale_id uuid; v_label text; v_count int;
BEGIN
  PERFORM public.require_auth();
  IF p_order_id IS NULL THEN RAISE EXCEPTION 'Falta identificar la orden'; END IF;
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orden no encontrada'; END IF;
  IF EXISTS (SELECT 1 FROM public.cashea_sales WHERE order_id=p_order_id) THEN
    RAISE EXCEPTION 'Esta venta Cashea ya quedó registrada. Recarga la orden; no cobres nuevamente';
  END IF;
  IF v_order.status <> 'OPEN' THEN RAISE EXCEPTION 'La orden no está abierta'; END IF;
  PERFORM public.validate_order_ready_to_close(p_order_id);

  IF p_initial_percent IS NULL OR p_initial_percent::text IN ('NaN','Infinity','-Infinity')
    OR p_initial_percent<=0 OR p_initial_percent>100 THEN
    RAISE EXCEPTION 'La inicial aprobada debe estar entre 0 y 100 por ciento';
  END IF;
  IF p_cashea_reference IS NULL OR btrim(p_cashea_reference) !~ '^[0-9]{1,32}$' THEN
    RAISE EXCEPTION 'Registra el número de orden de Cashea (solo dígitos)';
  END IF;
  IF p_initial_payments IS NULL OR jsonb_typeof(p_initial_payments)<>'array' THEN
    RAISE EXCEPTION 'Envía el desglose de la inicial como lista';
  END IF;
  IF jsonb_array_length(p_initial_payments)>8 THEN
    RAISE EXCEPTION 'La inicial admite entre 0 y 8 formas de cobro';
  END IF;

  SELECT coalesce(sum(charged_ves_amount),0),coalesce(sum(charged_ref_amount),0)
    INTO v_total_ves,v_total_ref FROM public.order_items WHERE order_id=p_order_id;
  IF v_total_ves<=0 OR v_total_ref<=0 THEN RAISE EXCEPTION 'Orden sin artículos cobrables'; END IF;
  IF p_expected_total_ves IS NULL OR p_expected_total_ref IS NULL OR
     abs(v_total_ves-p_expected_total_ves)>0.01 OR
     abs(v_total_ref-p_expected_total_ref)>0.0001 THEN
    RAISE EXCEPTION 'El total de la orden cambió. Actualiza el cobro antes de confirmar';
  END IF;
  SELECT bcv_rate,operative_rate INTO v_bcv,v_op FROM public.get_order_rates(p_order_id);
  IF v_bcv IS NULL OR v_bcv<=0 OR v_op IS NULL OR v_op<=0 OR
     p_expected_bcv IS NULL OR p_expected_bcv<>v_bcv THEN
    RAISE EXCEPTION 'La tasa BCV cambió. Actualiza los importes de la inicial';
  END IF;
  v_initial_ves := round(round(v_total_ref*p_initial_percent/100,4)*v_bcv,2);
  SELECT coalesce(sum(value_ves),0) INTO v_paid FROM public.payments
    WHERE order_id=p_order_id;
  IF v_paid>v_initial_ves THEN
    RAISE EXCEPTION 'Los pagos anteriores superan la inicial de Cashea: revisa sus montos';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_initial_payments)
  LOOP
    v_seen:=v_seen+1;
    IF jsonb_typeof(v_row)<>'object' THEN
      RAISE EXCEPTION 'Cada cobro debe tener método y monto';
    END IF;
    v_method := upper(btrim(coalesce(v_row->>'method','')));
    v_amount_text := btrim(coalesce(v_row->>'amount',''));
    v_reference := nullif(btrim(coalesce(v_row->>'reference','')),'');
    IF v_method NOT IN ('TRANSFER_BDV','TRANSFER_BNC','CASH_VES','CASH_USD','ZELLE','BINANCE') THEN
      RAISE EXCEPTION 'Selecciona el banco o forma de pago exacta para cada cobro';
    END IF;
    IF v_amount_text !~ '^[0-9]{1,10}(\.[0-9]{1,2})?$' THEN
      RAISE EXCEPTION 'Cobro %: ingresa monto positivo con máximo dos decimales',v_seen;
    END IF;
    v_amount := v_amount_text::numeric;
    IF v_amount<=0 THEN RAISE EXCEPTION 'Cobro %: el monto debe ser mayor a cero',v_seen; END IF;
    IF v_method IN ('TRANSFER_BDV','TRANSFER_BNC') AND
       (v_reference IS NULL OR v_reference !~ '^[0-9]{4,32}$') THEN
      RAISE EXCEPTION 'Cobro %: registra al menos los últimos 4 dígitos de la referencia bancaria',v_seen;
    END IF;
    IF v_method IN ('ZELLE','BINANCE') AND
       (v_reference IS NULL OR length(v_reference)<4 OR length(v_reference)>100) THEN
      RAISE EXCEPTION 'Cobro %: registra la referencia de Zelle o Binance',v_seen;
    END IF;
    IF length(coalesce(v_reference,''))>100 THEN
      RAISE EXCEPTION 'Cobro %: referencia demasiado larga',v_seen;
    END IF;
    v_currency := CASE WHEN v_method IN ('CASH_USD','ZELLE','BINANCE') THEN 'USD' ELSE 'VES' END;
    v_code := CASE v_method
      WHEN 'TRANSFER_BDV' THEN 'BDV' WHEN 'TRANSFER_BNC' THEN 'BNC'
      ELSE v_method END;
    IF NOT EXISTS (SELECT 1 FROM public.financial_accounts
                   WHERE code=v_code AND active AND currency=v_currency) THEN
      RAISE EXCEPTION 'La cuenta % no está activa o su moneda no corresponde al pago',v_code;
    END IF;
    v_ves := CASE WHEN v_currency='USD' THEN round(v_amount*v_bcv,2)
                  ELSE v_amount END;
    IF v_ves<=0 THEN RAISE EXCEPTION 'El monto convertido del cobro es inválido'; END IF;
    v_new_paid := v_new_paid+v_ves;
    IF v_paid+v_new_paid>v_initial_ves THEN
      RAISE EXCEPTION 'Los cobros superan la inicial aprobada. Revisa el desglose';
    END IF;
    -- Los USD de la inicial Cashea se valoran a BCV, NO a tasa operativa.
    -- Triggers existentes seleccionan cuenta y generan exactamente un movimiento.
    INSERT INTO public.payments(
      order_id,method,currency,amount_original,bcv_rate_snapshot,
      operative_rate_snapshot,value_ves,value_ref,reference,paid_at
    ) VALUES(
      p_order_id,v_method,v_currency,v_amount,v_bcv,v_op,v_ves,
      round(v_ves/v_bcv,4),v_reference,now()
    );
  END LOOP;
  IF v_paid+v_new_paid<>v_initial_ves THEN
    RAISE EXCEPTION 'La inicial no cuadra: falta Bs %. Completa o ajusta los cobros',
      round(v_initial_ves-v_paid-v_new_paid,2);
  END IF;
  SELECT count(DISTINCT method),min(method)
    INTO v_count,v_label FROM public.payments WHERE order_id=p_order_id;
  IF v_count=0 THEN RAISE EXCEPTION 'La inicial no tiene pagos registrados'; END IF;
  IF v_count>1 OR v_label NOT IN ('CASH_USD','CASH_VES','MOBILE_PAYMENT','TRANSFER_BDV','TRANSFER_BNC','ZELLE','BINANCE') THEN v_label:='MIXED'; END IF;

  -- El cierre probado calcula comisión/cuotas, no agrega pago porque ya
  -- fue cubierta EXACTAMENTE la inicial (0 de remanente).
  SELECT lubricenter_private.close_order_cashea(
    p_order_id,p_initial_percent,'TRANSFER_BDV',NULL,p_cashea_reference,
    p_expected_total_ves,p_expected_total_ref,p_expected_bcv
  ) INTO v_sale_id;
  UPDATE public.cashea_sales SET initial_payment_method=v_label WHERE id=v_sale_id;
  INSERT INTO public.audit_events(event_type,entity_type,entity_id,data)
  VALUES ('cashea.initial_split','cashea_sale',v_sale_id,
    jsonb_build_object('order_id',p_order_id,'initial_ves',v_initial_ves,
      'previous_payments_ves',v_paid,'new_payments_ves',v_new_paid,
      'initial_payment_method',v_label,'new_payment_count',v_seen));
  RETURN v_sale_id;
END;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.collect_order_tender(p_request uuid, p_order uuid, p_method text, p_received numeric, p_return_usd numeric, p_return_currency text, p_change_rate numeric, p_reference text DEFAULT NULL::text, p_customer_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.orders; t public.order_tenders; pid uuid; payload jsonb; b numeric; rate numeric; remaining numeric; applied numeric; covered numeric; change numeric; currency text; a uuid; fixed_usd boolean; due numeric;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 payload:=jsonb_build_array(p_order,p_method,p_received,p_return_usd,p_return_currency,p_change_rate,p_reference,p_customer_label);
 if p_request is null then raise exception 'Falta el identificador del cobro'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,0));
 select * into t from public.order_tenders where id=p_request;
 if found then
  if t.request_payload<>payload then raise exception 'Solicitud reutilizada con otros datos'; end if;
  return t.payment_id;
 end if;
 -- Same lock as cash close: a count cannot certify half a collection.
 perform pg_advisory_xact_lock(220033);
 select * into o from public.orders where id=p_order for update;
 if not found or o.status<>'OPEN' then raise exception 'La orden debe estar abierta'; end if;
 if p_method is null or p_method not in ('CASH_USD','CASH_VES','TRANSFER_BDV','TRANSFER_BNC','ZELLE','BINANCE') then raise exception 'Método inválido'; end if;
 if p_method in ('TRANSFER_BDV','TRANSFER_BNC') and coalesce(trim(p_reference),'') !~ '^[0-9]{4,32}$' then raise exception 'Faltan los últimos 4 de referencia'; end if;
 if p_received is null or p_received<=0 or p_received::text in ('NaN','Infinity','-Infinity') or round(p_received,2)<>p_received then raise exception 'Monto recibido inválido'; end if;
 if p_change_rate is null or p_change_rate<=0 or p_change_rate::text in ('NaN','Infinity','-Infinity') or round(p_change_rate,6)<>p_change_rate then raise exception 'Indica la tasa acordada para el vuelto'; end if;
 if p_return_usd is null or p_return_usd<0 or p_return_usd::text in ('NaN','Infinity','-Infinity') or round(p_return_usd,2)<>p_return_usd then raise exception 'Monto de vuelto inválido'; end if;
 select bcv_rate,public.order_usd_rate(p_order) into b,rate from public.get_order_rates(p_order);
 if b is null or b<=0 or rate is null or rate<=0 then raise exception 'Faltan tasas para cobrar'; end if;
 currency:=case when p_method in ('CASH_USD','ZELLE','BINANCE') then 'USD' else 'VES' end;
 select coalesce(sum(charged_ves_amount),0)-(select coalesce(sum(value_ves),0) from public.payments where order_id=p_order) into remaining from public.order_items where order_id=p_order;
 if remaining<=0 then raise exception 'La orden ya está cubierta'; end if;
 -- Round the commercial USD amount once. Covered Bs are bounded to the sale,
 -- including the unavoidable sub-cent equivalence difference.
 select bool_and(price_denomination='USD') into fixed_usd from public.order_items where order_id=p_order;
 if currency='VES' and fixed_usd and p_change_rate<>b then raise exception 'El pago en Bs usa la tasa BCV completa: %',b; end if;
 due:=case when currency='USD' then round(remaining/rate,2) when fixed_usd then round(remaining/rate*p_change_rate,2) else round(remaining,2) end;
 if p_method not in ('CASH_USD','CASH_VES') and (p_return_usd<>0 or p_received>due) then raise exception 'El pago digital supera el saldo. Corrige el monto o el precio antes de cobrar'; end if;
 applied:=least(p_received,due);
 if applied<=0 then raise exception 'El pendiente es menor que un centavo; revisa el cierre'; end if;
 covered:=case when p_received>=due then remaining when currency='USD' then round(applied*rate,2) when fixed_usd then round(applied/p_change_rate*rate,2) else applied end;
 change:=case when currency='USD' then p_received-applied else round((p_received-applied)/p_change_rate,2) end;
 if p_return_usd>change then raise exception 'El vuelto entregado supera el sobrante'; end if;
 if change>p_return_usd and o.customer_id is null and length(trim(coalesce(p_customer_label,'')))<3 then raise exception 'Identifica al cliente para no perder el vuelto pendiente'; end if;
 insert into public.payments(order_id,method,currency,amount_original,bcv_rate_snapshot,operative_rate_snapshot,value_ves,value_ref,reference)
 values(p_order,p_method,currency,applied,b,rate,covered,round(covered/b,4),nullif(trim(p_reference),'')) returning id into pid;
 select financial_account_id into a from public.payments where id=pid;
 insert into public.order_tenders(id,order_id,payment_id,customer_id,customer_label,method,currency,received,applied,payment_rate,change_usd,change_rate,rounding_ves,request_payload)
 values(p_request,p_order,pid,o.customer_id,coalesce(nullif(trim(p_customer_label),''),'Cliente de '||o.order_number),p_method,currency,p_received,applied,rate,change,p_change_rate,case when currency='VES' then round(p_received-applied-change*p_change_rate,2) else 0 end,payload);
 if p_received>applied then
  insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,note,reference,finance_nature,finance_request_id,tender_id)
  values(a,'IN','ADJUSTMENT',currency,p_received-applied,round((p_received-applied)*case when currency='USD' then rate else 1 end,2),'Vuelto recibido','Dinero recibido que no pertenece a la venta',p_reference,'REFUND',p_request,p_request);
 end if;
 -- Coverage uses the sale's frozen valuation. A Bs cash/bank movement uses
 -- the actual Bs handed over, never that bookkeeping equivalence.
 update public.account_movements set tender_id=p_request,value_ves=case when public.account_movements.currency='VES' then applied else public.account_movements.value_ves end where source_payment_id=pid;
 if p_return_usd>0 then perform lubricenter_private.return_order_change(gen_random_uuid(),p_request,p_return_usd,p_return_currency,p_change_rate,'Vuelto entregado al cobrar'); end if;
 return pid;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.complete_prepared_cashea(p_request uuid, p_order_id uuid, p_initial_percent numeric, p_initial_payments jsonb, p_cashea_reference text, p_expected_total_ves numeric, p_expected_total_ref numeric, p_expected_bcv numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.sale_operation_requests; payload jsonb:=jsonb_build_array(p_order_id,p_initial_percent,p_initial_payments,p_cashea_reference,p_expected_total_ves,p_expected_total_ref,p_expected_bcv); result jsonb; sale uuid;
begin
 perform public.require_auth();
 if p_request is null then raise exception 'Falta el identificador del cobro'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,99));
 select * into previous from public.sale_operation_requests where id=p_request;
 if found then
  if previous.actor_id<>auth.uid() or previous.kind<>'CASHEA' or previous.payload<>payload then raise exception 'Solicitud reutilizada con otros datos'; end if;
  return previous.result;
 end if;
 sale:=lubricenter_private.close_order_cashea_split(p_order_id,p_initial_percent,p_initial_payments,p_cashea_reference,p_expected_total_ves,p_expected_total_ref,p_expected_bcv);
 select jsonb_build_object('order_id',o.id,'order_number',o.order_number,'total_ves',o.total_ves,'total_ref',o.total_ref,'initial_ref',s.initial_ref,'financed_ref',s.financed_ref,'commission_ref',s.commission_ref) into result from public.orders o join public.cashea_sales s on s.id=sale where o.id=p_order_id;
 insert into public.sale_operation_requests values(p_request,auth.uid(),'CASHEA',payload,result,now());
 return result;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.correct_cashea_initial(p_order_id uuid, p_reason text, p_initial_percent numeric, p_lines jsonb, p_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 o public.orders%ROWTYPE; s public.cashea_sales%ROWTYPE;
 old_s jsonb; old_payments jsonb; old_installments jsonb;
 line jsonb; pay public.payments%ROWTYPE; movement public.account_movements%ROWTYPE;
 account_uuid uuid; pay_uuid uuid; old_id uuid;
 v_method text; ref text; currency_code text; account_code text;
 input_amount numeric; equivalent numeric; new_initial numeric; new_ves numeric; new_financed numeric;
 amount_1 numeric; amount_3 numeric; gross_paid numeric:=0;
 updated_count integer:=0; created_count integer:=0; deleted_count integer:=0;
 line_ids uuid[]:=ARRAY[]::uuid[]; initial_ids uuid[]:=ARRAY[]::uuid[];
 old_payment_ids uuid[]:=ARRAY[]::uuid[]; installment_row public.cashea_installments%ROWTYPE;
 initial_method text; snapshot_date timestamptz; operative_rate numeric;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 IF NOT p_confirmed THEN RAISE EXCEPTION 'Confirma expresamente la rectificación del dinero real recibido'; END IF;
 IF length(btrim(coalesce(p_reason,'')))<8 THEN RAISE EXCEPTION 'Describe la causa de la corrección (mínimo ocho caracteres)'; END IF;
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)<1
   OR jsonb_array_length(p_lines)>8 THEN RAISE EXCEPTION 'Indica entre uno y ocho cobros de la inicial'; END IF;
 SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.status<>'CLOSED' THEN RAISE EXCEPTION 'Solo se rectifican órdenes cerradas'; END IF;
 SELECT * INTO s FROM public.cashea_sales WHERE order_id=o.id FOR UPDATE;
 IF NOT FOUND OR s.status NOT IN ('ACTIVE','SETTLED') OR s.ownership_status<>'OWN'
 THEN RAISE EXCEPTION 'No hay una operación Cashea propia y vigente para esta orden'; END IF;
 IF p_initial_percent IS NULL OR p_initial_percent<=0 OR p_initial_percent>=100
 OR p_initial_percent::text IN ('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'La inicial debe ser mayor que cero y menor que 100 por ciento'; END IF;
 IF s.bcv_rate_snapshot<=0 THEN RAISE EXCEPTION 'La tasa BCV original no es válida'; END IF;
 -- This correction MUST NOT invalidate a bank match, settled installment or documented change.
 IF EXISTS (SELECT 1 FROM public.reconciliation_allocations a
   WHERE a.reversed_at IS NULL AND (a.cashea_sale_id=s.id
    OR a.cashea_installment_id IN (SELECT id FROM public.cashea_installments WHERE cashea_sale_id=s.id)))
 THEN RAISE EXCEPTION 'Cashea ya tiene conciliaciones; revísalas antes de rectificar la inicial'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.installment_no),'[]'::jsonb) INTO old_installments
 FROM public.cashea_installments i WHERE i.cashea_sale_id=s.id;
 SELECT array_agg(p.id),coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.paid_at),'[]'::jsonb),min(p.paid_at),
        max(p.operative_rate_snapshot)
 INTO old_payment_ids,old_payments,snapshot_date,operative_rate
 FROM public.payments p WHERE p.order_id=o.id
   AND NOT EXISTS (SELECT 1 FROM public.audit_events a
      WHERE a.event_type='cashea.installment_payment_recorded' AND a.data->>'payment_id'=p.id::text)
   AND p.receivable_id IS NULL;
 IF old_payment_ids IS NULL THEN RAISE EXCEPTION 'No se encontraron cobros iniciales para corregir'; END IF;
 IF EXISTS(SELECT 1 FROM public.order_tenders t WHERE t.order_id=o.id
            AND t.payment_id=ANY(old_payment_ids))
 THEN RAISE EXCEPTION 'La orden contiene un vuelto documentado; necesita devolución auditada'; END IF;
 IF EXISTS(SELECT 1 FROM public.reconciliation_allocations a
   JOIN public.account_movements m ON m.id=a.account_movement_id
   WHERE a.reversed_at IS NULL AND m.source_payment_id=ANY(old_payment_ids))
 THEN RAISE EXCEPTION 'Un cobro está conciliado; deshaz su asignación antes de rectificar'; END IF;
 PERFORM 1 FROM public.payments p WHERE p.id=ANY(old_payment_ids) ORDER BY p.id FOR UPDATE;
 PERFORM 1 FROM public.account_movements m WHERE m.source_payment_id=ANY(old_payment_ids) ORDER BY m.id FOR UPDATE;
 PERFORM 1 FROM public.cashea_installments i WHERE i.cashea_sale_id=s.id ORDER BY i.id FOR UPDATE;
 old_s:=to_jsonb(s);
 new_initial:=round(s.gross_ref*p_initial_percent/100,4);
 new_ves:=round(new_initial*s.bcv_rate_snapshot,2);
 new_financed:=s.gross_ref-new_initial;
 amount_1:=round(new_financed/3,4);
 amount_3:=new_financed-2*amount_1;
 IF amount_1<=0 OR amount_3<=0 THEN RAISE EXCEPTION 'Las tres cuotas restantes deben ser positivas'; END IF;
 IF EXISTS(SELECT 1 FROM public.cashea_installments i WHERE i.cashea_sale_id=s.id AND
   (CASE WHEN i.installment_no=3 THEN amount_3 ELSE amount_1 END)<i.paid_ref)
 THEN RAISE EXCEPTION 'La nueva inicial reduciría una cuota por debajo de lo ya pagado'; END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
   v_method:=line->>'method'; ref:=nullif(btrim(coalesce(line->>'reference','')),'');
   IF v_method NOT IN ('TRANSFER_BDV','TRANSFER_BNC','CASH_VES','CASH_USD','ZELLE','BINANCE')
   THEN RAISE EXCEPTION 'Método de cobro de inicial no admitido'; END IF;
   input_amount:=(line->>'amount')::numeric;
   IF input_amount IS NULL OR input_amount<=0 OR input_amount::text IN ('NaN','Infinity','-Infinity')
       OR round(input_amount,2)<>input_amount THEN RAISE EXCEPTION 'Monto de inicial inválido'; END IF;
   IF v_method IN ('TRANSFER_BDV','TRANSFER_BNC') AND coalesce(ref,'') !~ '^\d{4,32}$'
   THEN RAISE EXCEPTION 'Cada pago bancario necesita al menos los últimos cuatro dígitos'; END IF;
   IF v_method IN ('ZELLE','BINANCE') AND length(coalesce(ref,''))<4
   THEN RAISE EXCEPTION 'El cobro electrónico necesita referencia'; END IF;
   currency_code:=CASE WHEN v_method IN ('CASH_USD','ZELLE','BINANCE') THEN 'USD' ELSE 'VES' END;
   account_code:=CASE WHEN v_method='TRANSFER_BDV' THEN 'BDV'
                      WHEN v_method='TRANSFER_BNC' THEN 'BNC' ELSE v_method END;
   SELECT id INTO account_uuid FROM public.financial_accounts WHERE code=account_code AND active;
   IF account_uuid IS NULL THEN RAISE EXCEPTION 'Cuenta financiera no disponible: %',account_code; END IF;
   equivalent:=CASE WHEN currency_code='USD' THEN round(input_amount*s.bcv_rate_snapshot,2) ELSE input_amount END;
   gross_paid:=gross_paid+equivalent;
   old_id:=nullif(line->>'source_id','')::uuid;
   IF old_id IS NOT NULL THEN
     IF old_id=ANY(line_ids) OR NOT (old_id=ANY(old_payment_ids))
     THEN RAISE EXCEPTION 'Cobro inicial repetido o ajeno a esta venta'; END IF;
     line_ids:=array_append(line_ids,old_id);
     SELECT * INTO pay FROM public.payments WHERE id=old_id FOR UPDATE;
     UPDATE public.payments SET method=v_method, currency=currency_code,amount_original=input_amount,
         value_ves=equivalent,value_ref=round(equivalent/s.bcv_rate_snapshot,4),
         reference=ref,financial_account_id=account_uuid
       WHERE id=old_id;
     UPDATE public.account_movements SET account_id=account_uuid,currency=currency_code,
         amount_original=input_amount,value_ves=equivalent,reference=ref
       WHERE source_payment_id=old_id;
     IF NOT FOUND THEN RAISE EXCEPTION 'El pago no tiene movimiento financiero asociado'; END IF;
     updated_count:=updated_count+1;
   ELSE
     INSERT INTO public.payments(order_id,method,currency,amount_original,
       bcv_rate_snapshot,operative_rate_snapshot,value_ves,value_ref,reference,
       financial_account_id,paid_at,created_by)
     VALUES(o.id,v_method,currency_code,input_amount,s.bcv_rate_snapshot,
       coalesce(operative_rate,s.bcv_rate_snapshot),equivalent,
       round(equivalent/s.bcv_rate_snapshot,4),ref,account_uuid,
       coalesce(snapshot_date,s.created_at),auth.uid())
     RETURNING id INTO pay_uuid;
     created_count:=created_count+1;
   END IF;
 END LOOP;
 IF abs(gross_paid-new_ves)>greatest(1,round(s.bcv_rate_snapshot*0.5,2)) THEN
    RAISE EXCEPTION 'La inicial simulada (Bs %) no corresponde al % por ciento (Bs %). Comprueba porcentaje e importes',
       gross_paid,p_initial_percent,new_ves;
 END IF;
 -- Delete ONLY an old initial line explicitly omitted from the new split.
 FOREACH pay_uuid IN ARRAY old_payment_ids LOOP
   IF NOT (pay_uuid=ANY(line_ids)) THEN
     DELETE FROM public.account_movements WHERE source_payment_id=pay_uuid;
     DELETE FROM public.payments WHERE id=pay_uuid;
     deleted_count:=deleted_count+1;
   END IF;
 END LOOP;
 SELECT CASE WHEN count(DISTINCT p.method)=1 THEN min(p.method) ELSE 'MIXED' END
 INTO initial_method
 FROM public.payments p WHERE p.order_id=o.id AND p.receivable_id IS NULL
   AND NOT EXISTS (SELECT 1 FROM public.audit_events a
        WHERE a.event_type='cashea.installment_payment_recorded' AND a.data->>'payment_id'=p.id::text);
 UPDATE public.cashea_sales SET initial_percent=p_initial_percent,initial_ref=new_initial,
   initial_ves_snapshot=new_ves,financed_ref=new_financed,initial_payment_method=initial_method
 WHERE id=s.id;
 UPDATE public.cashea_installments i SET
   amount_ref=CASE WHEN installment_no=3 THEN amount_3 ELSE amount_1 END,
   amount_ves_snapshot=round((CASE WHEN installment_no=3 THEN amount_3 ELSE amount_1 END)*s.bcv_rate_snapshot,2),
   status=CASE WHEN (CASE WHEN installment_no=3 THEN amount_3 ELSE amount_1 END)-i.paid_ref<=0.0001
     THEN 'PAID' WHEN i.paid_ref>0 THEN 'PARTIAL' ELSE 'PENDING' END
 WHERE cashea_sale_id=s.id;
 INSERT INTO public.audit_events(event_type,entity_type,entity_id,actor_id,data)
 VALUES ('cashea.initial_correction','order',o.id,auth.uid(),jsonb_build_object(
  'reason',btrim(p_reason),'before_sale',old_s,'before_initial_payments',old_payments,
  'before_installments',old_installments,'after_initial_percent',p_initial_percent,
  'after_initial_ref',new_initial,'after_initial_ves',new_ves,'received_ves',gross_paid,
  'after_lines',p_lines,'payments_updated',updated_count,'payments_added',created_count,
  'payments_removed',deleted_count,'sale_recreated',false,'bank_refund',false));
 RETURN jsonb_build_object('ok',true,'order_id',o.id,'cashea_sale_id',s.id,
    'initial_ref',new_initial,'financed_ref',new_financed,'received_ves',gross_paid,
    'updated',updated_count,'added',created_count,'removed',deleted_count);
END
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.correct_closed_oil_service(p_order_id uuid, p_service_item_id uuid, p_vehicle_id uuid, p_odometer integer, p_oil_brand text, p_oil_viscosity text, p_oil_liters numeric, p_filter_code text, p_next_service_odometer integer, p_next_service_date date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_order public.orders%rowtype;v_item public.order_items%rowtype;
 v_original jsonb;v_created boolean:=false;v_id uuid;v_vehicle public.vehicles%rowtype;
 v_snap public.order_items%rowtype;v_followup uuid;v_crm_count integer;
 v_day date:=(now() at time zone 'America/Caracas')::date;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 IF length(btrim(coalesce(p_reason,'')))<8 OR length(p_reason)>800 THEN
   RAISE EXCEPTION 'Describe la corrección y su motivo (8 a 800 caracteres)';
 END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR v_order.status<>'CLOSED' THEN
   RAISE EXCEPTION 'Esta corrección conserva cobros y requiere una orden cerrada';
 END IF;
 IF v_order.customer_id IS NULL OR v_order.is_walk_in THEN
   RAISE EXCEPTION 'El servicio requiere una orden con cliente identificado';
 END IF;
 SELECT * INTO v_vehicle FROM public.vehicles WHERE id=p_vehicle_id FOR UPDATE;
 IF NOT FOUND OR v_vehicle.customer_id IS NULL THEN
   RAISE EXCEPTION 'Selecciona un vehículo y su propietario para generar el CRM correcto';
 END IF;
 IF p_odometer IS NULL OR p_odometer<0 OR p_odometer>9999999 THEN
   RAISE EXCEPTION 'Kilometraje actual inválido';
 END IF;
 IF length(btrim(coalesce(p_oil_brand,'')))<2 OR length(p_oil_brand)>150 THEN
   RAISE EXCEPTION 'Indica el aceite utilizado';
 END IF;
 IF length(coalesce(p_oil_viscosity,''))>80 OR length(coalesce(p_filter_code,''))>100
 OR p_oil_liters IS NOT NULL AND (p_oil_liters<=0 OR p_oil_liters>100 OR p_oil_liters::text='NaN') THEN
   RAISE EXCEPTION 'Viscosidad, filtro o litros inválidos';
 END IF;
 IF p_next_service_odometer IS NULL AND p_next_service_date IS NULL THEN
   RAISE EXCEPTION 'Indica el próximo servicio por fecha o kilometraje';
 END IF;
 IF p_next_service_odometer IS NOT NULL AND
   (p_next_service_odometer<=p_odometer OR p_next_service_odometer>9999999) THEN
   RAISE EXCEPTION 'El próximo kilometraje debe ser mayor al actual';
 END IF;
 IF p_next_service_date IS NOT NULL AND p_next_service_date < v_day-interval '10 years' THEN
   RAISE EXCEPTION 'Fecha del próximo servicio inválida';
 END IF;

 IF p_service_item_id IS NOT NULL THEN
  SELECT * INTO v_item FROM public.order_items
  WHERE id=p_service_item_id AND order_id=p_order_id
    AND item_type='SERVICE' AND business_area='OIL_CHANGE' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La línea no es un cambio de aceite de esta orden'; END IF;
  v_original:=to_jsonb(v_item);
  v_id:=v_item.id;
 ELSE
  IF EXISTS(SELECT 1 FROM public.order_items i WHERE i.order_id=p_order_id
     AND i.item_type='SERVICE' AND i.business_area='OIL_CHANGE'
     AND coalesce(i.service_vehicle_id,v_order.vehicle_id)=p_vehicle_id)
  THEN RAISE EXCEPTION 'Ya existe un cambio de aceite para este carro en la orden; corrige esa línea'; END IF;
  SELECT * INTO v_snap FROM public.order_items
  WHERE order_id=p_order_id ORDER BY created_at LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orden sin artículos originales'; END IF;
  INSERT INTO public.order_items(order_id,item_type,business_area,description,quantity,
   pricing_mode,base_ref_amount,customer_ref_amount,charged_ves_amount,
   charged_ref_amount,bcv_rate_snapshot,operative_rate_snapshot,
   service_vehicle_id,service_odometer,oil_brand,oil_viscosity,oil_quantity_liters,
   oil_filter_code,next_service_odometer,next_service_date)
  VALUES(p_order_id,'SERVICE','OIL_CHANGE','Cambio de aceite',1,'STANDARD',0,0,0,0,
   v_snap.bcv_rate_snapshot,v_snap.operative_rate_snapshot,p_vehicle_id,p_odometer,
   btrim(p_oil_brand),nullif(btrim(coalesce(p_oil_viscosity,'')),''),
   p_oil_liters,nullif(btrim(coalesce(p_filter_code,'')),''),
   p_next_service_odometer,p_next_service_date)
  RETURNING id INTO v_id;
  v_created:=true;
 END IF;
 IF NOT v_created THEN
  UPDATE public.order_items SET service_vehicle_id=p_vehicle_id,service_odometer=p_odometer,
   oil_brand=btrim(p_oil_brand),oil_viscosity=nullif(btrim(coalesce(p_oil_viscosity,'')),''),
   oil_quantity_liters=p_oil_liters,
   oil_filter_code=nullif(btrim(coalesce(p_filter_code,'')),''),
   next_service_odometer=p_next_service_odometer,next_service_date=p_next_service_date
  WHERE id=v_id;
 END IF;
 SELECT * INTO v_item FROM public.order_items WHERE id=v_id;
 INSERT INTO public.service_records(
  order_id,order_item_id,customer_id,vehicle_id,service_type,description,odometer,
  oil_brand,oil_viscosity,oil_quantity_liters,oil_filter_code,
  next_service_odometer,next_service_date,charged_ref_amount,charged_ves_amount,
  performed_at,created_by
 ) VALUES(p_order_id,v_id,v_vehicle.customer_id,p_vehicle_id,'OIL_CHANGE',
  v_item.description,p_odometer,v_item.oil_brand,v_item.oil_viscosity,v_item.oil_quantity_liters,
  v_item.oil_filter_code,v_item.next_service_odometer,v_item.next_service_date,
  v_item.charged_ref_amount,v_item.charged_ves_amount,coalesce(v_order.closed_at,now()),
  auth.uid())
 ON CONFLICT(order_item_id) DO UPDATE SET
  customer_id=excluded.customer_id,vehicle_id=excluded.vehicle_id,
  description=excluded.description,odometer=excluded.odometer,
  oil_brand=excluded.oil_brand,oil_viscosity=excluded.oil_viscosity,
  oil_quantity_liters=excluded.oil_quantity_liters,oil_filter_code=excluded.oil_filter_code,
  next_service_odometer=excluded.next_service_odometer,next_service_date=excluded.next_service_date;

 UPDATE public.vehicles SET
   current_odometer=greatest(coalesce(current_odometer,0),p_odometer),
   updated_at=now()
 WHERE id=p_vehicle_id;

 v_followup:=lubricenter_private.upsert_vehicle_crm(p_order_id,p_vehicle_id,true);
 INSERT INTO public.integration_events(event_type,aggregate_type,aggregate_id,payload)
 VALUES('vehicle.service_history_updated','vehicle',p_vehicle_id,
  jsonb_build_object('order_id',p_order_id,'corrected',true,'service_item_id',v_id,
   'next_service_odometer',p_next_service_odometer,'next_service_date',p_next_service_date));

 INSERT INTO public.audit_events(event_type,entity_type,entity_id,actor_id,data)
 VALUES('order.service_corrected','order_item',v_id,auth.uid(),
  jsonb_build_object('reason',btrim(p_reason),'order_id',p_order_id,
   'vehicle_id',p_vehicle_id,'previous',v_original,'after',to_jsonb(v_item),
   'price_unchanged',true,'payments_unchanged',true,'stock_unchanged',true,
   'cashea_unchanged',true,'followup_id',v_followup));
 RETURN jsonb_build_object('ok',true,'created_service',v_created,'item_id',v_id,
   'followup_id',v_followup,'cashea_and_payments_unchanged',true);
END $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.correct_closed_order(p_order_id uuid, p_reason text, p_business_at timestamp with time zone, p_items jsonb, p_payments jsonb, p_customer_id uuid, p_vehicle_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.orders; n uuid; i public.order_items; ni public.order_items; p public.payments; np public.payments;
 x jsonb; q numeric; u numeric; ratio numeric; tv numeric; tr numeric; pv numeric; initial_paid numeric;
 cs public.cashea_sales; ns public.cashea_sales; ci public.cashea_installments; ci_id uuid; instmap jsonb:='{}';
 lc public.receivables; new_lc uuid; inst_id uuid; new_sale uuid; part numeric; amount numeric; fin numeric; paidinst numeric;
begin
 perform lubricenter_private.require_order_admin();
 select * into o from public.orders where id=p_order_id for update;
 if not found then raise exception 'Orden no encontrada'; end if;
 if o.status='CANCELLED' then
  select id into n from public.orders where corrects_order_id=p_order_id;
  if n is not null then return n; end if;
 end if;
 if o.status<>'CLOSED' then raise exception 'Solo se corrigen ventas cerradas'; end if;
 if p_business_at is null or p_business_at>now()+interval '5 minutes' then raise exception 'Indica la fecha real de la venta'; end if;
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'La corrección necesita al menos una línea. Si no hubo venta, usa Anular'; end if;
 if jsonb_typeof(p_payments)<>'array' then raise exception 'Revisa los pagos'; end if;
 if p_vehicle_id is not null and not exists(select 1 from public.vehicles where id=p_vehicle_id and customer_id=p_customer_id) then raise exception 'El vehículo no pertenece al cliente seleccionado'; end if;
 perform 1 from public.cashea_installments where cashea_sale_id in(select id from public.cashea_sales where order_id=p_order_id) order by id for update;
 select * into cs from public.cashea_sales where order_id=p_order_id for update;
 select * into lc from public.receivables where order_id=p_order_id for update;
 perform lubricenter_private.cancel_order(p_order_id,p_reason);
 perform set_config('lubricenter.revision','yes',true);
 insert into public.orders(customer_id,vehicle_id,location_id,is_walk_in,business_at,corrects_order_id,health_status,health_notes,health_reviewed_at,crm_additional_services,crm_bonuses,crm_observations)
 values(p_customer_id,p_vehicle_id,o.location_id,o.is_walk_in,p_business_at,o.id,o.health_status,o.health_notes,o.health_reviewed_at,o.crm_additional_services,o.crm_bonuses,o.crm_observations) returning id into n;
 perform set_config('lubricenter.order_id',n::text,true);
 if (select count(*) from jsonb_array_elements(p_items))<>(select count(distinct value->>'source_id') from jsonb_array_elements(p_items)) then raise exception 'Hay líneas duplicadas en la corrección'; end if;
 for x in select value from jsonb_array_elements(p_items) loop
  select * into i from public.order_items where id=(x->>'source_id')::uuid and order_id=o.id;
  if not found then raise exception 'Una línea no pertenece a la venta original'; end if;
  q:=(x->>'quantity')::numeric; u:=(x->>'unit_ref')::numeric;
  if q is null or q<=0 or u is null or u<0 or q::text in ('NaN','Infinity','-Infinity') or u::text in ('NaN','Infinity','-Infinity') then raise exception 'Cantidad o precio inválido'; end if;
  ni:=i; ni.id:=gen_random_uuid(); ni.order_id:=n; ni.created_at:=now(); ni.quantity:=q; ni.description:=trim(x->>'description');
  if coalesce(ni.description,'')='' then raise exception 'Escribe la descripción de cada línea'; end if;
  if abs(q-i.quantity)>0.000001 or abs(u-i.charged_ref_amount/i.quantity)>0.000001 then
   ni.charged_ref_amount:=round(q*u,4); ni.charged_ves_amount:=round(ni.charged_ref_amount*i.bcv_rate_snapshot,2);
   ni.customer_ref_amount:=ni.charged_ref_amount; ni.base_ref_amount:=ni.charged_ref_amount;
   ni.pricing_mode:=case when i.pricing_mode='MANUAL_NO_STOCK' then i.pricing_mode else 'MANUAL_OVERRIDE' end;
   ni.cash_usd_special_total:=null; ni.cash_price_revealed:=false;
   ratio:=case when i.charged_ref_amount>0 then ni.charged_ref_amount/i.charged_ref_amount else q/i.quantity end;
   ni.worker_share_ref_snapshot:=round(i.worker_share_ref_snapshot*ratio,4); ni.assistant_bonus_ref_snapshot:=round(i.assistant_bonus_ref_snapshot*ratio,4);
  end if;
  if ni.price_denomination='USD' then ni.agreed_usd:=round(ni.charged_ves_amount/ni.operative_rate_snapshot,4); end if;
  insert into public.order_items select ni.*;
 end loop;
 select sum(charged_ves_amount),sum(charged_ref_amount) into tv,tr from public.order_items where order_id=n;
 if tv<=0 then raise exception 'El total debe ser mayor que cero'; end if;
 if cs.id is not null then
  ns:=cs; ns.id:=gen_random_uuid(); ns.order_id:=n; ns.created_at:=now(); ns.created_by:=auth.uid(); ns.receivable_id:=null;
  ns.gross_ref:=tr; ns.gross_ves_snapshot:=tv; ns.initial_ref:=round(tr*cs.initial_percent/100,4); ns.initial_ves_snapshot:=round(ns.initial_ref*cs.bcv_rate_snapshot,2);
  ns.financed_ref:=tr-ns.initial_ref; ns.commission_ref:=round(tr*cs.commission_percent/100,4); ns.commission_ves_snapshot:=round(ns.commission_ref*cs.bcv_rate_snapshot,2);
  ns.status:='ACTIVE'; ns.settled_at:=null; insert into public.cashea_sales select ns.*; new_sale:=ns.id;
  part:=round(ns.financed_ref/3,4);
  for ci in select * from public.cashea_installments where cashea_sale_id=cs.id order by installment_no loop
   amount:=case when ci.installment_no=3 then ns.financed_ref-2*part else part end;
   if amount+0.0001<ci.paid_ref then raise exception 'La cuota % ya recibió REF %. No puedes reducirla por debajo de ese pago',ci.installment_no,ci.paid_ref; end if;
   ci_id:=gen_random_uuid(); instmap:=instmap||jsonb_build_object(ci.id::text,ci_id);
   insert into public.cashea_installments(id,cashea_sale_id,installment_no,due_date,amount_ref,amount_ves_snapshot,paid_ref,paid_ves_actual,status,paid_at)
   values(ci_id,new_sale,ci.installment_no,(p_business_at at time zone 'America/Caracas')::date+ci.installment_no*14,amount,round(amount*cs.bcv_rate_snapshot,2),ci.paid_ref,ci.paid_ves_actual,case when amount-ci.paid_ref<=0.05 then 'PAID' when ci.paid_ref>0 then 'PARTIAL' else 'PENDING' end,ci.paid_at);
  end loop;
 end if;
 if (select count(*) from jsonb_array_elements(p_payments))<>(select count(distinct value->>'source_id') from jsonb_array_elements(p_payments)) then raise exception 'Hay pagos duplicados'; end if;
 initial_paid:=0;
 for x in select value from jsonb_array_elements(p_payments) loop
  select * into p from public.payments where id=(x->>'source_id')::uuid and order_id=o.id;
  if not found then raise exception 'Un pago no pertenece a la venta original'; end if;
  select entity_id into inst_id from public.audit_events where event_type='cashea.installment_payment_recorded' and data->>'payment_id'=p.id::text limit 1;
  if inst_id is not null and ((x->>'method') is distinct from p.method or (x->>'amount_original')::numeric<>p.amount_original) then raise exception 'Los pagos de cuotas Cashea se conservan: corrige la inicial, no una cuota ya recibida'; end if;
  np:=p; np.id:=gen_random_uuid(); np.order_id:=n; np.receivable_id:=null; np.created_at:=now(); np.created_by:=auth.uid();
  np.method:=x->>'method'; np.amount_original:=(x->>'amount_original')::numeric; np.reference:=nullif(trim(x->>'reference'),'');
  if np.amount_original is null or np.amount_original<=0 or np.amount_original::text in ('NaN','Infinity','-Infinity') then raise exception 'Monto de pago inválido'; end if;
  if np.method<>p.method or np.amount_original<>p.amount_original then
   np.currency:=case when np.method in ('CASH_USD','ZELLE','BINANCE') then 'USD' else 'VES' end;
   np.financial_account_id:=null;
   np.value_ves:=case when np.currency='USD' then round(np.amount_original*case when cs.id is not null then p.bcv_rate_snapshot else p.operative_rate_snapshot end,2) else np.amount_original end;
   np.value_ref:=round(np.value_ves/p.bcv_rate_snapshot,4);
  end if;
  if inst_id is null and p.receivable_id is null then np.paid_at:=p_business_at; end if;
  insert into public.payments select np.*;
  if inst_id is not null then
   if instmap->>inst_id::text is null then raise exception 'No se encontró la cuota original del pago'; end if;
   insert into public.audit_events(event_type,entity_type,entity_id,data) values('cashea.installment_payment_recorded','cashea_installment',(instmap->>inst_id::text)::uuid,jsonb_build_object('payment_id',np.id,'copied_from_payment_id',p.id,'value_ref',np.value_ref));
  else initial_paid:=initial_paid+np.value_ves; end if;
 end loop;
 if exists(select 1 from public.payments pay join public.audit_events a on a.event_type='cashea.installment_payment_recorded' and a.data->>'payment_id'=pay.id::text where pay.order_id=o.id and not exists(select 1 from jsonb_array_elements(p_payments) element where element.value->>'source_id'=pay.id::text)) then raise exception 'Conserva todos los pagos de cuotas Cashea ya recibidas'; end if;
 select coalesce(sum(value_ves),0) into pv from public.payments where order_id=n;
 if cs.id is null then
  if lc.id is not null then perform public.close_order_with_credit(n,lc.due_date); else perform public.close_order(n); end if;
 else
  if abs(initial_paid-ns.initial_ves_snapshot)>1 then raise exception 'Ajusta los pagos de la inicial a Bs % (inicial original de % por ciento)',ns.initial_ves_snapshot,cs.initial_percent; end if;
  perform public.validate_order_ready_to_close(n);
  update public.orders set status='CLOSED',closed_at=p_business_at,total_ves=tv,total_ref=tr,total_cash_usd_equivalent=(select sum(charged_ves_amount/operative_rate_snapshot) from public.order_items where order_id=n) where id=n;
  for i in select * from public.order_items where order_id=n loop
   if i.business_area in ('WORKSHOP','ELECTROAUTO') and coalesce(i.worker_share_ref_snapshot,0)>0 then insert into public.payroll_accruals(employee_id,source_order_item_id,source_type,amount_ref,description) values(i.worker_employee_id,i.id,case when i.business_area='WORKSHOP' then 'WORKSHOP_COMMISSION' else 'ELECTROAUTO_COMMISSION' end,i.worker_share_ref_snapshot,'Corrección · '||i.description); end if;
   if i.business_area='WORKSHOP' and coalesce(i.assistant_bonus_ref_snapshot,0)>0 then insert into public.payroll_accruals(employee_id,source_order_item_id,source_type,amount_ref,description) values(i.assistant_bonus_employee_id,i.id,'ASSISTANT_BONUS',i.assistant_bonus_ref_snapshot,'Corrección · '||i.description); end if;
  end loop;
  select coalesce(sum(greatest(amount_ref-paid_ref,0)),0) into fin from public.cashea_installments where cashea_sale_id=new_sale;
  update public.cashea_sales set status=case when fin<=0.05 then 'SETTLED' else 'ACTIVE' end,settled_at=case when fin<=0.05 then now() end where id=new_sale;
 end if;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('order.corrected','order',o.id,jsonb_build_object('replacement_order_id',n,'reason',p_reason));
 return n;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.create_order_dated(p_business_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; begin
 perform public.require_auth(); perform set_config('lubricenter.business_at',coalesce(p_business_at::text,''),true);
 select * into r from public.create_order(); return to_jsonb(r);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.crm_manual_case_save(p_case_id uuid, p_payload jsonb, p_expected_version integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_case public.crm_manual_cases%rowtype; v_old jsonb;
 v_vehicle public.vehicles%rowtype;v_order public.orders%rowtype;
 v_vehicle_id uuid;v_customer_id uuid;v_payer uuid;v_linked uuid;v_context text;v_note text;
 v_scheduled timestamptz;v_followup date;v_notes text;v_subject_hint text;v_request uuid;
 v_today date:=(now() at time zone 'America/Caracas')::date;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 IF jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Datos del CRM inválidos'; END IF;
 v_vehicle_id:=NULLIF(p_payload->>'vehicle_id','')::uuid;
 v_customer_id:=NULLIF(p_payload->>'customer_id','')::uuid;
 v_linked:=NULLIF(p_payload->>'linked_order_id','')::uuid;
 v_payer:=NULLIF(p_payload->>'payer_customer_id','')::uuid;
 v_context:=COALESCE(NULLIF(p_payload->>'payment_context',''),'UNVERIFIED');
 v_note:=NULLIF(btrim(coalesce(p_payload->>'payment_note','')),'');
 v_notes:=NULLIF(btrim(coalesce(p_payload->>'notes','')),'');
 v_subject_hint:=NULLIF(btrim(coalesce(p_payload->>'subject_hint','')),'');
 v_scheduled:=NULLIF(p_payload->>'scheduled_for','')::timestamptz;
 v_followup:=NULLIF(p_payload->>'next_contact_on','')::date;
 v_request:=NULLIF(p_payload->>'request_id','')::uuid;
 IF v_context NOT IN ('UNVERIFIED','REPORTED_EXTERNALLY','ORDER_LINKED','NO_CHARGE') THEN
  RAISE EXCEPTION 'Origen de pago inválido';
 END IF;
 IF v_vehicle_id IS NOT NULL THEN
  SELECT * INTO v_vehicle FROM public.vehicles WHERE id=v_vehicle_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehículo no encontrado'; END IF;
  IF v_vehicle.customer_id IS NULL THEN RAISE EXCEPTION 'Asigna un propietario al vehículo antes de usarlo en este pendiente'; END IF;
  IF v_customer_id IS NOT NULL AND v_customer_id IS DISTINCT FROM v_vehicle.customer_id THEN
   RAISE EXCEPTION 'El vehículo no pertenece al cliente seleccionado';
  END IF;
  v_customer_id:=v_vehicle.customer_id;
 ELSIF v_customer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.customers WHERE id=v_customer_id) THEN
  RAISE EXCEPTION 'Cliente no encontrado';
 END IF;
 IF v_customer_id IS NULL AND length(coalesce(v_subject_hint,v_notes,''))<3 THEN
  RAISE EXCEPTION 'Escribe una referencia para reconocer este compromiso cuando llegue el cliente';
 END IF;
 IF length(coalesce(v_subject_hint,''))>250 OR length(coalesce(v_notes,''))>1500 OR length(coalesce(v_note,''))>450 THEN
  RAISE EXCEPTION 'La referencia o las notas son demasiado extensas';
 END IF;
 IF v_scheduled IS NOT NULL AND (v_scheduled<now()-interval '2 years' OR v_scheduled>now()+interval '3 years') THEN
  RAISE EXCEPTION 'Fecha programada fuera del intervalo permitido';
 END IF;
 IF v_followup IS NOT NULL AND (v_followup<v_today-interval '2 years' OR v_followup>v_today+interval '3 years') THEN
  RAISE EXCEPTION 'Fecha de contacto fuera del intervalo permitido';
 END IF;
 IF v_context='REPORTED_EXTERNALLY' AND length(coalesce(v_note,''))<8 THEN
  RAISE EXCEPTION 'Describe dónde se reportó el pago, sin generar un ingreso nuevo';
 END IF;
 IF v_context='ORDER_LINKED' AND v_linked IS NULL THEN
  RAISE EXCEPTION 'Selecciona la orden que contiene el pago registrado';
 END IF;
 IF v_linked IS NOT NULL THEN
  SELECT * INTO v_order FROM public.orders WHERE id=v_linked;
  IF NOT FOUND OR v_order.status<>'CLOSED' THEN RAISE EXCEPTION 'La orden vinculada debe existir y estar cerrada'; END IF;
  IF v_order.customer_id IS NULL THEN RAISE EXCEPTION 'La orden vinculada necesita pagador identificado'; END IF;
  IF v_payer IS NOT NULL AND v_payer IS DISTINCT FROM v_order.customer_id THEN
   RAISE EXCEPTION 'El pagador debe coincidir con el cliente de la orden anterior';
  END IF;
  v_payer:=v_order.customer_id;
 END IF;
 IF v_payer IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id=v_payer) THEN
  RAISE EXCEPTION 'Pagador no encontrado';
 END IF;
 IF p_case_id IS NULL THEN
  IF v_request IS NULL THEN RAISE EXCEPTION 'Identificador de solicitud requerido'; END IF;
  SELECT id INTO p_case_id FROM public.crm_manual_cases WHERE request_id=v_request;
  IF FOUND THEN RETURN p_case_id; END IF;
  INSERT INTO public.crm_manual_cases(
   request_id,vehicle_id,customer_id,payer_customer_id,linked_order_id,payment_context,
   payment_note,status,scheduled_for,next_contact_on,notes,subject_hint,created_by,updated_by)
  VALUES(v_request,v_vehicle_id,v_customer_id,v_payer,v_linked,v_context,v_note,
   CASE WHEN v_scheduled IS NULL THEN 'PENDING_SERVICE' ELSE 'SCHEDULED' END,
   v_scheduled,v_followup,v_notes,v_subject_hint,auth.uid(),auth.uid()) RETURNING id INTO p_case_id;
  INSERT INTO public.crm_manual_case_events(case_id,event_type,after_data,actor_id)
  SELECT id,'CREATED',to_jsonb(c),auth.uid() FROM public.crm_manual_cases c WHERE id=p_case_id;
  RETURN p_case_id;
 END IF;
 SELECT * INTO v_case FROM public.crm_manual_cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Ficha de CRM manual no encontrada'; END IF;
 IF v_case.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'No puedes cambiar una ficha realizada o anulada: conserva el historial'; END IF;
 IF p_expected_version IS DISTINCT FROM v_case.version THEN RAISE EXCEPTION 'Otro usuario modificó la ficha. Recarga antes de guardar'; END IF;
 v_old:=to_jsonb(v_case);
 UPDATE public.crm_manual_cases c SET
  vehicle_id=v_vehicle_id,customer_id=v_customer_id,payer_customer_id=v_payer,
  linked_order_id=v_linked,payment_context=v_context,payment_note=v_note,
  status=CASE WHEN v_scheduled IS NULL THEN 'PENDING_SERVICE' ELSE 'SCHEDULED' END,
  scheduled_for=v_scheduled,next_contact_on=v_followup,notes=v_notes,subject_hint=v_subject_hint,
  updated_by=auth.uid(),updated_at=now(),version=c.version+1
 WHERE id=p_case_id;
 INSERT INTO public.crm_manual_case_events(case_id,event_type,before_data,after_data,actor_id)
 SELECT c.id,'UPDATED',v_old,to_jsonb(c),auth.uid() FROM public.crm_manual_cases c WHERE c.id=p_case_id;
 RETURN p_case_id;
END; $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.crm_manual_case_transition(p_case_id uuid, p_action text, p_expected_version integer, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.crm_manual_cases%rowtype; v_old jsonb;v_order public.orders%rowtype;
 v_km integer;v_oil text;v_vis text;v_filter text;v_liters numeric;v_next_km integer;
 v_next_date date;v_at timestamptz;v_sr uuid;v_message text;v_customer text;
 v_plate text;v_reason text;v_contact_permission text;v_vehicle_owner uuid;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 IF p_action NOT IN ('COMPLETE','CANCEL','MARK_CONTACT_SENT') THEN RAISE EXCEPTION 'Acción CRM inválida'; END IF;
 SELECT * INTO c FROM public.crm_manual_cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Ficha CRM no encontrada'; END IF;
 IF p_action='COMPLETE' AND c.status='COMPLETED' THEN
  RETURN jsonb_build_object('id',c.id,'service_record_id',c.service_record_id,'already_completed',true);
 END IF;
 IF p_expected_version IS DISTINCT FROM c.version THEN RAISE EXCEPTION 'La ficha cambió; recarga antes de continuar'; END IF;
 v_old:=to_jsonb(c);
 v_reason:=NULLIF(btrim(coalesce(p_payload->>'reason','')),'');
 IF p_action='CANCEL' THEN
  IF c.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'No se puede anular un servicio ya realizado o anulado'; END IF;
  IF length(coalesce(v_reason,''))<8 THEN RAISE EXCEPTION 'Explica por qué se anula el pendiente'; END IF;
  UPDATE public.crm_manual_cases SET status='CANCELLED',updated_by=auth.uid(),updated_at=now(),version=version+1 WHERE id=c.id;
  INSERT INTO public.crm_manual_case_events(case_id,event_type,before_data,after_data,reason,actor_id)
  SELECT id,'CANCELLED',v_old,to_jsonb(x),v_reason,auth.uid() FROM public.crm_manual_cases x WHERE id=c.id;
  RETURN jsonb_build_object('id',c.id,'status','CANCELLED');
 END IF;
 IF p_action='MARK_CONTACT_SENT' THEN
  IF c.status='CANCELLED' THEN RAISE EXCEPTION 'No se contacta desde una ficha anulada'; END IF;
  IF c.customer_id IS NULL THEN RAISE EXCEPTION 'Asigna al cliente antes de registrar un contacto'; END IF;
  IF c.crm_message_sent_at IS NOT NULL THEN RETURN jsonb_build_object('id',c.id,'already_sent',true); END IF;
  SELECT status INTO v_contact_permission FROM public.crm_contact_permissions WHERE customer_id=c.customer_id;
  IF v_contact_permission IS DISTINCT FROM 'OPT_IN' THEN RAISE EXCEPTION 'Comprueba autorización de contacto del propietario antes de registrar envío'; END IF;
  v_message:=NULLIF(btrim(coalesce(p_payload->>'message','')),'');
  IF length(coalesce(v_message,''))<20 OR length(v_message)>1800 THEN RAISE EXCEPTION 'Registra el texto real enviado por WhatsApp (20 a 1800 caracteres)'; END IF;
  UPDATE public.crm_manual_cases SET crm_message=v_message,crm_message_sent_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 WHERE id=c.id;
  INSERT INTO public.crm_manual_case_events(case_id,event_type,before_data,after_data,actor_id)
  SELECT id,'CONTACT_SENT',v_old,to_jsonb(x),auth.uid() FROM public.crm_manual_cases x WHERE id=c.id;
  RETURN jsonb_build_object('id',c.id,'status',c.status,'contact_sent',true);
 END IF;
 IF c.status NOT IN('PENDING_SERVICE','SCHEDULED') THEN RAISE EXCEPTION 'Este servicio no está pendiente'; END IF;
 IF c.customer_id IS NULL OR c.vehicle_id IS NULL THEN RAISE EXCEPTION 'Asigna o registra el cliente y el vehículo antes de confirmar el servicio'; END IF;
 SELECT customer_id INTO v_vehicle_owner FROM public.vehicles WHERE id=c.vehicle_id FOR SHARE;
 IF NOT FOUND OR v_vehicle_owner IS DISTINCT FROM c.customer_id THEN RAISE EXCEPTION 'El vehículo ya no está asociado al cliente de esta ficha; corrige la asignación'; END IF;
 v_km:=NULLIF(p_payload->>'odometer','')::integer;
 v_oil:=NULLIF(btrim(coalesce(p_payload->>'oil_brand','')),'');
 v_vis:=NULLIF(btrim(coalesce(p_payload->>'oil_viscosity','')),'');
 v_filter:=NULLIF(btrim(coalesce(p_payload->>'oil_filter_code','')),'');
 v_liters:=NULLIF(p_payload->>'oil_quantity_liters','')::numeric;
 v_next_km:=NULLIF(p_payload->>'next_service_odometer','')::integer;
 v_next_date:=NULLIF(p_payload->>'next_service_date','')::date;
 v_at:=COALESCE(NULLIF(p_payload->>'performed_at','')::timestamptz,now());
 IF v_km IS NULL OR v_km<0 OR v_km>9999999 THEN RAISE EXCEPTION 'Kilometraje del servicio inválido'; END IF;
 IF length(coalesce(v_oil,''))<2 OR length(v_oil)>150 THEN RAISE EXCEPTION 'Aceite utilizado requerido'; END IF;
 IF v_liters IS NOT NULL AND (v_liters<=0 OR v_liters>100 OR v_liters::text='NaN') THEN RAISE EXCEPTION 'Litros inválidos'; END IF;
 IF length(coalesce(v_vis,''))>80 OR length(coalesce(v_filter,''))>100 THEN RAISE EXCEPTION 'Datos de aceite/filtro demasiado largos'; END IF;
 IF v_next_km IS NULL AND v_next_date IS NULL THEN RAISE EXCEPTION 'Indica el próximo mantenimiento'; END IF;
 IF v_next_km IS NOT NULL AND (v_next_km<=v_km OR v_next_km>9999999) THEN RAISE EXCEPTION 'Próximo kilometraje inválido'; END IF;
 IF v_at>now()+interval '5 minutes' OR v_at<now()-interval '3 years' THEN RAISE EXCEPTION 'Fecha real del servicio inválida'; END IF;
 IF c.linked_order_id IS NOT NULL THEN
  SELECT * INTO v_order FROM public.orders WHERE id=c.linked_order_id FOR SHARE;
  IF NOT FOUND OR v_order.status<>'CLOSED' THEN RAISE EXCEPTION 'La orden vinculada ya no está cerrada'; END IF;
  IF EXISTS (SELECT 1 FROM public.service_records sr WHERE sr.order_id=c.linked_order_id AND sr.vehicle_id=c.vehicle_id
   AND sr.service_type='OIL_CHANGE' AND abs(extract(epoch FROM (sr.performed_at-v_at)))<86400)
  THEN RAISE EXCEPTION 'Este vehículo ya tiene un cambio de aceite de esa orden y fecha. Revisa el historial antes de duplicarlo'; END IF;
 END IF;
 INSERT INTO public.service_records(order_id,order_item_id,customer_id,vehicle_id,service_type,description,
  odometer,oil_brand,oil_viscosity,oil_quantity_liters,oil_filter_code,next_service_odometer,next_service_date,
  charged_ref_amount,charged_ves_amount,performed_at,created_by,source_system,source_key,service_notes,source_payload)
 VALUES(c.linked_order_id,NULL,c.customer_id,c.vehicle_id,'OIL_CHANGE','Cambio de aceite registrado en CRM manual',
  v_km,v_oil,v_vis,v_liters,v_filter,v_next_km,v_next_date,0,0,v_at,auth.uid(),'LUBRICENTER_CRM_MANUAL',
  c.id::text,c.notes,jsonb_build_object('crm_manual_case_id',c.id,'commercial_order_linked_for_reference_only',c.linked_order_id))
 RETURNING id INTO v_sr;
 UPDATE public.vehicles SET current_odometer=greatest(coalesce(current_odometer,0),v_km),updated_at=now() WHERE id=c.vehicle_id;
 SELECT coalesce(nullif(btrim(name),''),'cliente') INTO v_customer FROM public.customers WHERE id=c.customer_id;
 SELECT coalesce(nullif(btrim(concat_ws(' ',v.make,v.model)),''),'Vehículo')||coalesce(' · '||nullif(v.plate,''),'')
  INTO v_plate FROM public.vehicles v WHERE v.id=c.vehicle_id;
 v_message:='Hola *'||v_customer||'* 👋'||chr(10)||'Registramos el mantenimiento de tu vehículo *'||v_plate||'*.'||chr(10)||
  '🛢️ Aceite: '||v_oil||coalesce(' · '||v_vis,'')||chr(10)||'Kilometraje: '||v_km||' km.'||chr(10)||
  '📅 Próximo servicio: '||concat_ws(' o ',CASE WHEN v_next_km IS NOT NULL THEN v_next_km||' km' END,
  CASE WHEN v_next_date IS NOT NULL THEN to_char(v_next_date,'DD/MM/YYYY') END)||chr(10)||'*Lubricenter*';
 UPDATE public.crm_manual_cases SET status='COMPLETED',service_record_id=v_sr,crm_message=v_message,
  crm_message_sent_at=NULL,updated_by=auth.uid(),updated_at=now(),version=version+1 WHERE id=c.id;
 INSERT INTO public.crm_manual_case_events(case_id,event_type,before_data,after_data,actor_id)
 SELECT id,'COMPLETED',v_old,to_jsonb(x),auth.uid() FROM public.crm_manual_cases x WHERE id=c.id;
 RETURN jsonb_build_object('id',c.id,'status','COMPLETED','service_record_id',v_sr);
END; $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.customer_balance_order_cancelled()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_payment_id uuid;
begin
  if new.status='CANCELLED' and old.status is distinct from 'CANCELLED' then
    for v_payment_id in select id from public.payments where order_id=new.id
      and method in ('CUSTOMER_BALANCE_USD','CUSTOMER_BALANCE_BCV') order by id loop
      perform lubricenter_private.release_customer_balance_payment(v_payment_id,'Orden anulada: '||coalesce(new.cancellation_reason,'sin detalle'));
    end loop;
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.customer_balance_payment_deleted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.method in ('CUSTOMER_BALANCE_USD','CUSTOMER_BALANCE_BCV') then
    perform lubricenter_private.release_customer_balance_payment(old.id,'Pago quitado de la orden');
  end if;
  return old;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.customer_balance_payment_used()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_id uuid; v_status text; v_pocket text; v_units numeric(18,2);
  v_rate numeric; v_available numeric(18,2); v_entry uuid;
begin
  if new.method not in ('CUSTOMER_BALANCE_USD','CUSTOMER_BALANCE_BCV') then return new; end if;
  select customer_id,status into v_customer_id,v_status from public.orders where id=new.order_id for update;
  if v_customer_id is null then raise exception 'Asocia un cliente antes de usar saldo a favor'; end if;
  if v_status<>'OPEN' then raise exception 'Solo se puede usar saldo a favor en una orden abierta'; end if;
  v_pocket := case when new.method='CUSTOMER_BALANCE_USD' then 'USD' else 'VES_BCV' end;
  v_rate := case when v_pocket='USD' then new.operative_rate_snapshot else new.bcv_rate_snapshot end;
  if v_rate is null or v_rate<=0 or new.value_ves<=0 then raise exception 'Tasa o importe de saldo inválido'; end if;
  if v_pocket='USD' and (new.currency<>'USD' or abs(new.value_ves-round(new.amount_original*v_rate,2))>0.01)
    or v_pocket='VES_BCV' and (new.currency<>'VES' or abs(new.value_ves-new.amount_original)>0.01) then
    raise exception 'El saldo a favor debe conservar su moneda y su tasa';
  end if;
  v_units := round(new.value_ves/v_rate,2);
  insert into public.customer_balance_accounts(customer_id,pocket) values(v_customer_id,v_pocket)
    on conflict do nothing;
  select balance_usd into v_available from public.customer_balance_accounts
    where customer_id=v_customer_id and pocket=v_pocket for update;
  if v_units<=0 or v_units>v_available then
    raise exception 'Saldo a favor insuficiente: disponible % USD en %',v_available,v_pocket;
  end if;
  update public.customer_balance_accounts set balance_usd=balance_usd-v_units,updated_at=now()
    where customer_id=v_customer_id and pocket=v_pocket;
  insert into public.customer_balance_movements(
    customer_id,pocket,movement_type,delta_usd,amount_original,currency,value_ves,
    bcv_rate_snapshot,operative_rate_snapshot,method,note,order_id,payment_id
  ) values (
    v_customer_id,v_pocket,'USE',-v_units,new.amount_original,new.currency,new.value_ves,
    new.bcv_rate_snapshot,new.operative_rate_snapshot,new.method,
    'Aplicado a la orden',new.order_id,new.id
  ) returning id into v_entry;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('customer_balance.used','customer_balance_movement',v_entry,
    jsonb_build_object('customer_id',v_customer_id,'order_id',new.order_id,'payment_id',new.id,
      'pocket',v_pocket,'units_usd',v_units,'value_ves',new.value_ves,'rate',v_rate));
  return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_allocate(p_request_id uuid, p_external_id uuid, p_movement_id uuid, p_installment_id uuid, p_external_amount numeric, p_target_amount numeric, p_method text, p_reason text, p_sale_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x public.external_transactions; s public.external_sources; m public.account_movements; i public.cashea_installments; c public.cashea_sales; v_id uuid; v_used numeric; v_capacity numeric; v_currency text; v_tolerance numeric; a public.reconciliation_allocations;
begin
 perform lubricenter_private.finance_require();
 if p_request_id is null or length(trim(coalesce(p_reason,'')))<3 then raise exception 'Identificador y motivo requeridos'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,22));
 select * into a from public.reconciliation_allocations where request_id=p_request_id;
 if found then
  if a.external_transaction_id<>p_external_id or a.account_movement_id is distinct from p_movement_id or a.cashea_installment_id is distinct from p_installment_id or a.cashea_sale_id is distinct from p_sale_id or a.external_amount<>p_external_amount or a.target_amount<>p_target_amount or a.method<>p_method then raise exception 'La clave de operación ya se usó con otros datos'; end if;
  return a.id;
 end if;
 if num_nonnulls(p_movement_id,p_installment_id,p_sale_id)<>1 or p_external_amount is null or p_target_amount is null or p_external_amount<=0 or p_target_amount<=0 or p_external_amount>='Infinity'::numeric or p_target_amount>='Infinity'::numeric then raise exception 'Asignación inválida'; end if;
 select * into x from public.external_transactions where id=p_external_id for update;
 if not found or x.ownership_status<>'OWN' then raise exception 'Resuelve primero a quién pertenece el cobro'; end if;
 if exists(select 1 from public.reconciliation_cases where subject_id=x.id and status='OPEN' and kind in ('SOURCE_CONFLICT','SOURCE_AMOUNT')) then raise exception 'Resuelve la inconsistencia del reporte antes de asignar'; end if;
 select * into s from public.external_sources where id=x.source_id;
 if p_movement_id is not null then
  if s.provider<>'BDV' then raise exception 'Cashea se asigna a cuotas; el banco se asigna a movimientos'; end if;
  select * into m from public.account_movements where id=p_movement_id for update;
  if not found or m.account_id<>s.account_id or m.currency<>x.currency or m.direction<>x.direction then raise exception 'Cuenta, moneda o dirección incompatible'; end if;
  if m.source_payment_id is not null and exists(select 1 from public.payments p join public.orders o on o.id=p.order_id where p.id=m.source_payment_id and o.status='CANCELLED') then raise exception 'El pago pertenece a una orden anulada'; end if;
  v_capacity:=m.amount_original; v_currency:=m.currency;
  select coalesce(sum(target_amount),0) into v_used from public.reconciliation_allocations where account_movement_id=m.id and reversed_at is null;
 elsif p_sale_id is not null then
  if s.provider<>'CASHEA_TRANSACTIONS' or not 0=any(x.installments) then raise exception 'Este movimiento no documenta una inicial Cashea'; end if;
  select * into c from public.cashea_sales where id=p_sale_id for update;
  if not found or c.status='CANCELLED' or c.ownership_status<>'OWN' or trim(c.cashea_reference) is distinct from x.external_order then raise exception 'Inicial incompatible con la orden Cashea'; end if;
  v_capacity:=c.initial_ref; v_currency:='USD';
  select coalesce(sum(target_amount),0) into v_used from public.reconciliation_allocations where cashea_sale_id=c.id and reversed_at is null;
 else
  if s.provider<>'CASHEA_TRANSACTIONS' then raise exception 'Solo el reporte de cobros Cashea se asigna a cuotas'; end if;
  select * into i from public.cashea_installments where id=p_installment_id for update;
  if not found then raise exception 'Cuota no encontrada'; end if;
  select * into c from public.cashea_sales where id=i.cashea_sale_id;
  if c.status='CANCELLED' or c.ownership_status<>'OWN' or trim(c.cashea_reference) is distinct from x.external_order or not i.installment_no=any(x.installments) then raise exception 'Orden o cuota incompatible con el reporte'; end if;
  v_capacity:=i.amount_ref; v_currency:='USD';
  select coalesce(sum(target_amount),0) into v_used from public.reconciliation_allocations where cashea_installment_id=i.id and reversed_at is null;
 end if;
 if s.provider='CASHEA_TRANSACTIONS' and (select status from public.cashea_order_snapshots where external_order=x.external_order order by created_at desc,id desc limit 1)='CANCELLED' then raise exception 'La última evidencia Cashea muestra la orden cancelada'; end if;
 if v_used+p_target_amount>v_capacity then raise exception 'La asignación excede el saldo conciliable del destino'; end if;
 v_capacity:=case when s.provider='BDV' then x.amount else least(x.amount_ref,x.assigned_ref) end;
 select coalesce(sum(external_amount),0) into v_used from public.reconciliation_allocations where external_transaction_id=x.id and reversed_at is null;
 if v_capacity is null or v_used+p_external_amount>v_capacity then raise exception 'El movimiento externo no tiene saldo suficiente'; end if;
 v_tolerance:=case when v_currency='VES' then least(5,p_target_amount*.001) when s.provider='CASHEA_TRANSACTIONS' then least(0.005,p_target_amount*.001) else 0 end;
 if p_method='ROUNDING' and abs(p_external_amount-p_target_amount)>v_tolerance then raise exception 'Diferencia fuera de tolerancia'; end if;
 if p_method='MANUAL' and p_external_amount<>p_target_amount then raise exception 'Una diferencia comercial necesita ajuste documentado separado, no conciliación manual'; end if;
 insert into public.reconciliation_allocations(request_id,external_transaction_id,account_movement_id,cashea_installment_id,cashea_sale_id,currency,external_amount,target_amount,method,reason)
 values(p_request_id,x.id,p_movement_id,p_installment_id,p_sale_id,v_currency,p_external_amount,p_target_amount,p_method,trim(p_reason)) returning id into v_id;
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and tg_table_name='reconciliation_cases' and to_jsonb(new)-'updated_at'=to_jsonb(old)-'updated_at' then return new; end if;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('finance.'||lower(tg_op),tg_table_name,
 case when tg_op='DELETE' then coalesce((to_jsonb(old)->>'id')::uuid,(to_jsonb(old)->>'account_id')::uuid) else coalesce((to_jsonb(new)->>'id')::uuid,(to_jsonb(new)->>'account_id')::uuid) end,
 jsonb_build_object('before',case when tg_op='INSERT' then null else to_jsonb(old) end,'after',case when tg_op='DELETE' then null else to_jsonb(new) end));
 return coalesce(new,old);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_autofix_bank_mismatches(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 hit record; p public.payments%ROWTYPE; old_movement jsonb;
 target_account uuid; fixed integer:=0; skipped integer:=0; errors jsonb:='[]'::jsonb;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 IF p_from IS NULL OR p_to IS NULL OR p_from>p_to OR p_to-p_from>35
 THEN RAISE EXCEPTION 'Período inválido de máximo 36 días'; END IF;
 FOR hit IN SELECT * FROM lubricenter_private.finance_exact_bank_mismatches(p_from,p_to)
 LOOP
  BEGIN
   SELECT * INTO p FROM public.payments WHERE id=hit.payment_id FOR UPDATE;
   IF NOT FOUND OR p.method NOT IN ('TRANSFER_BDV','TRANSFER_BNC')
     OR NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.id=p.order_id AND o.status='CLOSED')
   THEN RAISE EXCEPTION 'Pago no válido para rectificación'; END IF;
   IF (SELECT code FROM public.financial_accounts WHERE id=p.financial_account_id)<>hit.recorded_account
   THEN RAISE EXCEPTION 'La cuenta cambió mientras se revisaba'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.external_transactions et
       JOIN public.external_sources es ON es.id=et.source_id
       JOIN public.financial_accounts fa ON fa.id=es.account_id
       WHERE et.id=hit.external_transaction_id AND et.direction='IN' AND et.currency='VES'
        AND fa.code=hit.actual_account AND abs(et.amount-p.amount_original)<=0.01
        AND right(regexp_replace(coalesce(et.reference,''),'[^0-9]','','g'),length(p.reference))=p.reference)
   THEN RAISE EXCEPTION 'La evidencia bancaria ya no coincide'; END IF;
   IF EXISTS(SELECT 1 FROM public.reconciliation_allocations a
       JOIN public.account_movements m ON m.id=a.account_movement_id
       WHERE a.reversed_at IS NULL AND m.source_payment_id=p.id)
       OR EXISTS(SELECT 1 FROM public.order_tenders t WHERE t.payment_id=p.id)
   THEN RAISE EXCEPTION 'Tiene conciliación activa o vuelto auditado'; END IF;
   SELECT id INTO target_account FROM public.financial_accounts WHERE code=hit.actual_account AND active;
   IF target_account IS NULL THEN RAISE EXCEPTION 'La cuenta destino no está activa'; END IF;
   SELECT to_jsonb(m) INTO old_movement FROM public.account_movements m
    WHERE m.source_payment_id=p.id FOR UPDATE;
   IF old_movement IS NULL THEN RAISE EXCEPTION 'Falta movimiento de caja original'; END IF;
   UPDATE public.payments SET
      method=CASE WHEN hit.actual_account='BDV' THEN 'TRANSFER_BDV' ELSE 'TRANSFER_BNC' END,
      financial_account_id=target_account
    WHERE id=p.id;
   UPDATE public.account_movements SET account_id=target_account
    WHERE source_payment_id=p.id;
   UPDATE public.cashea_sales s SET initial_payment_method=
      CASE WHEN (SELECT count(DISTINCT ip.method) FROM public.payments ip
        WHERE ip.order_id=p.order_id AND NOT EXISTS
         (SELECT 1 FROM public.audit_events a WHERE a.event_type='cashea.installment_payment_recorded'
          AND a.data->>'payment_id'=ip.id::text))=1
        THEN (SELECT min(ip.method) FROM public.payments ip WHERE ip.order_id=p.order_id
         AND NOT EXISTS(SELECT 1 FROM public.audit_events a
          WHERE a.event_type='cashea.installment_payment_recorded'
          AND a.data->>'payment_id'=ip.id::text)) ELSE 'MIXED' END
    WHERE s.order_id=p.order_id AND s.status IN ('ACTIVE','SETTLED')
    AND NOT EXISTS(SELECT 1 FROM public.audit_events a
         WHERE a.event_type='cashea.installment_payment_recorded'
           AND a.data->>'payment_id'=p.id::text);
   INSERT INTO public.audit_events(event_type,entity_type,entity_id,actor_id,data)
    VALUES('finance.bank_autocorrected','payment',p.id,auth.uid(),jsonb_build_object(
     'previous_payment',to_jsonb(p),'previous_movement',old_movement,
     'external_transaction_id',hit.external_transaction_id,
     'actual_account',hit.actual_account,'reason','Referencia, fecha e importe exactos; coincidencia bancaria única',
     'new_sale',false,'bank_refund',false));
   fixed:=fixed+1;
  EXCEPTION WHEN OTHERS THEN
    skipped:=skipped+1;
    errors:=errors||jsonb_build_array(jsonb_build_object('payment_id',hit.payment_id,'error',SQLERRM));
  END;
 END LOOP;
 RETURN jsonb_build_object('corrected',fixed,'skipped',skipped,'errors',errors);
END $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_bank_outflows_review(p_from date, p_to date, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 perform lubricenter_private.finance_require();
 if p_from is null or p_to is null or p_to < p_from or p_to-p_from > 366 then
  raise exception 'Selecciona un período válido (máximo 366 días)';
 end if;
 select jsonb_build_object(
  'total', (select count(*) from public.external_transactions x join public.external_sources s on s.id=x.source_id
     where s.provider='BDV' and x.direction='OUT' and timezone('America/Caracas',x.occurred_at)::date between p_from and p_to),
  'pending', (select count(*) from public.external_transactions x join public.external_sources s on s.id=x.source_id
     where s.provider='BDV' and x.direction='OUT' and x.nature='UNCLASSIFIED'
       and timezone('America/Caracas',x.occurred_at)::date between p_from and p_to),
  'rows', coalesce((
    select jsonb_agg(to_jsonb(r) order by r.occurred_at desc,r.id desc) from (
      select x.id,x.occurred_at,x.reference,x.description,x.amount::text amount,x.currency,
       x.nature,x.category,x.category_id,x.ownership_status,x.classification_reason,
       exists(select 1 from public.reconciliation_allocations a where a.external_transaction_id=x.id and a.reversed_at is null) allocated
      from public.external_transactions x join public.external_sources s on s.id=x.source_id
      where s.provider='BDV' and x.direction='OUT'
        and timezone('America/Caracas',x.occurred_at)::date between p_from and p_to
      order by x.occurred_at desc,x.id desc limit 100 offset greatest(coalesce(p_offset,0),0)
    ) r),'[]'::jsonb),
  'accounts',coalesce((
    select jsonb_agg(jsonb_build_object('id',a.id,'code',a.code,'name',a.name,'currency',a.currency))
    from public.financial_accounts a where a.active and a.currency='VES'),'[]'::jsonb),
  'sources',coalesce((
    select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name))
    from public.external_sources s where s.provider='BDV' and s.active and s.account_id is not null),'[]'::jsonb),
  'categories',coalesce((
    select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'nature',c.nature))
    from public.finance_categories c where c.active),'[]'::jsonb)
 ) into v_result;
 return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_batch(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 perform lubricenter_private.finance_require();
 select to_jsonb(b)-'payload' into v_result
  from public.external_import_batches b where b.id=p_id;
 if v_result is null then raise exception 'Reporte no encontrado'; end if;
 return v_result;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_batches(p_from date, p_to date, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform lubricenter_private.finance_require();
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>366 then
  raise exception 'Selecciona un período válido de máximo un año';
 end if;
 return jsonb_build_object(
  'total',(select count(*) from public.external_import_batches b
   where b.requested_from<=p_to and b.requested_to>=p_from),
  'batches',coalesce((select jsonb_agg(to_jsonb(q)) from (
   select b.id,b.source_id,b.source_name,b.status,b.requested_from,b.requested_to,
    b.row_count,b.balance_chain,b.created_at,b.verified_at
   from public.external_import_batches b
   where b.requested_from<=p_to and b.requested_to>=p_from
   order by b.created_at desc,b.id desc limit 20 offset greatest(p_offset,0)
  ) q),'[]'::jsonb)
 );
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_activate(p_account_id uuid, p_amount numeric, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform lubricenter_private.finance_require('OWNER');
 perform pg_advisory_xact_lock(220033);
 if not exists(select 1 from public.financial_accounts where id=p_account_id and account_type='CASH' and code in ('CASH_USD','CASH_VES') and active) then raise exception 'Selecciona Caja USD o Caja Bs'; end if;
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Describe el conteo inicial'; end if;
 insert into public.finance_cash_openings(account_id,effective_at,amount,reason) values(p_account_id,clock_timestamp(),p_amount,p_reason);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_close(p_business_date date, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; c public.cash_closings; t record; d public.cash_closing_accounts;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 perform pg_advisory_xact_lock(220033);
 select id into v_location from public.locations where active order by created_at limit 1;
 select * into c from public.cash_closings where business_date=p_business_date and location_id=v_location for update;
 if not found then raise exception 'Primero cuenta Caja USD y Caja Bs'; end if;
 if c.status='CLOSED' then return c.id; end if;
 if c.finance_version is null then raise exception 'Este cierre pertenece al control histórico'; end if;
 if c.status in ('REVIEW','REOPENED') then perform lubricenter_private.finance_require(); end if;
 if (select count(*) from lubricenter_private.finance_cash_totals(p_business_date))<>2 then raise exception 'Configura Caja USD y Caja Bs'; end if;
 for t in select * from lubricenter_private.finance_cash_totals(p_business_date) loop
  select * into d from public.cash_closing_accounts where cash_closing_id=c.id and account_id=t.id;
  if not t.activated or d.actual_native is null then raise exception 'Falta el conteo de %',t.name; end if;
  if d.expected_native<>t.expected_native or d.system_in_native<>t.system_in_native or d.system_out_native<>t.system_out_native then raise exception 'Hubo movimientos después del conteo de %. Confirma nuevamente el efectivo',t.name; end if;
 end loop;
 -- A discrepancy is an administrative case, never a block on tomorrow's sales.
 update public.cash_closings set status='CLOSED',notes=nullif(trim(p_notes),''),closed_by=auth.uid(),closed_at=now(),review_reason=null,updated_at=now() where id=c.id;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('finance.cash_closed','cash_closing',c.id,jsonb_build_object('business_date',p_business_date));
 for d in select * from public.cash_closing_accounts where cash_closing_id=c.id loop
  if abs(d.difference_native)>(case when (select currency from public.financial_accounts where id=d.account_id)='USD' then 0.01 else 1 end) then
   perform lubricenter_private.finance_case('cash:'||c.id||':'||d.account_id,'CASH_VARIANCE','cash_closing',c.id,'Diferencia en efectivo','Se guardó el conteo sin inventar un ajuste contable.',jsonb_build_object('account_id',d.account_id,'difference',d.difference_native,'explanation',d.explanation));
  end if;
 end loop;
 return c.id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_count(p_business_date date, p_account_id uuid, p_actual_native numeric, p_explanation text DEFAULT NULL::text, p_denominations jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; c public.cash_closings; t record;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 perform pg_advisory_xact_lock(220033);
 if p_business_date is null or p_business_date>timezone('America/Caracas',now())::date then raise exception 'Fecha de conteo inválida'; end if;
 if p_actual_native is null or p_actual_native<0 or p_actual_native>='Infinity'::numeric then raise exception 'Escribe el efectivo contado; cero es válido'; end if;
 select * into t from lubricenter_private.finance_cash_totals(p_business_date) where id=p_account_id;
 if not found or not t.activated then raise exception 'El dueño debe registrar primero el conteo de apertura de esta caja'; end if;
 select id into v_location from public.locations where active order by created_at limit 1;
 insert into public.cash_closings(business_date,location_id,finance_version) values(p_business_date,v_location,22) on conflict(business_date,location_id) do nothing;
 select * into c from public.cash_closings where business_date=p_business_date and location_id=v_location for update;
 if c.finance_version is null then raise exception 'Cierre histórico conservado. Inicia el nuevo control desde la apertura física'; end if;
 if c.status='CLOSED' then raise exception 'El día está cerrado; pide al dueño que lo reabra'; end if;
 if c.status in ('REVIEW','REOPENED') then perform lubricenter_private.finance_require(); end if;
 insert into public.cash_closing_accounts(cash_closing_id,account_id,opening_native,system_in_native,system_out_native,expected_native,actual_native,difference_native,explanation,denomination_counts,updated_by,updated_at)
 values(c.id,p_account_id,t.opening_native,t.system_in_native,t.system_out_native,t.expected_native,p_actual_native,p_actual_native-t.expected_native,nullif(trim(p_explanation),''),p_denominations,auth.uid(),now())
 on conflict(cash_closing_id,account_id) do update set opening_native=excluded.opening_native,system_in_native=excluded.system_in_native,system_out_native=excluded.system_out_native,expected_native=excluded.expected_native,actual_native=excluded.actual_native,difference_native=excluded.difference_native,explanation=excluded.explanation,denomination_counts=excluded.denomination_counts,updated_by=auth.uid(),updated_at=now();
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('finance.cash_count','cash_closing',c.id,jsonb_build_object('account',p_account_id,'actual',p_actual_native,'expected',t.expected_native));
 return c.id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_dashboard(p_business_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_day date:=coalesce(p_business_date,timezone('America/Caracas',now())::date); v_location uuid; v_close public.cash_closings; v_accounts jsonb;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 select id into v_location from public.locations where active order by created_at limit 1;
 select * into v_close from public.cash_closings where business_date=v_day and location_id=v_location;
 if v_close.id is not null and v_close.finance_version is null then
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into v_accounts from (select a.id,a.code,a.name,a.currency,a.account_type,true activated,d.opening_native,d.system_in_native,d.system_out_native,d.expected_native,d.actual_native,d.difference_native,d.explanation,d.denomination_counts,d.updated_at counted_at from public.cash_closing_accounts d join public.financial_accounts a on a.id=d.account_id where d.cash_closing_id=v_close.id) q;
 else
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into v_accounts from (select a.*,d.actual_native,d.difference_native,d.explanation,d.denomination_counts,d.updated_at counted_at from lubricenter_private.finance_cash_totals(v_day) a left join public.cash_closing_accounts d on d.cash_closing_id=v_close.id and d.account_id=a.id) q;
 end if;
 return jsonb_build_object('business_date',v_day,'location_id',v_location,'role',lubricenter_private.finance_role(),'legacy',v_close.id is not null and v_close.finance_version is null,'status',coalesce(v_close.status,'OPEN'),'closing',case when v_close.id is null then null else to_jsonb(v_close) end,'accounts',v_accounts);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_due(p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; v_today date:=timezone('America/Caracas',now())::date;
 v_openings integer; v_start date; v_total integer; v_tasks jsonb;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 if p_offset is null or p_offset<0 then raise exception 'Página inválida'; end if;
 select id into v_location from public.locations where active order by created_at limit 1;
 if v_location is null then
  return jsonb_build_object('status','NEEDS_LOCATION','total',0,'tasks','[]'::jsonb);
 end if;
 select count(*),max(timezone('America/Caracas',o.effective_at)::date)
  into v_openings,v_start
  from public.finance_cash_openings o
  join public.financial_accounts a on a.id=o.account_id
  where a.active and a.account_type='CASH' and a.code in ('CASH_USD','CASH_VES');
 if v_openings<>2 then
  return jsonb_build_object('status','NEEDS_OPENING','total',0,'tasks','[]'::jsonb);
 end if;
 with activity as (
  select distinct timezone('America/Caracas',m.occurred_at)::date business_date
   from public.account_movements m
   join public.financial_accounts a on a.id=m.account_id
   join public.finance_cash_openings o on o.account_id=a.id
   where a.active and a.account_type='CASH' and a.code in ('CASH_USD','CASH_VES')
    and m.occurred_at>=o.effective_at
  union
  select c.business_date from public.cash_closings c
   where c.location_id=v_location and c.finance_version=22
 ), due as (
  select d.business_date,c.status closing_status
   from activity d
   left join public.cash_closings c
    on c.location_id=v_location and c.business_date=d.business_date
   where d.business_date>=v_start and d.business_date<v_today
    and (c.id is null or c.status<>'CLOSED')
 ), numbered as (
  select *,row_number() over(order by business_date desc) rn from due
 )
 select count(*)::integer,
  coalesce(jsonb_agg(jsonb_build_object(
   'task_key','cash:'||v_location||':'||business_date,
   'business_date',business_date,
   'kind',case when closing_status='REVIEW' then 'REVIEW' else 'CLOSE' end,
   'title',case when closing_status='REVIEW' then 'Revisar cuadre de caja' else 'Falta cerrar caja' end,
   'reason',case when closing_status='REVIEW'
    then 'Un movimiento o conteo cambió después del cierre'
    else 'Hay actividad de efectivo o un conteo iniciado sin cierre' end,
   'action_url','/cash-close?day='||business_date
  ) order by business_date desc) filter(where rn>p_offset and rn<=p_offset+20),'[]'::jsonb)
 into v_total,v_tasks from numbered;
 return jsonb_build_object('status','ACTIVE','total',v_total,'tasks',v_tasks);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_open_recount_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_close public.cash_closings; v_revision uuid;
begin
 if old.actual_native is null or
    (old.actual_native is not distinct from new.actual_native
     and old.explanation is not distinct from new.explanation) then
   return new;
 end if;
 select * into v_close from public.cash_closings where id=new.cash_closing_id;
 if v_close.finance_version is distinct from 22 or v_close.status not in ('OPEN','REOPENED')
 then return new; end if;
 if length(trim(coalesce(new.explanation,'')))<8 then
   raise exception 'Explica por qué se modificó un conteo anterior (mínimo 8 caracteres)';
 end if;
 insert into public.finance_cash_close_revisions
   (cash_closing_id,account_id,actor_id,revision_type,reason,before_snapshot,after_snapshot)
 values(new.cash_closing_id,new.account_id,auth.uid(),'COUNT_DRAFT_CORRECTION',
        trim(new.explanation),to_jsonb(old),to_jsonb(new)) returning id into v_revision;
 perform lubricenter_private.finance_cash_notify_owners(
   v_close.location_id,v_close.id,'COUNT_DRAFT_CORRECTION',
   'Se corrigió un conteo del '||v_close.business_date::text||
    ' antes de finalizar el cierre: '||left(trim(new.explanation),120),v_revision);
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cash_recount_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_day date; v_close uuid;
begin
 if old.actual_native is distinct from new.actual_native then
  select business_date into v_day from public.cash_closings where id=new.cash_closing_id;
  select c.id into v_close from public.cash_closings c
   join public.cash_closing_accounts ca on ca.cash_closing_id=c.id
   where ca.account_id=new.account_id and ca.actual_native is not null
    and c.finance_version=22 and c.status in ('CLOSED','REVIEW')
    and c.business_date>v_day
   order by c.business_date,c.id limit 1;
  update public.cash_closings set status='REVIEW',
   review_reason='Se corrigió un conteo anterior que afecta la apertura',
   updated_at=now()
  where id=v_close and status='CLOSED';
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cashea_balance_entry(p_request_id uuid, p_kind text, p_date date, p_amount numeric, p_reference text, p_evidence text, p_statement_id uuid DEFAULT NULL::uuid, p_bank_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_statement public.cashea_merchant_statements; v_bank public.external_transactions; v_old public.cashea_balance_events;
begin
 perform lubricenter_private.finance_require(case when p_kind in ('OPENING_CREDIT','OPENING_DEBIT','ADJUSTMENT_CREDIT','ADJUSTMENT_DEBIT') then 'OWNER' else 'ADMIN' end);
 if p_request_id is null then raise exception 'Falta identificador de solicitud'; end if;
 if p_kind not in ('OPENING_CREDIT','OPENING_DEBIT','COVERAGE_CREDIT','SERVICE_DEDUCTION','PAYOUT','ADJUSTMENT_CREDIT','ADJUSTMENT_DEBIT') then raise exception 'Tipo de balance Cashea inválido'; end if;
 if p_date is null or p_date>timezone('America/Caracas',now())::date then raise exception 'Fecha del movimiento inválida'; end if;
 if p_amount is null or p_amount<=0 or p_amount>='Infinity'::numeric or p_amount<>round(p_amount,2) then raise exception 'Importe USD inválido'; end if;
 if p_reference is null or length(trim(p_reference))<3 or p_evidence is null or length(trim(p_evidence))<5 then raise exception 'Indica referencia y evidencia comprobable'; end if;
 if (p_kind='SERVICE_DEDUCTION')<>(p_statement_id is not null) or (p_bank_transaction_id is not null and p_kind<>'PAYOUT') then raise exception 'Vínculo de balance inválido'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,24));
 select * into v_old from public.cashea_balance_events where request_id=p_request_id;
 if found then
  if row(v_old.kind,v_old.occurred_on,v_old.amount_ref,v_old.reference,v_old.evidence,v_old.statement_id,v_old.bank_transaction_id) is distinct from row(p_kind,p_date,p_amount,trim(p_reference),trim(p_evidence),p_statement_id,p_bank_transaction_id) then raise exception 'La solicitud ya fue guardada con otros datos. Recarga antes de corregir'; end if;
  return v_old.id;
 end if;
 if p_kind='SERVICE_DEDUCTION' then
  select * into v_statement from public.cashea_merchant_statements where id=p_statement_id for update;
  if not found or v_statement.voided_at is not null or p_amount<>v_statement.total_deduct_ref or p_date<v_statement.period_to then raise exception 'El descuento debe coincidir con la factura vigente y ser posterior al período'; end if;
 end if;
 if p_bank_transaction_id is not null then
  select * into v_bank from public.external_transactions where id=p_bank_transaction_id for update;
  if not found or v_bank.direction<>'IN' or v_bank.ownership_status<>'OWN' or v_bank.amount_ref is null or abs(v_bank.amount_ref-p_amount)>0.01 or v_bank.reference<>trim(p_reference) or timezone('America/Caracas',v_bank.occurred_at)::date<>p_date or not exists(select 1 from public.external_sources s join public.financial_accounts a on a.id=s.account_id where s.id=v_bank.source_id and s.provider in ('BDV','BNC') and a.account_type='BANK') then
   raise exception 'El pago no coincide con un ingreso bancario propio comprobado';
  end if;
 end if;
 insert into public.cashea_balance_events(request_id,kind,occurred_on,amount_ref,reference,evidence,statement_id,bank_transaction_id)
 values(p_request_id,p_kind,p_date,p_amount,trim(p_reference),trim(p_evidence),p_statement_id,p_bank_transaction_id) returning id into v_id;
 return v_id;
exception when unique_violation then raise exception 'Ya existe un registro activo para este movimiento, factura o apertura';
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cashea_balance_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_opening date; v_net numeric; v_total integer;
begin
 perform lubricenter_private.finance_require();
 select occurred_on into v_opening from public.cashea_balance_events where kind in ('OPENING_CREDIT','OPENING_DEBIT') and reversed_at is null;
 select coalesce(sum(amount_ref*case when kind in ('SERVICE_DEDUCTION','PAYOUT','OPENING_DEBIT','ADJUSTMENT_DEBIT') then -1 else 1 end),0)
 into v_net from public.cashea_balance_events where reversed_at is null and (v_opening is null or occurred_on>=v_opening);
 select count(*) into v_total from public.cashea_balance_events;
 return jsonb_build_object('opening_on',v_opening,'recorded_net',v_net::text,'events_total',v_total,
  'pending_bank_payouts',(select count(*) from public.cashea_balance_events where kind='PAYOUT' and reversed_at is null and bank_transaction_id is null),
  'statements_total',(select count(*) from public.cashea_merchant_statements),
  'pending_deductions',(select count(*) from public.cashea_merchant_statements s where voided_at is null and not exists(select 1 from public.cashea_balance_events e where e.statement_id=s.id and e.reversed_at is null)));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cashea_charges(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 perform lubricenter_private.finance_require();
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>366 then raise exception 'Período inválido'; end if;
 select jsonb_build_object('count',count(*),'service_ref',coalesce(sum(service_ref),0)::text,
  'vat_ref',coalesce(sum(vat_ref),0)::text,'withholding_ref',coalesce(sum(withholding_ref),0)::text,
  'total_deduct_ref',coalesce(sum(total_deduct_ref),0)::text,
  'unattributed',count(*) filter(where ownership_status<>'OWN')) into v_result
 from public.cashea_merchant_statements where voided_at is null and period_to between p_from and p_to;
 return v_result;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cashea_ownership(p_id uuid, p_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform lubricenter_private.finance_require();
 if p_status is null or p_status not in ('OWN','SHARED','UNRESOLVED') or p_reason is null or length(trim(p_reason))<5 then raise exception 'Indica propiedad y evidencia de la factura'; end if;
 perform 1 from public.cashea_merchant_statements where id=p_id and voided_at is null for update;
 if not found then raise exception 'Factura no disponible'; end if;
 update public.cashea_merchant_statements set ownership_status=p_status,ownership_reason=trim(p_reason)
 where id=p_id and row(ownership_status,ownership_reason) is distinct from row(p_status,trim(p_reason));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cashea_reverse(p_kind text, p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform lubricenter_private.finance_require('OWNER');
 if p_id is null or p_reason is null or length(trim(p_reason))<5 then raise exception 'Explica la corrección'; end if;
 if p_kind='EVENT' then
  update public.cashea_balance_events set reversed_at=now(),reversed_by=auth.uid(),reversal_reason=trim(p_reason)
   where id=p_id and reversed_at is null;
  if not found then raise exception 'Movimiento no disponible para corregir'; end if;
 elsif p_kind='STATEMENT' then
  perform 1 from public.cashea_merchant_statements where id=p_id and voided_at is null for update;
  if not found then raise exception 'Factura no disponible para corregir'; end if;
  if exists(select 1 from public.cashea_balance_events where statement_id=p_id and reversed_at is null) then raise exception 'Revierte primero el descuento vinculado'; end if;
  update public.cashea_merchant_statements set voided_at=now(),voided_by=auth.uid(),void_reason=trim(p_reason) where id=p_id;
  update public.reconciliation_cases set status='RESOLVED',resolution='Factura anulada: '||trim(p_reason),resolved_at=now(),resolved_by=auth.uid() where subject_id=p_id and kind='CASHEA_SERVICE_VARIANCE' and status='OPEN';
 else raise exception 'Tipo de corrección inválido'; end if;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_cashea_statement(p_request_id uuid, p_from date, p_to date, p_invoice text, p_sales numeric, p_percent numeric, p_service numeric, p_vat numeric, p_withholding numeric, p_evidence text, p_ownership_status text DEFAULT 'UNRESOLVED'::text, p_ownership_reason text DEFAULT 'Pendiente de atribuir a Lubricenter'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_old public.cashea_merchant_statements;
begin
 perform lubricenter_private.finance_require();
 if p_request_id is null then raise exception 'Falta identificador de solicitud'; end if;
 if p_invoice is null or length(trim(p_invoice))<3 then raise exception 'Escribe el número de factura Cashea'; end if;
 if p_evidence is null or length(trim(p_evidence))<5 then raise exception 'Indica la evidencia de la factura'; end if;
 if p_from is null or p_to is null or p_from>p_to or p_to>timezone('America/Caracas',now())::date or p_to-p_from>366 then raise exception 'Revisa el período de la factura'; end if;
 if p_sales is null or p_sales<=0 or p_sales>='Infinity'::numeric or p_percent is null or p_percent<0 or p_percent>100 or p_service is null or p_service<0 or p_service>='Infinity'::numeric or p_vat is null or p_vat<0 or p_vat>='Infinity'::numeric or coalesce(p_withholding,0)<0 or coalesce(p_withholding,0)>='Infinity'::numeric then raise exception 'Importes de factura inválidos'; end if;
 if p_sales<>round(p_sales,2) or p_service<>round(p_service,2) or p_vat<>round(p_vat,2) or coalesce(p_withholding,0)<>round(coalesce(p_withholding,0),2) then raise exception 'Usa hasta dos decimales en los importes de factura'; end if;
 -- The request ID guards retries; period and invoice guard duplicate economic facts.
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,23));
 select * into v_old from public.cashea_merchant_statements where id=p_request_id;
 if found then
  if row(v_old.period_from,v_old.period_to,v_old.invoice_number,v_old.sales_ref,v_old.commission_percent,v_old.service_ref,v_old.vat_ref,v_old.withholding_ref,v_old.evidence,v_old.ownership_status,v_old.ownership_reason) is distinct from row(p_from,p_to,trim(p_invoice),p_sales,p_percent,p_service,p_vat,coalesce(p_withholding,0),trim(p_evidence),p_ownership_status,trim(p_ownership_reason)) then raise exception 'La solicitud ya fue guardada con otros datos. Recarga antes de corregir'; end if;
  return v_old.id;
 end if;
 insert into public.cashea_merchant_statements(id,period_from,period_to,invoice_number,sales_ref,commission_percent,service_ref,vat_ref,withholding_ref,evidence,ownership_status,ownership_reason)
 values(p_request_id,p_from,p_to,trim(p_invoice),p_sales,p_percent,p_service,p_vat,coalesce(p_withholding,0),trim(p_evidence),p_ownership_status,trim(p_ownership_reason)) returning id into v_id;
 if abs(p_service-round(p_sales*p_percent/100,2))>0.02 then
  perform lubricenter_private.finance_case('cashea_service:'||v_id,'CASHEA_SERVICE_VARIANCE','cashea_merchant_statement',v_id,'Revisar cálculo de comisión Cashea','La factura difiere del porcentaje sobre las ventas informadas. Se conservó el documento sin cambiar caja ni ventas.',jsonb_build_object('invoice_number',trim(p_invoice),'sales_ref',p_sales,'commission_percent',p_percent,'service_ref',p_service,'difference_ref',p_service-round(p_sales*p_percent/100,2)));
 end if;
 return v_id;
exception when unique_violation then raise exception 'Esta factura o período ya está registrado. Revisa el historial antes de guardar';
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_category_upsert(p_name text, p_nature text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_nature text; v_name text:=trim(p_name);
begin
 perform lubricenter_private.finance_require();
 if length(v_name)<1 or length(v_name)>80 then raise exception 'Nombre de categoría inválido'; end if;
 if p_nature not in ('EXPENSE','INVENTORY_PURCHASE','ASSET_PURCHASE','SUPPLIER_PAYMENT','OWNER_DRAW','PAYROLL','INTERNAL_TRANSFER','REFUND','TAX','BANK_FEE','OWNER_CONTRIBUTION','OTHER_INCOME') then raise exception 'Naturaleza inválida'; end if;
 select id,nature into v_id,v_nature from public.finance_categories where lower(trim(name))=lower(v_name) for update;
 if found then
   if v_nature<>p_nature then raise exception 'La categoría ya existe con otra naturaleza'; end if;
   update public.finance_categories set active=true,updated_at=now() where id=v_id;
   return v_id;
 end if;
 insert into public.finance_categories(name,nature,created_by) values(v_name,p_nature,auth.uid()) returning id into v_id;
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('finance.category_created','finance_category',v_id,jsonb_build_object('name',v_name,'nature',p_nature));
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_classify_external(p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 x public.external_transactions; s public.external_sources; c public.finance_categories;
 v_nature text:=p_data->>'nature'; v_reason text; v_value_ves numeric; v_rate numeric:=1;
 v_movement uuid; v_counter uuid; v_target public.financial_accounts; v_group uuid;
 v_candidates integer; v_rule uuid; v_category_name text;
begin
 perform lubricenter_private.finance_require();
 select * into x from public.external_transactions where id=p_id for update;
 if not found then raise exception 'Movimiento no encontrado'; end if;
 select * into s from public.external_sources where id=x.source_id;
 if s.account_id is null then raise exception 'Esta fuente todavía no está vinculada a una cuenta financiera'; end if;
 if x.ownership_status<>'OWN' then raise exception 'Resuelve primero a quién pertenece el movimiento'; end if;
 if exists(select 1 from public.reconciliation_cases rc where rc.subject_id=x.id and rc.status='OPEN' and rc.kind in ('SOURCE_CONFLICT','SOURCE_AMOUNT')) then
   raise exception 'Resuelve primero la inconsistencia del reporte';
 end if;

 if x.direction='OUT' and v_nature not in ('EXPENSE','INVENTORY_PURCHASE','ASSET_PURCHASE','SUPPLIER_PAYMENT','OWNER_DRAW','PAYROLL','INTERNAL_TRANSFER','REFUND','TAX','BANK_FEE') then
   raise exception 'Naturaleza de salida inválida';
 elsif x.direction='IN' and v_nature not in ('OWNER_CONTRIBUTION','OTHER_INCOME','INTERNAL_TRANSFER','REFUND') then
   raise exception 'Naturaleza de entrada inválida';
 end if;
 if v_nature='OWNER_DRAW' then perform lubricenter_private.finance_require('OWNER'); end if;

 if nullif(p_data->>'category_id','') is not null then
   select * into c from public.finance_categories where id=(p_data->>'category_id')::uuid and active;
   if not found then raise exception 'Categoría no disponible'; end if;
   if c.nature<>v_nature then raise exception 'La categoría no corresponde a esta naturaleza'; end if;
   v_category_name:=c.name;
 elsif v_nature not in ('INTERNAL_TRANSFER','REFUND') then
   raise exception 'Selecciona una categoría';
 end if;

 v_reason:=coalesce(nullif(trim(p_data->>'note'),''),'Conciliación: '||coalesce(v_category_name,v_nature));
 update public.external_transactions
 set nature=v_nature,category=v_category_name,category_id=c.id,classification_reason=v_reason
 where id=x.id;

 select id into v_movement from public.account_movements where finance_request_id=x.id;
 if v_movement is not null then
   return jsonb_build_object('movement_id',v_movement,'created',false);
 end if;
 if exists(select 1 from public.reconciliation_allocations where external_transaction_id=x.id and reversed_at is null) then
   raise exception 'Este movimiento ya tiene una asignación. Revísala antes de reclasificar';
 end if;

 select count(*),(array_agg(m.id order by m.occurred_at,m.id))[1]
 into v_candidates,v_movement
 from public.account_movements m
 where m.account_id=s.account_id and m.direction=x.direction and m.currency=x.currency
   and abs(m.amount_original-x.amount)<=least(5,x.amount*.001)
   and m.occurred_at between x.occurred_at-interval '48 hours' and x.occurred_at+interval '48 hours'
   and not exists(select 1 from public.reconciliation_allocations a where a.account_movement_id=m.id and a.reversed_at is null)
   and (
     (v_nature='INTERNAL_TRANSFER' and m.transfer_group is not null and m.finance_nature='INTERNAL_TRANSFER')
     or
     (v_nature<>'INTERNAL_TRANSFER'
      and length(regexp_replace(coalesce(m.reference,''),'\D','','g'))>=4
      and right(regexp_replace(coalesce(m.reference,''),'\D','','g'),4)=right(x.reference,4))
   );

 if v_candidates>1 then raise exception 'Hay varios registros internos parecidos. Revísalos antes de registrar otro'; end if;

 if v_candidates=1 then
   update public.account_movements
   set finance_nature=coalesce(finance_nature,v_nature),
       category=coalesce(category,v_category_name),
       category_id=coalesce(category_id,c.id)
   where id=v_movement;
 else
   if x.currency='USD' then
     select value into v_rate from public.exchange_rates
     where rate_type='OPERATIVE' and timezone('America/Caracas',effective_at)::date<=timezone('America/Caracas',x.occurred_at)::date
     order by effective_at desc limit 1;
     if v_rate is null then raise exception 'Falta la tasa operativa histórica'; end if;
   end if;
   v_value_ves:=round(x.amount*v_rate,2);

   if v_nature='INTERNAL_TRANSFER' then
     if nullif(p_data->>'target_account_id','') is null then raise exception 'Selecciona la otra cuenta de la transferencia'; end if;
     select * into v_target from public.financial_accounts where id=(p_data->>'target_account_id')::uuid and active;
     if not found or v_target.id=s.account_id or v_target.currency<>x.currency then raise exception 'Cuenta destino incompatible'; end if;
     v_group:=gen_random_uuid();
     insert into public.account_movements(account_id,direction,movement_type,transfer_group,currency,amount_original,value_ves,category,category_id,note,reference,occurred_at,finance_nature,finance_request_id)
     values(s.account_id,x.direction,'TRANSFER',v_group,x.currency,x.amount,v_value_ves,v_category_name,c.id,v_reason,x.reference,x.occurred_at,v_nature,x.id)
     returning id into v_movement;
     insert into public.account_movements(account_id,direction,movement_type,transfer_group,currency,amount_original,value_ves,category,category_id,note,reference,occurred_at,finance_nature)
     values(v_target.id,case when x.direction='OUT' then 'IN' else 'OUT' end,'TRANSFER',v_group,x.currency,x.amount,v_value_ves,v_category_name,c.id,'Contrapartida · '||v_reason,x.reference,x.occurred_at,v_nature)
     returning id into v_counter;
   else
     insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,category_id,note,reference,occurred_at,finance_nature,finance_request_id)
     values(s.account_id,x.direction,
       case when v_nature in ('EXPENSE','PAYROLL','TAX','BANK_FEE') then 'EXPENSE'
            when v_nature in ('INVENTORY_PURCHASE','SUPPLIER_PAYMENT') then 'SUPPLIER_PAYMENT'
            else 'ADJUSTMENT' end,
       x.currency,x.amount,v_value_ves,v_category_name,c.id,v_reason,x.reference,x.occurred_at,v_nature,x.id)
     returning id into v_movement;
   end if;
 end if;

 perform lubricenter_private.finance_allocate(gen_random_uuid(),x.id,v_movement,null,x.amount,x.amount,'EXACT',v_reason);

 update public.reconciliation_cases
 set status='RESOLVED',resolution=v_reason,resolved_by=auth.uid(),resolved_at=now()
 where status='OPEN' and subject_type='external_transaction' and subject_id=x.id and kind in ('UNCLASSIFIED','UNMATCHED');

 if coalesce((p_data->>'save_rule')::boolean,false) then
   perform lubricenter_private.finance_require('OWNER');
   if x.direction<>'OUT' or v_nature not in ('BANK_FEE','EXPENSE') then raise exception 'Solo se automatizan comisiones y gastos repetitivos explícitos'; end if;
   insert into public.reconciliation_rules(source_id,description_contains,nature,category,category_id,approved_by)
   values(x.source_id,upper(trim(x.description)),v_nature,v_category_name,c.id,auth.uid())
   returning id into v_rule;
 end if;

 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('finance.external_classified','external_transaction',x.id,
   jsonb_build_object('nature',v_nature,'category_id',c.id,'movement_id',v_movement,'counter_movement_id',v_counter,'rule_id',v_rule));
 return jsonb_build_object('movement_id',v_movement,'counter_movement_id',v_counter,'rule_id',v_rule,'created',v_candidates=0);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_configure(p_action text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
 perform lubricenter_private.finance_require('OWNER');
 if p_action='MEMBERSHIP' then
  insert into public.finance_memberships(user_id,role,granted_by) values((p_data->>'user_id')::uuid,p_data->>'role',auth.uid())
  on conflict(user_id) do update set role=excluded.role,granted_by=auth.uid(),granted_at=now();
  return (p_data->>'user_id')::uuid;
 elsif p_action='SOURCE' then
  if p_data->>'provider'='BDV' and not exists(select 1 from public.financial_accounts where id=(p_data->>'account_id')::uuid and code='BDV' and currency='VES' and active) then raise exception 'Selecciona la cuenta Banco de Venezuela'; end if;
  insert into public.external_sources(provider,name,account_id,external_account,currency) values(p_data->>'provider',p_data->>'name',nullif(p_data->>'account_id','')::uuid,coalesce(p_data->>'external_account',''),p_data->>'currency') returning id into v_id;
 elsif p_action='RULE' then
  insert into public.reconciliation_rules(source_id,description_contains,nature,category,approved_by) values(nullif(p_data->>'source_id','')::uuid,upper(trim(p_data->>'description_contains')),p_data->>'nature',p_data->>'category',auth.uid()) returning id into v_id;
 elsif p_action='DISABLE_RULE' then
  update public.reconciliation_rules set active=false where id=(p_data->>'id')::uuid returning id into v_id;
 else raise exception 'Acción de configuración inválida'; end if;
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_guard_allocated_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='account_movements' then
  if (new.account_id,new.currency,new.direction,new.amount_original,new.reference,new.occurred_at,new.source_payment_id)
     is distinct from
     (old.account_id,old.currency,old.direction,old.amount_original,old.reference,old.occurred_at,old.source_payment_id)
     and exists(select 1 from public.reconciliation_allocations a
      where a.account_movement_id=old.id and a.reversed_at is null) then
   raise exception 'El movimiento tiene conciliaciones activas. Reviértelas antes de cambiar importe, cuenta, moneda, fecha o referencia';
  end if;
 elsif tg_table_name='cashea_installments' then
  if (new.cashea_sale_id,new.installment_no,new.amount_ref)
     is distinct from (old.cashea_sale_id,old.installment_no,old.amount_ref)
     and exists(select 1 from public.reconciliation_allocations a
      where a.cashea_installment_id=old.id and a.reversed_at is null) then
   raise exception 'La cuota tiene conciliaciones activas. Reviértelas antes de cambiar sus condiciones';
  end if;
 elsif tg_table_name='cashea_sales' then
  if (new.cashea_reference,new.initial_ref,new.ownership_status)
     is distinct from (old.cashea_reference,old.initial_ref,old.ownership_status)
     and exists(select 1 from public.reconciliation_allocations a
      where a.cashea_sale_id=old.id and a.reversed_at is null) then
   raise exception 'La inicial Cashea tiene conciliaciones activas. Reviértelas antes de cambiar sus condiciones';
  end if;
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_immutable_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if old.event_type like 'finance.%' then raise exception 'El historial financiero es inmutable'; end if;
 return coalesce(new,old);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_import(p_source_id uuid, p_name text, p_from date, p_to date, p_preview jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.external_sources; b uuid; t uuid; r jsonb; v_key text; v_fp text; v_own text; v_reason text; v_matches integer; v_sale uuid; v_bad boolean; v_time timestamptz;
begin
 perform lubricenter_private.finance_require();
 select * into s from public.external_sources where id=p_source_id and active for update;
 if not found then raise exception 'Fuente no disponible'; end if;
 if s.provider<>p_preview->>'provider' then raise exception 'Reporte incompatible con la fuente'; end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'Selecciona un período válido, máximo un año'; end if;
 if jsonb_typeof(p_preview->'rows')<>'array' or jsonb_typeof(p_preview->'orders')<>'array' or jsonb_typeof(p_preview->'errors')<>'array' then raise exception 'Formato del reporte inválido'; end if;
 if jsonb_array_length(p_preview->'rows')+jsonb_array_length(p_preview->'orders')>10000 then raise exception 'Importa hasta 10000 filas por lote'; end if;
 if jsonb_array_length(p_preview->'rows')+jsonb_array_length(p_preview->'orders')=0 then raise exception 'El reporte está vacío'; end if;
 v_fp:=md5(jsonb_build_object('from',p_from,'to',p_to,'rows',p_preview->'rows','orders',p_preview->'orders','errors',p_preview->'errors')::text);
 select id into b from public.external_import_batches where source_id=s.id and fingerprint=v_fp;
 if b is not null then return b; end if;
 insert into public.external_import_batches(source_id,fingerprint,source_name,requested_from,requested_to,row_count,duplicate_count,balance_chain,validation,payload)
 values(s.id,v_fp,left(p_name,200),p_from,p_to,jsonb_array_length(p_preview->'rows')+jsonb_array_length(p_preview->'orders'),coalesce((p_preview->>'duplicates')::integer,0),null,
 jsonb_build_object('errors',p_preview->'errors','warnings',p_preview->'warnings'),p_preview) returning id into b;
 for r in select value from jsonb_array_elements(p_preview->'rows') loop
  v_time:=(r->>'occurred_at')::timestamptz;
  if s.provider='CASHEA_ORDERS' or coalesce(r->>'reference','')!~'^\d+$' or coalesce(r->>'direction','') not in ('IN','OUT') or (s.provider='BDV' and r->>'currency'<>s.currency) or (s.provider='CASHEA_TRANSACTIONS' and r->>'currency' not in ('VES','USD')) or (r->>'amount')::numeric is null or (r->>'amount')::numeric<=0 or (r->>'amount')::numeric>='Infinity'::numeric then raise exception 'Movimiento inválido en fila %',r->>'row'; end if;
  if s.provider='BDV' and (r->>'balance') is null then raise exception 'Falta saldo BDV'; end if;
  if s.provider='CASHEA_TRANSACTIONS' and (coalesce(r->>'external_order','')!~'^\d+$' or (r->>'amount_ref') is null or (r->>'assigned_ref') is null or coalesce(trim(r->>'provider_account'),'')=''  or r->>'direction'<>'IN') then raise exception 'Reporte Cashea: revisa cuenta, orden y montos en fila %',r->>'row'; end if;
  v_key:=md5(jsonb_build_array(v_time,r->>'reference',r->>'direction',(r->>'amount')::numeric,case when s.provider='BDV' then (r->>'balance')::numeric else null end,coalesce(r->>'provider_account',''))::text);
  v_own:='OWN'; v_reason:='OWN_BANK_ACCOUNT'; v_sale:=null;
  if s.provider='CASHEA_TRANSACTIONS' then
   select count(*),(array_agg(id))[1] into v_matches,v_sale from public.cashea_sales where trim(cashea_reference)=r->>'external_order' and status<>'CANCELLED';
   v_own:=case when v_matches=1 then 'OWN' else 'UNRESOLVED' end; v_reason:=case when v_matches=1 then 'ORDER_MATCH' else 'UNKNOWN' end;
  end if;
  insert into public.external_transactions(source_id,identity_key,first_batch_id,occurred_at,reference,description,direction,currency,amount,balance,amount_ref,assigned_ref,exchange_rate,rate_date,external_order,installments,provider_account,channel_label,ownership_status,ownership_reason,ownership_evidence,raw)
  values(s.id,v_key,b,v_time,r->>'reference',r->>'description',r->>'direction',r->>'currency',(r->>'amount')::numeric,(r->>'balance')::numeric,(r->>'amount_ref')::numeric,(r->>'assigned_ref')::numeric,(r->>'rate')::numeric,(r->>'rate_date')::date,r->>'external_order',array(select value::integer from jsonb_array_elements_text(coalesce(r->'installments','[]'))),r->>'provider_account',r->>'channel_label',v_own,v_reason,jsonb_build_object('cashea_sale_id',v_sale),r->'raw')
  on conflict(source_id,identity_key) do nothing returning id into t;
  if t is null then
   select id into t from public.external_transactions where source_id=s.id and identity_key=v_key;
   if exists(select 1 from public.external_transactions where id=t and (external_order is distinct from r->>'external_order' or amount_ref is distinct from (r->>'amount_ref')::numeric or assigned_ref is distinct from (r->>'assigned_ref')::numeric or installments is distinct from array(select value::integer from jsonb_array_elements_text(coalesce(r->'installments','[]'))))) then
    perform lubricenter_private.finance_case('conflict:'||t,'SOURCE_CONFLICT','external_transaction',t,'Reporte con versiones distintas','El mismo cobro aparece con otra orden, cuota o importe. No se duplicó ni sobrescribió.',jsonb_build_object('batch_id',b,'row',r));
   end if;
  end if;
  insert into public.external_batch_transactions values(b,t,(r->>'row')::integer) on conflict do nothing;
  if (r->>'assigned_ref')::numeric-(r->>'amount_ref')::numeric>0.005 then perform lubricenter_private.finance_case('amount:'||t,'SOURCE_AMOUNT','external_transaction',t,'Revisar importe Cashea','Monto asignado supera el USD informado más allá de medio centavo; conserva ambas cifras.',r); end if;
  t:=null;
 end loop;
 for r in select value from jsonb_array_elements(p_preview->'orders') loop
  if s.provider<>'CASHEA_ORDERS' or coalesce(r->>'external_order','')!~'^\d+$' or jsonb_typeof(r->'installments')<>'array' then raise exception 'Snapshot Cashea inválido'; end if;
  insert into public.cashea_order_snapshots(batch_id,external_order,purchased_on,status,total_ref,initial_ref,installments,raw)
  values(b,r->>'external_order',(r->>'purchased_on')::date,r->>'status',(r->>'total_ref')::numeric,(r->>'initial_ref')::numeric,r->'installments',r->'raw');
 end loop;
 update public.external_import_batches set
 observed_from=(select min(d) from (select timezone('America/Caracas',x.occurred_at)::date d from public.external_transactions x join public.external_batch_transactions l on l.transaction_id=x.id where l.batch_id=b union all select purchased_on from public.cashea_order_snapshots where batch_id=b) q),
 observed_to=(select max(d) from (select timezone('America/Caracas',x.occurred_at)::date d from public.external_transactions x join public.external_batch_transactions l on l.transaction_id=x.id where l.batch_id=b union all select purchased_on from public.cashea_order_snapshots where batch_id=b) q)
 where id=b;
 -- Recalculate chain from persisted decimals; never trust browser's 'complete' or chain flag.
 if s.provider='BDV' then
  with ordered as (select x.*,lag(balance) over(order by x.occurred_at,case when (select (z->>'occurred_at')::timestamptz from jsonb_array_elements(p_preview->'rows') z limit 1) >= (select (z->>'occurred_at')::timestamptz from jsonb_array_elements(p_preview->'rows') with ordinality a(z,n) order by n desc limit 1) then -l.row_number else l.row_number end) prev from public.external_transactions x join public.external_batch_transactions l on l.transaction_id=x.id where l.batch_id=b)
  select bool_or(prev is not null and balance<>prev+case when direction='IN' then amount else -amount end) into v_bad from ordered;
  update public.external_import_batches set balance_chain=not coalesce(v_bad,false) where id=b;
 end if;
 perform lubricenter_private.finance_case('batch:'||b,'COVERAGE','import_batch',b,'Confirmar cobertura del reporte','La fecha del primer y último movimiento no prueba que estén todas las páginas.',jsonb_build_object('source_name',p_name));
 return b;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_outflow(p_request_id uuid, p_account_id uuid, p_amount numeric, p_nature text, p_category text, p_payee text, p_note text, p_reference text, p_occurred_on date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.financial_accounts; v_rate numeric; v_id uuid; v_day date:=coalesce(p_occurred_on,timezone('America/Caracas',now())::date); m public.account_movements;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 if p_request_id is null then raise exception 'Identificador requerido'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,22));
 select * into m from public.account_movements where finance_request_id=p_request_id;
 if found then
  if m.account_id<>p_account_id or m.amount_original<>p_amount or m.finance_nature<>p_nature then raise exception 'Operación ya utilizada con datos distintos'; end if; return m.id;
 end if;
 if p_nature='OWNER_DRAW' then perform lubricenter_private.finance_require('OWNER'); end if;
 if p_nature not in ('EXPENSE','ASSET_PURCHASE','OWNER_DRAW','TAX','BANK_FEE','UNCLASSIFIED') then raise exception 'Usa el módulo de compras, proveedores, nómina, devolución o transferencia para enlazar su documento'; end if;
 if p_nature in ('EXPENSE','BANK_FEE') and coalesce(trim(p_category),'')='' then raise exception 'Selecciona una categoría'; end if;
 select * into a from public.financial_accounts where id=p_account_id and active and account_type in ('CASH','BANK');
 if not found then raise exception 'Selecciona una cuenta del negocio'; end if;
 if p_amount is null or p_amount<=0 or p_amount>='Infinity'::numeric then raise exception 'Monto inválido'; end if;
 if v_day>timezone('America/Caracas',now())::date then raise exception 'La salida no puede ser futura'; end if;
 if a.account_type='BANK' and coalesce(trim(p_reference),'')!~'^\d{4,32}$' then raise exception 'Escribe los últimos 4 números de la referencia'; end if;
 if a.currency='USD' then
  select value into v_rate from public.exchange_rates where rate_type='OPERATIVE' and timezone('America/Caracas',effective_at)::date<=v_day order by effective_at desc limit 1;
  if v_rate is null then raise exception 'Falta la tasa histórica para valorar esta salida en USD'; end if;
 else v_rate:=1; end if;
 insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,payee,note,reference,occurred_at,finance_nature,finance_request_id)
 values(a.id,'OUT',case when p_nature in ('EXPENSE','TAX','BANK_FEE') then 'EXPENSE' else 'ADJUSTMENT' end,a.currency,p_amount,round(p_amount*v_rate,2),nullif(trim(p_category),''),p_payee,p_note,p_reference,
 case when v_day=timezone('America/Caracas',now())::date then now() else ((v_day::timestamp+time '12:00') at time zone 'America/Caracas') end,p_nature,p_request_id) returning id into v_id;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('finance.outflow_recorded','account_movement',v_id,jsonb_build_object('nature',p_nature,'rate_snapshot',v_rate,'reason',p_note));
 if p_nature='UNCLASSIFIED' then perform lubricenter_private.finance_case('nature:'||v_id,'OUTFLOW_NATURE','account_movement',v_id,'Clasificar salida registrada','El efectivo ya salió; falta identificar su naturaleza.',jsonb_build_object('amount',p_amount,'currency',a.currency)); end if;
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare r record; x record; c record; v_count integer:=0; v_candidates integer; v_used numeric; v_capacity numeric; v_rule record; v_run timestamptz; v_excluded integer:=0;
begin
 perform lubricenter_private.finance_require();
 perform pg_advisory_xact_lock(221122);
 v_run:=clock_timestamp();
 v_excluded:=lubricenter_private.finance_quarantine_exact_duplicates();
 update public.external_transactions x set ownership_status='OWN',ownership_reason='ORDER_MATCH',ownership_evidence=jsonb_build_object('cashea_sale_id',c.id)
 from public.cashea_sales c where x.external_order=trim(c.cashea_reference) and c.status<>'CANCELLED' and x.ownership_reason='UNKNOWN'
 and not exists(select 1 from public.reconciliation_transaction_exclusions e where e.transaction_id=x.id)
 and (select count(*) from public.cashea_sales z where trim(z.cashea_reference)=x.external_order and z.status<>'CANCELLED')=1;
 for r in with candidates as (
  select x.id xid,m.id mid,x.amount ea,m.amount_original ta,count(*) over(partition by x.id) nx,count(*) over(partition by m.id) nm
  from public.external_transactions x join public.external_sources s on s.id=x.source_id and s.provider='BDV'
  join public.account_movements m on m.account_id=s.account_id and m.currency=x.currency and m.direction=x.direction
   and right(regexp_replace(coalesce(m.reference,''),'\D','','g'),4)=right(x.reference,4) and length(regexp_replace(coalesce(m.reference,''),'\D','','g'))>=4
   and abs(extract(epoch from(m.occurred_at-x.occurred_at)))<=172800 and abs(m.amount_original-x.amount)<=least(5,m.amount_original*.001)
  where x.ownership_status='OWN'
   and not exists(select 1 from public.reconciliation_transaction_exclusions e where e.transaction_id=x.id)
   and not exists(select 1 from public.reconciliation_allocations a where (a.external_transaction_id=x.id or a.account_movement_id=m.id) and a.reversed_at is null)
   and not exists(select 1 from public.reconciliation_cases c where c.subject_id=x.id and c.status='OPEN' and c.kind in ('SOURCE_CONFLICT','SOURCE_AMOUNT'))
   and not exists(select 1 from public.payments p join public.orders o on o.id=p.order_id where p.id=m.source_payment_id and o.status='CANCELLED')
 ) select * from candidates where nx=1 and nm=1 order by xid loop
  perform lubricenter_private.finance_allocate(gen_random_uuid(),r.xid,r.mid,null,r.ea,r.ta,case when r.ea=r.ta then 'EXACT' else 'ROUNDING' end,'Referencia, cuenta, moneda, fecha y monto coinciden; candidato único en ambos extremos'); v_count:=v_count+1;
 end loop;
 for x in select t.*,s.provider from public.external_transactions t join public.external_sources s on s.id=t.source_id
  where not exists(select 1 from public.reconciliation_transaction_exclusions e where e.transaction_id=t.id)
  order by t.occurred_at,t.id loop
  if x.ownership_status='OTHER_LOCATION' then continue; end if;
  if x.ownership_status='UNRESOLVED' then
   perform lubricenter_private.finance_case('owner:'||x.id,'OWNERSHIP','external_transaction',x.id,'Identificar cobro Cashea','No hay una orden interna inequívoca. No se asume otro local.',jsonb_build_object('order',x.external_order,'amount',x.amount_ref)); continue;
  end if;
  if x.provider='CASHEA_TRANSACTIONS' and cardinality(x.installments)=1
   and not exists(select 1 from public.reconciliation_allocations where external_transaction_id=x.id and reversed_at is null)
   and not exists(select 1 from public.reconciliation_cases where subject_id=x.id and status='OPEN' and kind in ('SOURCE_CONFLICT','SOURCE_AMOUNT')) then
   select i.id,i.amount_ref-coalesce((select sum(a.target_amount) from public.reconciliation_allocations a where a.cashea_installment_id=i.id and a.reversed_at is null),0) remaining into c
   from public.cashea_installments i join public.cashea_sales cs on cs.id=i.cashea_sale_id
   where trim(cs.cashea_reference)=x.external_order and cs.status<>'CANCELLED' and cs.ownership_status='OWN' and i.installment_no=x.installments[1];
   if found and least(x.amount_ref,x.assigned_ref)<=c.remaining
    and coalesce((select status from public.cashea_order_snapshots ss where ss.external_order=x.external_order order by created_at desc,id desc limit 1),'')<>'CANCELLED' then
    v_capacity:=least(x.amount_ref,x.assigned_ref);
    if c.remaining>v_capacity and c.remaining-v_capacity<=least(0.005,c.remaining*.001) then
     perform lubricenter_private.finance_allocate(gen_random_uuid(),x.id,null,c.id,v_capacity,c.remaining,'ROUNDING','Precisión del reporte Cashea: diferencia máxima de medio centavo, conservada explícitamente');
    else perform lubricenter_private.finance_allocate(gen_random_uuid(),x.id,null,c.id,v_capacity,v_capacity,'EXACT','Orden y cuota identificadas; cobro parcial o completo sin alterar cartera'); end if;
    v_count:=v_count+1;
   end if;
   if x.installments[1]=0 then
    select cs.id,cs.initial_ref-coalesce((select sum(a.target_amount) from public.reconciliation_allocations a where a.cashea_sale_id=cs.id and a.reversed_at is null),0) remaining into c from public.cashea_sales cs where trim(cs.cashea_reference)=x.external_order and cs.status<>'CANCELLED' and cs.ownership_status='OWN';
    if found and least(x.amount_ref,x.assigned_ref)<=c.remaining and coalesce((select status from public.cashea_order_snapshots ss where ss.external_order=x.external_order order by created_at desc,id desc limit 1),'')<>'CANCELLED' then
     perform lubricenter_private.finance_allocate(gen_random_uuid(),x.id,null,null,least(x.amount_ref,x.assigned_ref),least(x.amount_ref,x.assigned_ref),'EXACT','Inicial documentada por Cashea; no se registra otro pago',c.id); v_count:=v_count+1;
    end if;
   end if;
  end if;
  select coalesce(sum(external_amount),0) into v_used from public.reconciliation_allocations where external_transaction_id=x.id and reversed_at is null;
  v_capacity:=case when x.provider='BDV' then x.amount else least(x.amount_ref,x.assigned_ref) end;
  v_candidates:=0;
  if x.direction='OUT' and x.nature='UNCLASSIFIED' then
   select count(*) into v_candidates from public.reconciliation_rules where active and (source_id is null or source_id=x.source_id) and position(description_contains in upper(x.description))>0;
   if v_candidates=1 then
    select * into v_rule from public.reconciliation_rules where active and (source_id is null or source_id=x.source_id) and position(description_contains in upper(x.description))>0;
    if v_rule.category_id is not null then
     perform lubricenter_private.finance_classify_external(x.id,jsonb_build_object('nature',v_rule.nature,'category_id',v_rule.category_id,'note','Regla aprobada '||v_rule.id||' versión '||v_rule.version,'save_rule',false));
     v_count:=v_count+1;
     continue;
    end if;
    update public.external_transactions set nature=v_rule.nature,category=v_rule.category,classification_reason='Regla aprobada '||v_rule.id||' versión '||v_rule.version where id=x.id;
   else perform lubricenter_private.finance_case('class:'||x.id,'UNCLASSIFIED','external_transaction',x.id,'Clasificar salida',x.description,jsonb_build_object('amount',x.amount,'currency',x.currency)); end if;
  end if;
  if v_used<v_capacity and (x.direction='IN' or x.nature<>'UNCLASSIFIED' or v_candidates=1) then
   perform lubricenter_private.finance_case('unmatched:'||x.id,'UNMATCHED','external_transaction',x.id,case when x.direction='IN' then 'Cobro por vincular' else 'Salida sin registro interno' end,
   case when cardinality(x.installments)>1 then 'Este cobro cubre varias cuotas: distribuye solo el monto comprobado.' else 'No hay una coincidencia única. Busca el registro interno.' end,jsonb_build_object('remaining',v_capacity-v_used,'reference',x.reference,'order',x.external_order));
  end if;
 end loop;
 for r in select distinct on (s.external_order) s.* from public.cashea_order_snapshots s order by s.external_order,s.created_at desc,s.id desc loop
  select * into c from public.cashea_sales where trim(cashea_reference)=r.external_order and status<>'CANCELLED';
  if found and (r.status='CANCELLED' or abs(c.gross_ref-r.total_ref)>.01 or abs(c.initial_ref-r.initial_ref)>.01 or exists(
   select 1 from jsonb_array_elements(r.installments) q left join public.cashea_installments i on i.cashea_sale_id=c.id and i.installment_no=(q->>'number')::integer
   where i.id is null or abs(i.amount_ref-(q->>'amount_ref')::numeric)>.0001 or i.due_date<>(q->>'due_date')::date)) then
   perform lubricenter_private.finance_case('schedule:'||c.id,'CASHEA_SCHEDULE','cashea_sale',c.id,'Revisar condiciones Cashea','Total, inicial, calendario o cancelación difiere de la orden interna.',jsonb_build_object('snapshot_id',r.id,'external_order',r.external_order));
  end if;
 end loop;
 for r in
  select m.*, m.amount_original-coalesce((select sum(z.target_amount) from public.reconciliation_allocations z where z.account_movement_id=m.id and z.reversed_at is null),0) remaining
  from public.account_movements m join public.financial_accounts a on a.id=m.account_id and a.account_type='BANK'
  where m.direction='IN' and m.occurred_at<now()-interval '48 hours'
  and m.amount_original>coalesce((select sum(z.target_amount) from public.reconciliation_allocations z where z.account_movement_id=m.id and z.reversed_at is null),0)
  and lubricenter_private.finance_bdv_window_covered(m.account_id,m.occurred_at)
  and not exists(select 1 from public.payments p join public.orders o on o.id=p.order_id where p.id=m.source_payment_id and o.status='CANCELLED')
 loop
  perform lubricenter_private.finance_case('missing:'||r.id,'MISSING_EXTERNAL','account_movement',r.id,
   case when r.remaining<r.amount_original then 'Cobro parcialmente conciliado' else 'Cobro sin evidencia bancaria' end,
   'La cobertura del banco y el margen de 48 horas están verificados. Revisa la parte pendiente, referencia y cuenta.',
   jsonb_build_object('amount',r.amount_original,'remaining',r.remaining,'matched',r.amount_original-r.remaining,'currency',r.currency,'reference',r.reference));
 end loop;
 for r in select d.*,a.currency from public.cash_closing_accounts d join public.cash_closings c on c.id=d.cash_closing_id and c.finance_version=22 and c.status in ('CLOSED','REVIEW') join public.financial_accounts a on a.id=d.account_id where abs(d.difference_native)>case when a.currency='USD' then .01 else 1 end loop
  perform lubricenter_private.finance_case('cash:'||r.cash_closing_id||':'||r.account_id,'CASH_VARIANCE','cash_closing',r.cash_closing_id,'Diferencia en efectivo','Conteo guardado. Revisar diferencia; no es un ingreso o gasto automático.',jsonb_build_object('account_id',r.account_id,'difference',r.difference_native,'explanation',r.explanation));
 end loop;
 update public.reconciliation_cases set status='RESOLVED',resolution='La evidencia actual ya no presenta esta excepción',resolved_at=now(),resolved_by=auth.uid()
 where status='OPEN' and kind in ('OWNERSHIP','UNMATCHED','UNCLASSIFIED','MISSING_EXTERNAL','CASHEA_SCHEDULE','CASH_VARIANCE') and updated_at<v_run;
 return jsonb_build_object('matched',v_count,'excluded_exact_duplicates',v_excluded,'open_cases',(select count(*) from public.reconciliation_cases where status='OPEN'));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_record_external_outflow(p_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x public.external_transactions; s public.external_sources; v_id uuid;
begin
 perform lubricenter_private.finance_require();
 select * into x from public.external_transactions where id=p_id for update;
 if not found then raise exception 'Movimiento no encontrado'; end if;
 select id into v_id from public.account_movements where finance_request_id=x.id;
 if found then return v_id; end if;
 select * into s from public.external_sources where id=x.source_id;
 if s.provider<>'BDV' or x.direction<>'OUT' or x.ownership_status<>'OWN' then raise exception 'Esta acción registra únicamente una salida bancaria propia'; end if;
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Confirma por qué esta salida no tiene registro interno'; end if;
 if x.nature not in ('EXPENSE','ASSET_PURCHASE','OWNER_DRAW','TAX','BANK_FEE') then raise exception 'Primero clasifica. Compras, proveedores y transferencias se registran desde sus documentos'; end if;
 if x.nature='OWNER_DRAW' then perform lubricenter_private.finance_require('OWNER'); end if;
 if exists(select 1 from public.reconciliation_allocations where external_transaction_id=x.id and reversed_at is null) then raise exception 'Este movimiento ya tiene una asignación; revisa el registro existente'; end if;
 if exists(select 1 from public.account_movements where account_id=s.account_id and direction='OUT' and currency=x.currency and abs(amount_original-x.amount)<=least(5,x.amount*.001) and right(regexp_replace(coalesce(reference,''),'\D','','g'),4)=right(x.reference,4) and occurred_at between x.occurred_at-interval '48 hours' and x.occurred_at+interval '48 hours') then raise exception 'Ya hay una salida similar: vincúlala en lugar de duplicarla'; end if;
 insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,note,reference,occurred_at,finance_nature,finance_request_id)
 values(s.account_id,'OUT',case when x.nature in ('EXPENSE','TAX','BANK_FEE') then 'EXPENSE' else 'ADJUSTMENT' end,x.currency,x.amount,x.amount,x.category,p_reason,x.reference,x.occurred_at,x.nature,x.id) returning id into v_id;
 perform lubricenter_private.finance_allocate(gen_random_uuid(),x.id,v_id,null,x.amount,x.amount,'EXACT','Salida registrada desde evidencia externa; '||p_reason);
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('finance.external_outflow_recorded','account_movement',v_id,jsonb_build_object('external_transaction_id',x.id,'reason',p_reason));
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_report_coverage(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_from date:=coalesce(p_from,date_trunc('month',timezone('America/Caracas',now()))::date);
 v_to date:=coalesce(p_to,timezone('America/Caracas',now())::date);
 s record; v_rows jsonb:='[]'::jsonb; v_missing date; v_conflict date;
 v_complete integer; v_review integer; v_source_conflicts integer; v_source_conflict_from date;
 v_snapshot timestamptz; v_status text; v_stop date;
begin
 perform lubricenter_private.finance_require();
 if v_from>v_to or v_to-v_from>366 then raise exception 'Selecciona un período válido de máximo un año'; end if;
 for s in select * from public.external_sources where active order by provider,name,id loop
  select count(*) filter(where b.status='COMPLETE'),count(*) filter(where b.status='REVIEW')
   into v_complete,v_review from public.external_import_batches b
   where b.source_id=s.id and b.requested_from<=v_to and b.requested_to>=v_from;
  v_missing:=null; v_conflict:=null; v_snapshot:=null;
  select count(*), min(timezone('America/Caracas',x.occurred_at)::date)
   into v_source_conflicts,v_source_conflict_from
   from public.reconciliation_cases c
   join public.external_transactions x on x.id=c.subject_id
   where c.status='OPEN' and c.kind in ('SOURCE_CONFLICT','SOURCE_AMOUNT')
    and x.source_id=s.id
    and timezone('America/Caracas',x.occurred_at)::date between v_from and v_to;
  if s.provider='CASHEA_ORDERS' then
   select max(verified_at) into v_snapshot from public.external_import_batches
    where source_id=s.id and status='COMPLETE';
   v_status:=case when v_source_conflicts>0 then 'SOURCE_CONFLICT'
    when v_review>0 then 'NEEDS_VERIFICATION'
    when v_snapshot is not null then 'SNAPSHOT_AVAILABLE' else 'MISSING_REPORT' end;
  else
   select min(d::date) into v_missing
    from generate_series(v_from,v_to,interval '1 day') d
    where d::date>=timezone('America/Caracas',now())::date or not exists(
     select 1 from public.external_import_batches b
     where b.source_id=s.id and b.status='COMPLETE'
      and d::date between b.requested_from and b.requested_to
    );
   if s.provider='BDV' then
    select min(b.requested_from) into v_conflict
     from public.external_import_batches a join public.external_import_batches b
      on b.source_id=a.source_id and b.status='COMPLETE' and b.requested_from=a.requested_to+1
     where a.source_id=s.id and a.status='COMPLETE'
      and a.requested_to>=v_from and b.requested_from<=v_to
      and (a.controls->>'closing')::numeric is distinct from (b.controls->>'opening')::numeric;
   end if;
   v_status:=case when v_source_conflicts>0 then 'SOURCE_CONFLICT'
    when v_conflict is not null then 'BALANCE_CONFLICT'
    when v_missing is null then 'COVERAGE_VERIFIED'
    when v_missing=timezone('America/Caracas',now())::date and v_to=v_missing and v_complete>0 then 'IN_PROGRESS'
    when v_complete=0 and v_review>0 then 'NEEDS_VERIFICATION'
    when v_complete=0 then 'MISSING_REPORT' else 'PARTIAL' end;
  end if;
  v_stop:=least(coalesce(v_missing,v_to+1),coalesce(v_conflict,v_to+1),coalesce(v_source_conflict_from,v_to+1));
  v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
   'source_id',s.id,'source_name',s.name,'provider',s.provider,
   'account_id',s.account_id,'currency',s.currency,'status',v_status,
   'covered_through',case when s.provider='CASHEA_ORDERS' or v_stop<=v_from then null else v_stop-1 end,
   'missing_from',v_missing,'balance_conflict_from',v_conflict,
   'source_conflict_from',v_source_conflict_from,'source_conflicts',v_source_conflicts,
   'latest_snapshot_imported_at',v_snapshot,
   'verified_batches',v_complete,'review_batches',v_review
  ));
 end loop;
 return jsonb_build_object('from',v_from,'to',v_to,'sources',v_rows);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_require(p_role text DEFAULT 'ADMIN'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not lubricenter_private.staff_identity_allowed() then raise exception 'Usuario no autorizado'; end if;
 if (p_role='OWNER' and lubricenter_private.finance_role()<>'OWNER')
 or (p_role='ADMIN' and lubricenter_private.finance_role() not in ('ADMIN','OWNER'))
 then raise exception 'Esta acción necesita un administrador financiero'; end if;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_resolve(p_action text, p_id uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x public.external_transactions; v_role text;
begin
 perform lubricenter_private.finance_require(); v_role:=lubricenter_private.finance_role();
 if length(trim(coalesce(p_data->>'reason','')))<5 then raise exception 'Escribe el motivo para el historial'; end if;
 if p_action='OWNERSHIP' then
  select * into x from public.external_transactions where id=p_id for update;
  if not found then raise exception 'Movimiento no encontrado'; end if;
  if exists(select 1 from public.reconciliation_allocations where external_transaction_id=x.id and reversed_at is null) then raise exception 'Revierte las asignaciones antes de cambiar propiedad'; end if;
  if p_data->>'status' not in ('OWN','OTHER_LOCATION','UNRESOLVED') then raise exception 'Propiedad inválida'; end if;
  update public.external_transactions set ownership_status=p_data->>'status',ownership_reason='MANUAL_ASSIGNMENT',ownership_evidence=jsonb_build_object('reason',p_data->>'reason','actor',auth.uid()) where id=p_id;
 elsif p_action='CLASSIFY' then
  if p_data->>'nature' not in ('EXPENSE','INVENTORY_PURCHASE','ASSET_PURCHASE','SUPPLIER_PAYMENT','OWNER_DRAW','PAYROLL','INTERNAL_TRANSFER','REFUND','TAX','BANK_FEE','UNCLASSIFIED') then raise exception 'Naturaleza inválida'; end if;
  if p_data->>'nature'='OWNER_DRAW' and v_role<>'OWNER' then raise exception 'El dueño debe confirmar sus retiros'; end if;
  if p_data->>'nature' in ('EXPENSE','BANK_FEE') and length(trim(coalesce(p_data->>'category','')))=0 then raise exception 'Selecciona categoría'; end if;
  update public.external_transactions set nature=p_data->>'nature',category=nullif(trim(p_data->>'category'),''),classification_reason=p_data->>'reason' where id=p_id and direction='OUT';
  if not found then raise exception 'Salida no encontrada'; end if;
 elsif p_action='CLASSIFY_MOVEMENT' then
  if p_data->>'nature' not in ('EXPENSE','ASSET_PURCHASE','OWNER_DRAW','TAX','BANK_FEE','UNCLASSIFIED') then raise exception 'Vincula la compra, proveedor o transferencia desde su módulo antes de clasificar'; end if;
  if p_data->>'nature'='OWNER_DRAW' and v_role<>'OWNER' then raise exception 'El dueño debe confirmar sus retiros'; end if;
  if p_data->>'nature' in ('EXPENSE','BANK_FEE') and length(trim(coalesce(p_data->>'category','')))=0 then raise exception 'Selecciona categoría'; end if;
  update public.account_movements set finance_nature=p_data->>'nature',category=nullif(trim(p_data->>'category'),''),movement_type=case when p_data->>'nature' in ('EXPENSE','TAX','BANK_FEE') then 'EXPENSE' else 'ADJUSTMENT' end
   where id=p_id and finance_nature='UNCLASSIFIED' and direction='OUT';
  if not found then raise exception 'La salida ya fue clasificada; recarga antes de cambiarla'; end if;
  insert into public.audit_events(event_type,entity_type,entity_id,data) values('finance.nature_classified','account_movement',p_id,p_data);
  if p_data->>'nature'<>'UNCLASSIFIED' then update public.reconciliation_cases set status='RESOLVED',resolution=p_data->>'reason',resolved_by=auth.uid(),resolved_at=now() where case_key='nature:'||p_id; end if;
 elsif p_action='REVERSE_ALLOCATION' then
  perform 1 from public.external_transactions where id=(select external_transaction_id from public.reconciliation_allocations where id=p_id) for update;
  update public.reconciliation_allocations set reversed_at=now(),reversed_by=auth.uid(),reversal_reason=p_data->>'reason' where id=p_id and reversed_at is null;
 elsif p_action='DISMISS_CASE' then
  if v_role<>'OWNER' then raise exception 'Solo el dueño puede descartar una anomalía'; end if;
  update public.reconciliation_cases set status='DISMISSED',resolution=p_data->>'reason',resolved_by=auth.uid(),resolved_at=now() where id=p_id and kind not in ('COVERAGE','SOURCE_CONFLICT','SOURCE_AMOUNT');
 else raise exception 'Acción inválida'; end if;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_review(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x public.external_transactions; s public.external_sources; v_targets jsonb;
begin
 perform lubricenter_private.finance_require();
 select * into x from public.external_transactions where id=p_id;
 if not found then raise exception 'Movimiento externo no encontrado'; end if;
 select * into s from public.external_sources where id=x.source_id;
 if s.provider='BDV' then
  select coalesce(jsonb_agg(to_jsonb(m)),'[]') into v_targets from (
   select m.id,'movement' kind,m.occurred_at,m.reference,m.note,m.amount_original::text amount,m.currency,
    (m.amount_original-coalesce((select sum(target_amount) from public.reconciliation_allocations where account_movement_id=m.id and reversed_at is null),0))::text remaining
   from public.account_movements m where m.account_id=s.account_id and m.direction=x.direction and m.currency=x.currency
    and m.occurred_at between x.occurred_at-interval '7 days' and x.occurred_at+interval '7 days' order by abs(extract(epoch from(m.occurred_at-x.occurred_at))),m.id limit 100) m;
 else
  select coalesce(jsonb_agg(to_jsonb(i)),'[]') into v_targets from (
   select i.id,'installment' kind,i.installment_no,i.due_date,i.amount_ref::text amount,'USD' currency,
    (i.amount_ref-coalesce((select sum(target_amount) from public.reconciliation_allocations where cashea_installment_id=i.id and reversed_at is null),0))::text remaining
   from public.cashea_installments i join public.cashea_sales c on c.id=i.cashea_sale_id where trim(c.cashea_reference)=x.external_order and c.status<>'CANCELLED' and i.installment_no=any(x.installments)
   union all select c.id,'initial',0,null,c.initial_ref::text,'USD',(c.initial_ref-coalesce((select sum(target_amount) from public.reconciliation_allocations where cashea_sale_id=c.id and reversed_at is null),0))::text from public.cashea_sales c where trim(c.cashea_reference)=x.external_order and c.status<>'CANCELLED' and 0=any(x.installments)) i;
 end if;
 return jsonb_build_object('transaction',to_jsonb(x)||jsonb_build_object('amount',x.amount::text,'amount_ref',x.amount_ref::text,'assigned_ref',x.assigned_ref::text),'targets',v_targets,'allocations',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('external_amount',a.external_amount::text,'target_amount',a.target_amount::text,'difference',a.difference::text)) from public.reconciliation_allocations a where external_transaction_id=x.id),'[]'),
 'history',coalesce((select jsonb_agg(to_jsonb(e)) from (select * from public.audit_events where entity_id=x.id order by created_at desc limit 30) e),'[]'));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_transfer_fx(p_from_account_id uuid, p_to_account_id uuid, p_from_amount numeric, p_to_amount numeric, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.financial_accounts; b public.financial_accounts;
        g uuid := gen_random_uuid(); ves numeric;
begin
 perform lubricenter_private.finance_require();
 if p_from_account_id=p_to_account_id or p_from_amount is null or p_to_amount is null
    or p_from_amount<=0 or p_to_amount<=0 or p_from_amount>=1000000000000
    or p_to_amount>=1000000000000 or p_from_amount::text in ('NaN','Infinity','-Infinity')
    or p_to_amount::text in ('NaN','Infinity','-Infinity') then
   raise exception 'Cuentas o importes de conversión inválidos';
 end if;
 select * into a from public.financial_accounts where id=p_from_account_id and active=true;
 select * into b from public.financial_accounts where id=p_to_account_id and active=true;
 if a.id is null or b.id is null or a.currency=b.currency
    or a.account_type='RELATED' or b.account_type='RELATED' then
   raise exception 'Elige dos cuentas propias activas de distinta moneda';
 end if;
 ves:=case when a.currency='VES' then p_from_amount else p_to_amount end;
 insert into public.account_movements
 (account_id,direction,movement_type,finance_nature,transfer_group,currency,amount_original,value_ves,note,reference,occurred_at)
 values
 (a.id,'OUT','TRANSFER','INTERNAL_TRANSFER',g,a.currency,p_from_amount,ves,nullif(trim(p_note),''),nullif(trim(p_reference),''),now()),
 (b.id,'IN','TRANSFER','INTERNAL_TRANSFER',g,b.currency,p_to_amount,ves,nullif(trim(p_note),''),nullif(trim(p_reference),''),now());
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values ('cash.fx_transfer','transfer',g,jsonb_build_object(
   'from_account',a.code,'to_account',b.code,
   'from_amount',p_from_amount,'to_amount',p_to_amount,
   'ves_amount',ves,'usd_amount',case when a.currency='USD' then p_from_amount else p_to_amount end));
 return g;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_verify_batch(p_id uuid, p_controls jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.external_import_batches; s public.external_sources; v_total numeric; v_in numeric; v_out numeric; v_first numeric; v_last numeric; v_count integer; v_desc boolean;
begin
 perform lubricenter_private.finance_require();
 select * into b from public.external_import_batches where id=p_id for update;
 if not found then raise exception 'Lote no encontrado'; end if;
 select * into s from public.external_sources where id=b.source_id;
 if b.status='COMPLETE' then return; end if;
 if jsonb_array_length(b.validation->'errors')>0 then raise exception 'Revisa los errores del archivo y vuelve a importarlo completo'; end if;
 if b.observed_from<b.requested_from or b.observed_to>b.requested_to then raise exception 'Hay movimientos fuera del período solicitado'; end if;
 if coalesce(p_controls->>'all_pages','false')<>'true' or length(trim(coalesce(p_controls->>'evidence','')))<10 then raise exception 'Indica el control independiente del reporte y confirma todas las páginas'; end if;
 if (p_controls->>'from')::date is distinct from b.requested_from or (p_controls->>'to')::date is distinct from b.requested_to then raise exception 'Las fechas del control no coinciden con el período'; end if;
 if s.provider='CASHEA_ORDERS' then
  select count(*),coalesce(sum(total_ref),0) into v_count,v_total from public.cashea_order_snapshots where batch_id=b.id;
 else
  select count(*),coalesce(sum(case when s.provider='BDV' then x.amount else x.amount_ref end),0),coalesce(sum(amount) filter(where direction='IN'),0),coalesce(sum(amount) filter(where direction='OUT'),0) into v_count,v_total,v_in,v_out from public.external_transactions x where exists(select 1 from public.external_batch_transactions l where l.batch_id=b.id and l.transaction_id=x.id);
 end if;
 if (p_controls->>'expected_count')::integer is distinct from v_count or (p_controls->>'expected_total')::numeric is distinct from v_total then raise exception 'Cantidad o total del control no coincide. No se puede confirmar cobertura'; end if;
 if s.provider='BDV' then
  if b.balance_chain is distinct from true then raise exception 'La cadena de saldos tiene saltos'; end if;
  v_desc:=(b.payload->'rows'->0->>'occurred_at')::timestamptz>=(b.payload->'rows'->-1->>'occurred_at')::timestamptz;
  select x.balance-case when x.direction='IN' then x.amount else -x.amount end into v_first from public.external_transactions x join public.external_batch_transactions l on l.transaction_id=x.id where l.batch_id=b.id order by x.occurred_at,case when v_desc then -l.row_number else l.row_number end limit 1;
  select x.balance into v_last from public.external_transactions x join public.external_batch_transactions l on l.transaction_id=x.id where l.batch_id=b.id order by x.occurred_at desc,case when v_desc then l.row_number else -l.row_number end limit 1;
  if (p_controls->>'opening')::numeric is distinct from v_first or (p_controls->>'closing')::numeric is distinct from v_last or (p_controls->>'opening')::numeric+v_in-v_out is distinct from (p_controls->>'closing')::numeric then raise exception 'Saldos inicial/final no coinciden con el control independiente'; end if;
 end if;
 update public.external_import_batches set status='COMPLETE',controls=p_controls,verified_by=auth.uid(),verified_at=now() where id=b.id;
 update public.reconciliation_cases set status='RESOLVED',resolution='Cobertura verificada con controles',resolved_by=auth.uid(),resolved_at=now() where case_key='batch:'||b.id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_week_close(p_start date, p_force boolean DEFAULT false, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; p public.finance_reconciliation_periods; v_status jsonb; v_ready boolean;
begin
 perform lubricenter_private.finance_require();
 perform pg_advisory_xact_lock(hashtextextended('finance-week:'||p_start::text,22));
 perform lubricenter_private.finance_reconcile();
 select id into v_location from public.locations where active order by created_at limit 1;
 select * into p from public.finance_reconciliation_periods where location_id=v_location and period_start=p_start for update;
 if not found then raise exception 'Semana financiera no abierta'; end if;
 if p.status<>'OPEN' then return lubricenter_private.finance_week_status(p_start); end if;
 if timezone('America/Caracas',now())::date<=p.period_end then raise exception 'La semana todavía no terminó'; end if;
 v_status:=lubricenter_private.finance_week_status(p_start); v_ready:=(v_status->>'ready')::boolean;
 if not v_ready then
   if not p_force then raise exception 'La semana no cuadra. Resuelve los pendientes antes de cerrar'; end if;
   perform lubricenter_private.finance_require('OWNER');
   if length(trim(coalesce(p_reason,'')))<10 then raise exception 'Explica por qué cierras con diferencias'; end if;
 end if;
 update public.finance_reconciliation_periods
 set status=case when v_ready then 'CLOSED' else 'CLOSED_WITH_EXCEPTION' end,
     closed_by=auth.uid(),closed_at=now(),close_reason=nullif(trim(p_reason),''),close_snapshot=v_status
 where id=p.id;
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('finance.week_closed','finance_reconciliation_period',p.id,jsonb_build_object('forced',not v_ready,'snapshot',v_status,'reason',p_reason));
 return lubricenter_private.finance_week_status(p_start);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_week_open(p_start date, p_openings jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; v_id uuid; v_prev uuid; a record; v_open numeric; v_code text;
begin
 perform lubricenter_private.finance_require();
 if p_start is null or extract(isodow from p_start)<>1 then raise exception 'La semana financiera comienza el lunes'; end if;
 if p_start>timezone('America/Caracas',now())::date then raise exception 'Abre la semana cuando llegue el lunes'; end if;
 select id into v_location from public.locations where active order by created_at limit 1;
 if v_location is null then raise exception 'Falta ubicación activa'; end if;
 select id into v_id from public.finance_reconciliation_periods where location_id=v_location and period_start=p_start;
 if v_id is not null then return v_id; end if;

 select id into v_prev from public.finance_reconciliation_periods
 where location_id=v_location and period_start=p_start-7 and status in ('CLOSED','CLOSED_WITH_EXCEPTION');

 insert into public.finance_reconciliation_periods(location_id,period_start,period_end,opened_by)
 values(v_location,p_start,p_start+6,auth.uid()) returning id into v_id;

 for a in
  select * from public.financial_accounts
  where active and code in ('BDV','BNC','CASH_USD','CASH_VES')
  order by code
 loop
  v_code:=a.code; v_open:=null;
  if v_prev is not null then
    select closing_native into v_open from public.finance_reconciliation_period_accounts
    where period_id=v_prev and account_id=a.id;
  end if;
  if v_open is null and p_openings ? v_code then v_open:=(p_openings->>v_code)::numeric; end if;
  if v_open is null or v_open<0 then raise exception 'Falta saldo inicial de %',v_code; end if;
  insert into public.finance_reconciliation_period_accounts(period_id,account_id,opening_native)
  values(v_id,a.id,v_open);
 end loop;
 if (select count(*) from public.finance_reconciliation_period_accounts where period_id=v_id)<>4 then
   raise exception 'Se requieren BDV, BNC, Caja USD y Caja Bs activas';
 end if;
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('finance.week_opened','finance_reconciliation_period',v_id,jsonb_build_object('start',p_start,'end',p_start+6));
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_week_pending(p_start date, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; v_period uuid; v_end date; v_total integer; v_rows jsonb;
begin
 perform lubricenter_private.finance_require();
 select id into v_location from public.locations where active order by created_at limit 1;
 select id,period_end into v_period,v_end from public.finance_reconciliation_periods where location_id=v_location and period_start=p_start;
 if v_period is null then return jsonb_build_object('total',0,'rows','[]'::jsonb,'categories','[]'::jsonb); end if;

 with pending as (
   select x.*,fa.name account_name,fa.id account_id,
     x.amount-coalesce((select sum(ra.external_amount) from public.reconciliation_allocations ra where ra.external_transaction_id=x.id and ra.reversed_at is null),0) remaining
   from public.external_transactions x
   join public.external_sources s on s.id=x.source_id
   join public.financial_accounts fa on fa.id=s.account_id
   join public.finance_reconciliation_period_accounts pa on pa.period_id=v_period and pa.account_id=fa.id
   where timezone('America/Caracas',x.occurred_at)::date between p_start and v_end
 ), numbered as (
   select *,row_number() over(order by occurred_at,id) rn from pending
   where remaining>.01
 )
 select count(*)::integer,
   coalesce(jsonb_agg(jsonb_build_object(
     'id',id,'account_id',account_id,'account_name',account_name,'occurred_at',occurred_at,'reference',reference,
     'description',description,'direction',direction,'currency',currency,'amount',amount,'remaining',remaining,
     'nature',nature,'category',category,'category_id',category_id
   ) order by occurred_at,id) filter(where rn>greatest(p_offset,0) and rn<=greatest(p_offset,0)+50),'[]'::jsonb)
 into v_total,v_rows from numbered;

 return jsonb_build_object(
   'total',v_total,'rows',v_rows,
   'categories',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'nature',nature) order by nature,name) from public.finance_categories where active),'[]'::jsonb),
   'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',fa.id,'code',fa.code,'name',fa.name,'currency',fa.currency) order by fa.code)
     from public.finance_reconciliation_period_accounts pa join public.financial_accounts fa on fa.id=pa.account_id where pa.period_id=v_period),'[]'::jsonb)
 );
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_week_set_closing(p_start date, p_account_id uuid, p_closing numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; v_period uuid; v_end date;
begin
 perform lubricenter_private.finance_require();
 if p_closing is null or p_closing<0 or p_closing>='Infinity'::numeric then raise exception 'Saldo final inválido'; end if;
 select id into v_location from public.locations where active order by created_at limit 1;
 select id,period_end into v_period,v_end from public.finance_reconciliation_periods where location_id=v_location and period_start=p_start and status='OPEN';
 if v_period is null then raise exception 'Abre primero la semana financiera'; end if;
 if timezone('America/Caracas',now())::date<=v_end then raise exception 'Registra el saldo final cuando haya terminado el domingo'; end if;
 update public.finance_reconciliation_period_accounts
 set closing_native=p_closing,closing_recorded_by=auth.uid(),closing_recorded_at=now()
 where period_id=v_period and account_id=p_account_id;
 if not found then raise exception 'Cuenta fuera de esta semana'; end if;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.finance_week_status(p_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_location uuid; p public.finance_reconciliation_periods; a record;
 v_rows jsonb:='[]'::jsonb; v_blockers jsonb:='[]'::jsonb;
 v_source uuid; v_source_name text; v_imported boolean; v_net numeric; v_expected numeric; v_diff numeric;
 v_pending integer; v_conflicts integer; v_cash_due integer; v_tol numeric; v_ready boolean:=true;
 v_cashea_pending integer:=0; v_cashea_batch boolean:=false;
begin
 perform lubricenter_private.finance_require();
 select id into v_location from public.locations where active order by created_at limit 1;
 select * into p from public.finance_reconciliation_periods where location_id=v_location and period_start=p_start;
 if not found then
   return jsonb_build_object('status','NEEDS_OPENING','start',p_start,'end',p_start+6,'ready',false,'accounts','[]'::jsonb,'blockers',jsonb_build_array('Falta abrir la semana'));
 end if;

 for a in
  select pa.*,fa.code,fa.name,fa.currency,fa.account_type
  from public.finance_reconciliation_period_accounts pa
  join public.financial_accounts fa on fa.id=pa.account_id
  where pa.period_id=p.id order by fa.code
 loop
  v_source:=null; v_source_name:=null; v_imported:=true; v_net:=0; v_pending:=0; v_conflicts:=0; v_cash_due:=0;
  if a.account_type='BANK' then
    select s.id,s.name into v_source,v_source_name
    from public.external_sources s
    where s.active and s.account_id=a.account_id
    order by s.created_at limit 1;

    if v_source is null then
      v_imported:=false;
    else
      select exists(
        select 1 from public.external_import_batches b
        where b.source_id=v_source
          and b.requested_from<=p.period_start and b.requested_to>=p.period_end
          and coalesce(jsonb_array_length(b.validation->'errors'),0)=0
      ) into v_imported;

      select coalesce(sum(case when x.direction='IN' then x.amount else -x.amount end),0),
             count(*) filter(where
               x.amount-coalesce((select sum(ra.external_amount) from public.reconciliation_allocations ra where ra.external_transaction_id=x.id and ra.reversed_at is null),0)>.01
             ),
             count(*) filter(where exists(
               select 1 from public.reconciliation_cases rc
               where rc.subject_type='external_transaction' and rc.subject_id=x.id and rc.status='OPEN'
                 and rc.kind in ('SOURCE_CONFLICT','SOURCE_AMOUNT','OWNERSHIP')
             ))
      into v_net,v_pending,v_conflicts
      from public.external_transactions x
      where x.source_id=v_source
        and timezone('America/Caracas',x.occurred_at)::date between p.period_start and p.period_end;
    end if;
    v_expected:=a.opening_native+v_net;
  else
    select coalesce(sum(case when m.direction='IN' then m.amount_original else -m.amount_original end),0)
    into v_net
    from public.account_movements m
    where m.account_id=a.account_id
      and timezone('America/Caracas',m.occurred_at)::date between p.period_start and p.period_end;
    v_expected:=a.opening_native+v_net;

    select count(*) into v_cash_due
    from (
      select distinct timezone('America/Caracas',m.occurred_at)::date d
      from public.account_movements m
      where m.account_id=a.account_id
        and timezone('America/Caracas',m.occurred_at)::date between p.period_start and p.period_end
    ) d
    where not exists(
      select 1 from public.cash_closings cc
      where cc.location_id=p.location_id and cc.business_date=d.d and cc.status='CLOSED'
    );
  end if;

  v_tol:=case when a.currency='USD' then .01 when a.account_type='CASH' then 1 else .01 end;
  v_diff:=case when a.closing_native is null then null else a.closing_native-v_expected end;

  if a.closing_native is null then
    v_ready:=false; v_blockers:=v_blockers||jsonb_build_array('Falta saldo final de '||a.name);
  end if;
  if a.account_type='BANK' and not v_imported then
    v_ready:=false; v_blockers:=v_blockers||jsonb_build_array('Falta importar el período completo de '||a.name);
  end if;
  if v_pending>0 then
    v_ready:=false; v_blockers:=v_blockers||jsonb_build_array(a.name||': '||v_pending||' movimiento(s) sin conciliar');
  end if;
  if v_conflicts>0 then
    v_ready:=false; v_blockers:=v_blockers||jsonb_build_array(a.name||': '||v_conflicts||' conflicto(s) de fuente');
  end if;
  if v_cash_due>0 then
    v_ready:=false; v_blockers:=v_blockers||jsonb_build_array(a.name||': '||v_cash_due||' día(s) de caja sin cerrar');
  end if;
  if v_diff is not null and abs(v_diff)>v_tol then
    v_ready:=false; v_blockers:=v_blockers||jsonb_build_array(a.name||': diferencia de '||v_diff::text||' '||a.currency);
  end if;

  v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
    'account_id',a.account_id,'code',a.code,'name',a.name,'currency',a.currency,'type',a.account_type,
    'opening',a.opening_native,'closing',a.closing_native,'net',v_net,'expected_closing',v_expected,'difference',v_diff,
    'source_id',v_source,'source_name',v_source_name,'imported',v_imported,'pending',v_pending,'conflicts',v_conflicts,'cash_days_due',v_cash_due
  ));
 end loop;

 select count(*) into v_cashea_pending
 from public.external_transactions x join public.external_sources s on s.id=x.source_id and s.provider='CASHEA_TRANSACTIONS'
 where timezone('America/Caracas',x.occurred_at)::date between p.period_start and p.period_end
   and least(x.amount_ref,x.assigned_ref)-coalesce((select sum(ra.external_amount) from public.reconciliation_allocations ra where ra.external_transaction_id=x.id and ra.reversed_at is null),0)>.005;
 select exists(select 1 from public.external_import_batches b join public.external_sources s on s.id=b.source_id and s.provider='CASHEA_TRANSACTIONS'
   where b.requested_from<=p.period_start and b.requested_to>=p.period_end and coalesce(jsonb_array_length(b.validation->'errors'),0)=0)
 into v_cashea_batch;
 if not v_cashea_batch then
   v_ready:=false; v_blockers:=v_blockers||jsonb_build_array('Falta importar cobros Cashea de la semana');
 end if;
 if v_cashea_pending>0 then
   v_ready:=false; v_blockers:=v_blockers||jsonb_build_array('Cashea: '||v_cashea_pending||' cobro(s) por conciliar');
 end if;

 return jsonb_build_object('id',p.id,'status',p.status,'start',p.period_start,'end',p.period_end,'ready',case when p.status='OPEN' then v_ready else true end,
   'accounts',v_rows,'cashea',jsonb_build_object('imported',v_cashea_batch,'pending',v_cashea_pending),
   'blockers',v_blockers,'close_reason',p.close_reason,'closed_at',p.closed_at);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.get_bcv_official_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if auth.uid() is null then raise exception 'Inicia sesión para consultar el captador oficial'; end if;
 return jsonb_build_object('provider','BCV_OFFICIAL','mode',case when to_regprocedure('lubricenter_private.bcv_promote_official_observation(date)') is null then 'OBSERVER' else 'NATIVE_BRIDGE' end,
 'state',(select to_jsonb(s)-'id' from lubricenter_private.bcv_official_observer_state s where id),
 'current',(select to_jsonb(o)-'evidence_html' from lubricenter_private.bcv_official_observations o where value_date<=(now() at time zone 'America/Caracas')::date order by value_date desc limit 1),
 'next',(select to_jsonb(o)-'evidence_html' from lubricenter_private.bcv_official_observations o where value_date>(now() at time zone 'America/Caracas')::date order by value_date limit 1));
end$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.get_notion_pricing_job_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if auth.role() is distinct from 'service_role' then raise exception 'Solo el sincronizador interno'; end if;
 return jsonb_build_object('catalog_native',exists(select 1 from public.app_settings where key='catalog_authority' and value #>> '{}'='LUBRICENTER_OS'),
 'rate_authority',public.exchange_rate_authority(),'rates_verified_at',(select last_verified_at from public.integration_sync_state where source_key='notion_rates'));
