CREATE OR REPLACE FUNCTION lubricenter_private.guard_closed_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oid uuid; s text;
begin
 if TG_TABLE_NAME='orders' then s:=old.status;
 else oid:=coalesce(new.order_id,old.order_id); select status into s from public.orders where id=oid for update;
 end if;
 if s in ('CLOSED','CANCELLED') then perform lubricenter_private.require_order_admin(); end if;
 return coalesce(new,old);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.guard_inventory_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.inventory_movements; i public.order_items; flow text:=coalesce(current_setting('lubricenter.inventory_lifecycle',true),'');
begin
 if tg_op<>'INSERT' then raise exception 'El inventario conserva sus movimientos. Registra un ajuste o una devolución; no edites ni borres el historial'; end if;
 if new.order_item_id is not null and new.movement_type in ('SALE','RETURN') then
  select * into i from public.order_items where id=new.order_item_id;
  if not found then raise exception 'La línea de la orden no existe'; end if;
  if new.inventory_item_id is distinct from i.inventory_item_id then raise exception 'El movimiento no corresponde al SKU de la orden'; end if;
  if new.movement_type='SALE' then
   if flow<>'SALE' or new.quantity_delta<>-i.quantity then raise exception 'La salida se genera al cerrar la orden, con su cantidad exacta'; end if;
  else
   select * into s from public.inventory_movements where id=new.reversal_of and movement_type='SALE';
   if flow<>'RETURN' or not found or s.order_item_id<>new.order_item_id or s.inventory_item_id<>new.inventory_item_id
    or s.location_id<>new.location_id or new.quantity_delta<>-s.quantity_delta then raise exception 'La devolución debe revertir la salida original exacta'; end if;
  end if;
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.guard_order_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if old.status in ('CLOSED','CANCELLED') and new.status='OPEN' or old.status='CANCELLED' and new.status='CLOSED' then
  raise exception 'Una orden cerrada o anulada no se reabre. Usa una corrección vinculada para conservar cobros e inventario';
 end if;
 if new.status='CANCELLED' and old.status<>'CANCELLED' then
  if (old.status='CLOSED' or exists(select 1 from public.payments where order_id=old.id))
    and coalesce(current_setting('lubricenter.order_cancel_flow',true),'')<>'yes' then raise exception 'Esta orden requiere anulación auditada de sus cobros e inventario'; end if;
  perform lubricenter_private.return_order_stock(old.id,'Anulación '||old.order_number||': '||coalesce(new.cancellation_reason,'Sin motivo'));
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.guard_order_tender()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='orders' then
  if new.status='CANCELLED' and old.status<>'CANCELLED' and exists(select 1 from public.order_tenders where order_id=old.id and (change_usd>0 or received<>applied)) then raise exception 'Esta venta tiene un cobro con vuelto documentado. Requiere devolución auditada antes de anular'; end if;
 elsif tg_table_name='account_movements' then
  if old.tender_id is not null then raise exception 'El movimiento pertenece a un cobro con vuelto documentado; requiere reversión auditada'; end if;
 elsif exists(select 1 from public.order_tenders where payment_id=old.id) then raise exception 'El cobro conserva dinero y vuelto documentados; no se puede borrar ni modificar con el editor anterior';
 end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.guard_stock_item_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oid uuid:=case when tg_op='INSERT' then new.order_id else old.order_id end;s text;
begin
 select status into s from public.orders where id=oid for update;
 if s in ('CLOSED','CANCELLED') then
  if tg_op='INSERT' and new.inventory_item_id is not null
   or tg_op='DELETE' and old.inventory_item_id is not null then raise exception 'Corrige la venta mediante una orden vinculada para ajustar su inventario'; end if;
  if tg_op='UPDATE' then
   if (old.inventory_item_id is not null or new.inventory_item_id is not null) and
    row(old.inventory_item_id,old.inventory_location_id,old.quantity,old.order_id) is distinct from row(new.inventory_item_id,new.inventory_location_id,new.quantity,new.order_id)
    then raise exception 'No se puede cambiar el SKU o cantidad de una orden cerrada sin su corrección de inventario'; end if;
  end if;
 end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.inventory_receive_purchase(p_request_id uuid, p_invoice_id uuid, p_location_id uuid, p_received_on date, p_items jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invoice public.supplier_invoices;
  v_line public.supplier_invoice_items;
  v_inventory public.inventory_items;
  v_entry jsonb;
  v_canonical jsonb;
  v_hash text;
  v_prior public.purchase_receipt_requests;
  v_line_id uuid;
  v_qty numeric;
  v_pending numeric;
  v_previous_qty numeric;
  v_average numeric;
  v_receipt uuid;
  v_receipt_line uuid;
  v_seen uuid[] := '{}'::uuid[];
  v_count integer := 0;
begin
  perform lubricenter_private.require_order_admin();
  if p_request_id is null or p_invoice_id is null or p_location_id is null then
    raise exception 'Identifica solicitud, factura y ubicación';
  end if;
  if p_received_on is null or p_received_on > timezone('America/Caracas',now())::date then
    raise exception 'Fecha de recepción inválida';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array'
     or jsonb_array_length(p_items) not between 1 and 100 then
    raise exception 'Selecciona de 1 a 100 líneas a recibir';
  end if;
  if not exists (select 1 from public.locations where id=p_location_id and active) then
    raise exception 'Selecciona una ubicación activa';
  end if;
  for v_entry in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_entry) is distinct from 'object'
       or coalesce(v_entry->>'line_id','')=''
       or coalesce(v_entry->>'quantity','')='' then
      raise exception 'Cada línea debe incluir ID y cantidad';
    end if;
    v_line_id := (v_entry->>'line_id')::uuid;
    v_qty := (v_entry->>'quantity')::numeric;
    if v_qty is null or v_qty<=0
       or v_qty::text in ('NaN','Infinity','-Infinity') then
      raise exception 'Las cantidades recibidas deben ser positivas';
    end if;
    if v_line_id=any(v_seen) then raise exception 'Línea duplicada en la recepción'; end if;
    v_seen := array_append(v_seen,v_line_id);
  end loop;

  select jsonb_agg(
    jsonb_build_object('line_id',x.line_id,'quantity',trim_scale(x.quantity))
    order by x.line_id::text
  ) into v_canonical
  from jsonb_to_recordset(p_items) as x(line_id uuid,quantity numeric);
  v_hash := md5(p_invoice_id::text||'|'||p_location_id::text||'|'||
    p_received_on::text||'|'||coalesce(trim(p_notes),'')||'|'||v_canonical::text);

  -- Serialize concurrent requests, then each invoice independently. The same
  -- request token is repeatable ONLY with exactly the same payload.
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,221022));
  select * into v_prior from public.purchase_receipt_requests where request_id=p_request_id;
  if found then
    if v_prior.supplier_invoice_id<>p_invoice_id or v_prior.location_id<>p_location_id
       or v_prior.payload_hash<>v_hash then
      raise exception 'Esta solicitud ya se utilizó con datos distintos';
    end if;
    return v_prior.receipt_id;
  end if;
  select * into v_invoice from public.supplier_invoices where id=p_invoice_id for update;
  if not found or v_invoice.status='VOID' then
    raise exception 'Factura anulada o inexistente';
  end if;

  -- Validate ALL lines before applying a single mutation. A missing line,
  -- expense line or over-receipt aborts the complete transaction.
  for v_entry in select value from jsonb_array_elements(p_items) loop
    v_line_id := (v_entry->>'line_id')::uuid;
    v_qty := (v_entry->>'quantity')::numeric;
    select * into v_line from public.supplier_invoice_items
      where id=v_line_id and supplier_invoice_id=p_invoice_id for update;
    if not found or v_line.line_type<>'INVENTORY'
       or v_line.inventory_item_id is null then
      raise exception 'La línea no corresponde al inventario de esta factura';
    end if;
    v_pending := v_line.quantity-v_line.received_quantity;
    if v_pending<=0 or v_qty>v_pending then
      raise exception 'Cantidad superior a la pendiente de recibir: %',v_line.description;
    end if;
    if not exists (
      select 1 from public.inventory_items i
      where i.id=v_line.inventory_item_id and i.active
    ) then
      raise exception 'El artículo de inventario está inactivo o no existe';
    end if;
  end loop;

  insert into public.supplier_receipts(supplier_invoice_id,location_id,received_on,notes)
  values(p_invoice_id,p_location_id,p_received_on,nullif(trim(p_notes),''))
  returning id into v_receipt;

  -- Order consistently to avoid deadlocks on shared inventory SKUs.
  for v_entry in
    select x.value
    from jsonb_array_elements(p_items) x
    join public.supplier_invoice_items ii on ii.id=(x.value->>'line_id')::uuid
    order by ii.inventory_item_id,ii.id
  loop
    v_line_id := (v_entry->>'line_id')::uuid;
    v_qty := (v_entry->>'quantity')::numeric;
    select * into v_line from public.supplier_invoice_items where id=v_line_id for update;
    select * into v_inventory from public.inventory_items
      where id=v_line.inventory_item_id for update;
    select coalesce(sum(m.quantity_delta),0) into v_previous_qty
    from public.inventory_movements m
    where m.inventory_item_id=v_inventory.id;
    v_average := case when v_previous_qty>0 then
      round((v_previous_qty*v_inventory.average_cost_ref +
        v_qty*v_line.unit_cost_ref)/(v_previous_qty+v_qty),4)
      else v_line.unit_cost_ref end;

    insert into public.supplier_receipt_items(
      supplier_receipt_id,supplier_invoice_item_id,inventory_item_id,quantity,unit_cost_ref,
      average_cost_before,average_cost_after,quantity_before
    ) values(v_receipt,v_line.id,v_inventory.id,v_qty,v_line.unit_cost_ref,
      v_inventory.average_cost_ref,v_average,v_previous_qty)
    returning id into v_receipt_line;

    insert into public.inventory_movements(
      inventory_item_id,location_id,quantity_delta,movement_type,note,
      occurred_at,supplier_receipt_item_id
    ) values(
      v_inventory.id,p_location_id,v_qty,'PURCHASE',
      'Recepción de factura '||v_invoice.invoice_number,
      ((p_received_on::timestamp+time '12:00') at time zone 'America/Caracas'),
      v_receipt_line
    );
    update public.supplier_invoice_items
      set received_quantity=received_quantity+v_qty where id=v_line.id;
    update public.inventory_items
      set average_cost_ref=v_average,
          last_purchase_cost_ref=case when last_purchased_at is null or
            last_purchased_at<=((p_received_on::timestamp+time '12:00') at time zone 'America/Caracas')
            then v_line.unit_cost_ref else last_purchase_cost_ref end,
          last_purchased_at=greatest(last_purchased_at,((p_received_on::timestamp+time '12:00') at time zone 'America/Caracas')),
          cost_missing=case when v_average>0 then false else cost_missing end,
          updated_at=now()
      where id=v_inventory.id;
    v_count := v_count+1;
  end loop;

  insert into public.purchase_receipt_requests(
    request_id,supplier_invoice_id,location_id,payload_hash,receipt_id
  ) values(p_request_id,p_invoice_id,p_location_id,v_hash,v_receipt);
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('supplier_receipt.posted_v2','supplier_receipt',v_receipt,
    jsonb_build_object('request_id',p_request_id,'invoice_id',p_invoice_id,
     'location_id',p_location_id,'received_on',p_received_on,'lines',v_count,
     'quantities',v_canonical,'actor',auth.uid()));
  return v_receipt;
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.inventory_save_item(p_id uuid, p_sku text, p_display_name text, p_brand text, p_category text, p_unit text, p_price_usd numeric, p_image_url text, p_alt_codes text[], p_active boolean, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.inventory_items; v_id uuid;
  v_sku text := upper(btrim(coalesce(p_sku,'')));
  v_name text := btrim(coalesce(p_display_name,''));
  v_photo text := nullif(btrim(coalesce(p_image_url,'')),'');
  v_codes text[] := coalesce((select array_agg(distinct btrim(c)) from unnest(coalesce(p_alt_codes,'{}')) c where btrim(c) <> ''), '{}');
begin
  perform lubricenter_private.require_order_admin();
  if length(v_sku) < 2 or length(v_sku) > 60 then raise exception 'Código (SKU) inválido'; end if;
  if length(v_name) < 2 or length(v_name) > 180 then raise exception 'Nombre de venta inválido: usa entre 2 y 180 caracteres'; end if;
  if p_price_usd is not null and (p_price_usd < 0 or p_price_usd > 1000000 or p_price_usd::text in ('NaN','Infinity','-Infinity')) then
    raise exception 'Precio USD inválido'; end if;
  if v_photo is not null and (length(v_photo) > 1800 or v_photo !~* '^https://[^[:space:]]+$') then
    raise exception 'La foto debe ser una URL HTTPS válida'; end if;
  if exists(select 1 from public.inventory_items where upper(sku)=v_sku and id is distinct from p_id and merged_into is null) then
    raise exception 'Ya existe un artículo con el código %', v_sku; end if;
  if p_id is null then
    insert into public.inventory_items(sku, display_name, description, brand, category, unit, price_usd, price_updated_at,
      image_url, alt_codes, active, needs_review, cost_missing, source_name, imported_at, updated_at)
    values (v_sku, v_name, v_name, nullif(btrim(coalesce(p_brand,'')),''), nullif(btrim(coalesce(p_category,'')),''),
      coalesce(nullif(btrim(coalesce(p_unit,'')),''),'UND'), nullif(p_price_usd,0), case when nullif(p_price_usd,0) is not null then now() end,
      v_photo, v_codes, coalesce(p_active,true), false, true, 'Lubricenter OS', now(), now())
    returning id into v_id;
  else
    select * into v_old from public.inventory_items where id=p_id for update;
    if v_old.id is null then raise exception 'Artículo no encontrado'; end if;
    if p_expected_updated_at is not null and v_old.updated_at is distinct from p_expected_updated_at then
      raise exception 'Otra persona modificó este artículo. Recarga antes de guardar.'; end if;
    update public.inventory_items set
      sku=v_sku, display_name=v_name, brand=nullif(btrim(coalesce(p_brand,'')),''),
      category=nullif(btrim(coalesce(p_category,'')),''), unit=coalesce(nullif(btrim(coalesce(p_unit,'')),''),unit),
      price_usd=nullif(p_price_usd,0),
      price_updated_at=case when nullif(p_price_usd,0) is distinct from v_old.price_usd then now() else v_old.price_updated_at end,
      image_url=v_photo, alt_codes=v_codes, active=coalesce(p_active,v_old.active), updated_at=now()
    where id=p_id;
    v_id := p_id;
  end if;
  insert into public.audit_events(event_type, entity_type, entity_id, data, actor_id)
  values ('inventory.item_saved','inventory_item',v_id,
    jsonb_build_object('sku',v_sku,'name',v_name,'price_usd',p_price_usd,
      'before', case when v_old.id is null then null else jsonb_build_object('sku',v_old.sku,'name',v_old.display_name,'price_usd',v_old.price_usd,'active',v_old.active) end),
    auth.uid());
  return jsonb_build_object('id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.inventory_set_count_at_location(p_inventory_item_id uuid, p_location_id uuid, p_expected_quantity numeric, p_new_count numeric, p_note text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_current numeric; v_delta numeric;
begin
 perform lubricenter_private.require_order_admin();
 if p_new_count is null or p_new_count<0 or p_new_count::text in ('NaN','Infinity','-Infinity')
   or p_expected_quantity is null or nullif(trim(p_note),'') is null then
   raise exception 'Indica conteo válido y motivo del ajuste';
 end if;
 if not exists(select 1 from public.locations where id=p_location_id and active) then
   raise exception 'Sede no disponible';
 end if;
 perform 1 from public.inventory_items where id=p_inventory_item_id and active for update;
 if not found then raise exception 'Artículo no disponible'; end if;
 select coalesce(sum(quantity_delta),0) into v_current from public.inventory_movements
   where inventory_item_id=p_inventory_item_id and location_id=p_location_id;
 if v_current<>p_expected_quantity then
   raise exception 'Las existencias cambiaron. Actualiza antes de confirmar el conteo';
 end if;
 v_delta:=p_new_count-v_current;
 if v_delta<>0 then
   insert into public.inventory_movements(inventory_item_id,location_id,quantity_delta,movement_type,note)
   values(p_inventory_item_id,p_location_id,v_delta,'ADJUSTMENT',trim(p_note));
   insert into public.audit_events(event_type,entity_type,entity_id,data)
   values('inventory.counted','inventory_item',p_inventory_item_id,jsonb_build_object(
    'location_id',p_location_id,'previous',v_current,'counted',p_new_count,'note',trim(p_note),'actor',auth.uid()));
 end if;
 update public.inventory_items set needs_review=false,updated_at=now() where id=p_inventory_item_id;
 return p_new_count;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.inventory_set_price_bulk(p_item_ids uuid[], p_price_usd numeric)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
  perform lubricenter_private.require_order_admin();
  if p_price_usd is null or p_price_usd <= 0 or p_price_usd > 1000000 then raise exception 'Precio USD inválido'; end if;
  if coalesce(array_length(p_item_ids,1),0) = 0 or array_length(p_item_ids,1) > 500 then raise exception 'Selecciona entre 1 y 500 artículos'; end if;
  update public.inventory_items set price_usd=p_price_usd, price_updated_at=now(), updated_at=now() where id = any(p_item_ids) and active;
  get diagnostics n = row_count;
  insert into public.audit_events(event_type, entity_type, data, actor_id)
  values ('inventory.price_bulk','inventory_item', jsonb_build_object('items', p_item_ids, 'price_usd', p_price_usd, 'updated', n), auth.uid());
  return n;
end;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.normalize_order_walk_in()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  -- Corrections inherit walk-in status from the original order when no party is
  -- supplied. This keeps old quick services editable by the authorized account.
  if tg_op = 'INSERT'
     and new.corrects_order_id is not null
     and new.customer_id is null
     and new.vehicle_id is null then
    select o.is_walk_in into new.is_walk_in
    from public.orders o
    where o.id = new.corrects_order_id;
  end if;

  -- Any real customer or vehicle turns the order back into a tracked service.
  if new.customer_id is not null or new.vehicle_id is not null then
    new.is_walk_in := false;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.order_items_reapply_adjustments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_order uuid := coalesce(new.order_id, old.order_id);
begin
  if exists(select 1 from public.orders o where o.id = v_order and o.status = 'OPEN'
      and (o.adjust_discount_percent > 0 or o.adjust_rounding_mode <> 'NONE')) then
    perform lubricenter_private.recompute_order_adjustments(v_order);
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.owner_pin_check(p_pin text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s lubricenter_private.owner_secrets;
begin
  select * into s from lubricenter_private.owner_secrets where key = 'discount_pin' for update;
  if not found then return 'NOT_CONFIGURED'; end if;
  if s.locked_until is not null and s.locked_until > now() then return 'LOCKED'; end if;
  if p_pin is not null and s.secret_hash = extensions.crypt(p_pin, s.secret_hash) then
    update lubricenter_private.owner_secrets set failed_attempts = 0, locked_until = null where key = 'discount_pin';
    return 'OK';
  end if;
  update lubricenter_private.owner_secrets
  set failed_attempts = s.failed_attempts + 1,
      locked_until = case when s.failed_attempts + 1 >= 5 then now() + interval '15 minutes' end
  where key = 'discount_pin';
  return case when s.failed_attempts + 1 >= 5 then 'LOCKED' else 'WRONG' end;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_mark_historical_paid(p_run_id uuid, p_paid_on date, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.payroll_runs;
  v_paid numeric(18,2);
  v_outstanding numeric(18,2);
  v_id uuid;
begin
  perform lubricenter_private.require_order_admin();

  if p_paid_on is null or p_paid_on>timezone('America/Caracas',now())::date then
    raise exception 'Fecha inválida';
  end if;
  if length(trim(coalesce(p_note,'')))<8 then
    raise exception 'Explica la regularización histórica';
  end if;

  select * into r
  from public.payroll_runs
  where id=p_run_id and status='SETTLED'
  for update;
  if not found then raise exception 'Liquidación no disponible'; end if;

  select coalesce(sum(usd_equivalent),0)
  into v_paid
  from public.payroll_payments
  where payroll_run_id=p_run_id;

  v_outstanding:=round(r.total_ref-v_paid-
    coalesce((select sum(x.usd_applied) from public.payroll_advance_applications x
      where x.payroll_run_id=p_run_id),0),2);
  if v_outstanding<=0 then
    raise exception 'Esta liquidación ya está pagada';
  end if;

  insert into public.payroll_payments(
    payroll_run_id,paid_on,currency,amount_original,usd_equivalent,
    note,payment_mode,component
  )
  values(
    r.id,p_paid_on,'MANUAL',v_outstanding,v_outstanding,
    trim(p_note),'HISTORICAL_MANUAL','MANUAL'
  )
  returning id into v_id;

  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values(
    'payroll.historical_payment_regularized','payroll_payment',v_id,
    jsonb_build_object(
      'run_id',r.id,'paid_on',p_paid_on,'usd_equivalent',v_outstanding,
      'note',trim(p_note),'actor',auth.uid()
    )
  );

  return v_id;
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_record_payment(p_run_id uuid, p_account_id uuid, p_paid_on date, p_amount_original numeric, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.payroll_runs;
  a public.financial_accounts;
  v_bcv public.exchange_rates;
  v_op public.exchange_rates;
  v_usd numeric(18,2);
  v_total_paid numeric(18,2);
  v_advances_paid numeric(18,2);
  v_outstanding numeric(18,2);
  v_value_ves numeric(18,2);
  v_hard_due numeric(18,2);
  v_bcv_due numeric(18,2);
  v_hard_paid numeric(18,2);
  v_bcv_paid numeric(18,2);
  v_component text;
  v_component_outstanding numeric(18,2);
  v_movement uuid;
  v_id uuid;
  v_name text;
begin
  perform lubricenter_private.require_order_admin();
  perform pg_advisory_xact_lock(220034);

  if p_paid_on is null or p_paid_on>timezone('America/Caracas',now())::date then
    raise exception 'Selecciona una fecha de pago válida';
  end if;
  if p_amount_original is null or p_amount_original<=0 then
    raise exception 'Monto inválido';
  end if;

  select * into r
  from public.payroll_runs
  where id=p_run_id and status='SETTLED'
  for update;
  if not found then raise exception 'Liquidación no disponible'; end if;

  select * into a
  from public.financial_accounts
  where id=p_account_id
    and active
    and currency in ('USD','VES')
    and account_type in ('BANK','CASH','CLEARING')
  for update;
  if not found then raise exception 'Selecciona una cuenta activa USD o Bs'; end if;

  if a.account_type='BANK'
     and length(regexp_replace(coalesce(p_reference,''),'\D','','g'))<4 then
    raise exception 'Indica al menos los últimos 4 dígitos de la referencia bancaria';
  end if;

  select
    coalesce(sum(usd_equivalent),0),
    coalesce(sum(usd_equivalent) filter(where component='HARD_USD'),0),
    coalesce(sum(usd_equivalent) filter(where component='BCV_VES'),0)
  into v_total_paid,v_hard_paid,v_bcv_paid
  from public.payroll_payments
  where payroll_run_id=p_run_id;

  select coalesce(sum(x.usd_applied),0) into v_advances_paid
  from public.payroll_advance_applications x where x.payroll_run_id=p_run_id;
  v_total_paid:=v_total_paid+v_advances_paid;
  v_outstanding:=round(r.total_ref-v_total_paid,2);
  if v_outstanding<=0 then raise exception 'Esta liquidación ya está pagada'; end if;

  v_hard_due:=round(least(coalesce(r.commission_hard_usd,0),r.total_ref),2);
  v_bcv_due:=round(r.total_ref-v_hard_due,2);
  -- An already paid advance covers the BCV portion before any HARD_USD component.
  v_bcv_paid:=v_bcv_paid+least(v_advances_paid,v_bcv_due);
  v_hard_paid:=v_hard_paid+greatest(v_advances_paid-v_bcv_due,0);

  if a.currency='VES' then
    v_component:='BCV_VES';
    v_component_outstanding:=round(v_bcv_due-v_bcv_paid,2);
    if v_component_outstanding<=0 then
      raise exception 'La parte pagadera en Bs ya está saldada. Queda únicamente USD real';
    end if;

    select * into v_bcv
    from public.exchange_rates
    where rate_type='BCV'
      and effective_at<((p_paid_on+1)::timestamp at time zone 'America/Caracas')
    order by effective_at desc
    limit 1;
    if not found or v_bcv.value<=0 then
      raise exception 'No hay tasa BCV para esa fecha';
    end if;

    v_usd:=round(p_amount_original/v_bcv.value,2);
    v_value_ves:=round(p_amount_original,2);
  else
    if round(v_hard_due-v_hard_paid,2)>0 then
      v_component:='HARD_USD';
      v_component_outstanding:=round(v_hard_due-v_hard_paid,2);
    else
      v_component:='BCV_VES';
      v_component_outstanding:=round(v_bcv_due-v_bcv_paid,2);
    end if;

    v_usd:=round(p_amount_original,2);

    select * into v_op
    from public.exchange_rates
    where rate_type='OPERATIVE'
      and effective_at<((p_paid_on+1)::timestamp at time zone 'America/Caracas')
    order by effective_at desc
    limit 1;
    if not found or v_op.value<=0 then
      raise exception 'No hay tasa operativa para esa fecha';
    end if;

    v_value_ves:=round(p_amount_original*v_op.value,2);
  end if;

  if v_usd>v_component_outstanding+0.01 then
    if v_component='HARD_USD' then
      raise exception 'USD real pendiente: $%. Registra primero ese monto; luego puedes hacer otro pago para la parte BCV',v_component_outstanding;
    end if;
    raise exception 'El pago supera la parte BCV pendiente de $%',v_component_outstanding;
  end if;

  select name into v_name
  from public.employees
  where id=r.employee_id;

  insert into public.account_movements(
    account_id,direction,movement_type,currency,amount_original,value_ves,
    category,payee,note,reference,occurred_at,finance_nature
  )
  values(
    a.id,'OUT','EXPENSE',a.currency,round(p_amount_original,2),v_value_ves,
    'Nómina',v_name,
    coalesce(nullif(trim(p_note),''),'Pago nómina '||r.period_start||' al '||r.period_end),
    nullif(trim(p_reference),''),
    (p_paid_on::timestamp+time '12:00') at time zone 'America/Caracas',
    'PAYROLL'
  )
  returning id into v_movement;

  insert into public.payroll_payments(
    payroll_run_id,account_id,account_movement_id,paid_on,currency,
    amount_original,usd_equivalent,bcv_rate,bcv_effective_at,
    reference,note,payment_mode,component
  )
  values(
    r.id,a.id,v_movement,p_paid_on,a.currency,
    round(p_amount_original,2),v_usd,
    case when a.currency='VES' then v_bcv.value end,
    case when a.currency='VES' then v_bcv.effective_at end,
    nullif(trim(p_reference),''),nullif(trim(p_note),''),'ACTUAL',v_component
  )
  returning id into v_id;

  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values(
    'payroll.payment_recorded','payroll_payment',v_id,
    jsonb_build_object(
      'run_id',r.id,'movement_id',v_movement,'paid_on',p_paid_on,
      'currency',a.currency,'component',v_component,
      'amount_original',round(p_amount_original,2),
      'usd_equivalent',v_usd,'account_id',a.id,'actor',auth.uid()
    )
  );

  return v_id;
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_record_salary_payment(p_run_id uuid, p_account_id uuid, p_paid_on date, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.payroll_runs; a public.financial_accounts; v_rate public.exchange_rates; v_amount numeric(18,2); v_movement uuid; v_id uuid; v_name text;
begin
 perform lubricenter_private.require_order_admin();
 perform pg_advisory_xact_lock(220033);
 if p_paid_on is null or p_paid_on>timezone('America/Caracas',now())::date then raise exception 'Selecciona una fecha de pago válida'; end if;
 select * into r from public.payroll_runs where id=p_run_id for update;
 if not found or r.status<>'SETTLED' or r.payroll_version<>2 then raise exception 'Selecciona una liquidación vigente de nómina'; end if;
 if r.fixed_ref<=0 then raise exception 'Esta liquidación no tiene sueldo fijo por pagar'; end if;
 if exists(select 1 from public.payroll_salary_payments where payroll_run_id=p_run_id) then raise exception 'El sueldo fijo de esta liquidación ya fue registrado'; end if;
 select * into a from public.financial_accounts where id=p_account_id and active and currency='VES' and account_type in ('BANK','CASH') for update;
 if not found then raise exception 'Selecciona una cuenta activa en bolívares'; end if;
 if a.account_type='BANK' and length(regexp_replace(coalesce(p_reference,''),'\D','','g'))<4 then raise exception 'Indica al menos los últimos 4 dígitos de la referencia bancaria'; end if;
 select * into v_rate from public.exchange_rates where rate_type='BCV' and effective_at<((p_paid_on+1)::timestamp at time zone 'America/Caracas') order by effective_at desc limit 1;
 if not found or v_rate.value<=0 then raise exception 'No hay tasa BCV disponible para la fecha de pago'; end if;
 v_amount:=round(r.fixed_ref*v_rate.value,2);
 if v_amount<=0 then raise exception 'El sueldo convertido no puede ser cero'; end if;
 select name into v_name from public.employees where id=r.employee_id;
 insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,payee,note,reference,occurred_at,finance_nature)
 values(a.id,'OUT','EXPENSE','VES',v_amount,v_amount,'Sueldo fijo',v_name,'Nómina '||r.period_start||' al '||r.period_end,nullif(trim(p_reference),''),(p_paid_on::timestamp+time '12:00') at time zone 'America/Caracas','PAYROLL') returning id into v_movement;
 insert into public.payroll_salary_payments(payroll_run_id,account_id,account_movement_id,paid_on,salary_ref,bcv_rate,bcv_effective_at,amount_ves,reference)
 values(r.id,a.id,v_movement,p_paid_on,r.fixed_ref,v_rate.value,v_rate.effective_at,v_amount,nullif(trim(p_reference),'')) returning id into v_id;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('payroll.salary_paid','payroll_salary_payment',v_id,jsonb_build_object('run_id',r.id,'movement_id',v_movement,'paid_on',p_paid_on,'salary_ref',r.fixed_ref,'bcv_rate',v_rate.value,'bcv_rate_id',v_rate.id,'amount_ves',v_amount,'account_id',a.id,'actor',auth.uid()));
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_review(p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
  p_start date;
begin
  perform lubricenter_private.payroll_sync();
  if p_end is null then raise exception 'Indica el sábado de cierre'; end if;
  if extract(isodow from p_end)<>6 then raise exception 'La fecha de cierre de nómina debe ser sábado'; end if;
  p_start:=p_end-5;

  select coalesce(jsonb_agg(to_jsonb(w) order by w.earned_at,w.id),'[]')
  into result
  from public.payroll_work_items w
  where w.payroll_run_id is null
    and (w.earned_at at time zone 'America/Caracas')::date <= p_end;

  return result;
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_review_adjustment(p_id uuid, p_version integer, p_decision text, p_amount_ref numeric, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.payroll_adjustments%rowtype;
 v_decision text:=upper(coalesce(p_decision,''));
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 SELECT * INTO a FROM public.payroll_adjustments WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Ajuste no encontrado'; END IF;
 IF a.payroll_run_id IS NOT NULL THEN RAISE EXCEPTION 'Este ajuste ya fue liquidado'; END IF;
 IF a.transfer_id IS NOT NULL THEN RAISE EXCEPTION 'Modifica la transferencia como pareja, no cada empleado'; END IF;
 IF a.version<>p_version THEN RAISE EXCEPTION 'El ajuste cambió. Recarga'; END IF;
 IF v_decision NOT IN('PAY','HOLD','EXCLUDE') OR p_amount_ref IS NULL
 OR p_amount_ref=0 OR p_amount_ref::text IN('NaN','Infinity','-Infinity') THEN
  RAISE EXCEPTION 'Decisión o importe inválido'; END IF;
 IF length(trim(coalesce(p_note,'')))<5 THEN RAISE EXCEPTION 'Explica el motivo'; END IF;
 UPDATE public.payroll_adjustments
 SET decision=v_decision,amount_ref=round(p_amount_ref,2),note=trim(p_note),
  version=version+1,updated_at=now() WHERE id=p_id;
 INSERT INTO public.audit_events(event_type,entity_type,entity_id,data)
 VALUES('payroll.adjustment_reviewed','payroll_adjustment',p_id,
   jsonb_build_object('before',to_jsonb(a),
    'after',(select to_jsonb(x) from public.payroll_adjustments x where x.id=p_id),
    'actor',auth.uid()));
 RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_review_work(p_id uuid, p_version integer, p_decision text, p_amount numeric, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.payroll_work_items; updated public.payroll_work_items;
begin
 perform lubricenter_private.require_order_admin();
 perform pg_advisory_xact_lock(240924,1);
 select * into w from public.payroll_work_items where id=p_id for update;
 if not found then raise exception 'Trabajo no encontrado'; end if;
 if w.payroll_run_id is not null then raise exception 'Este trabajo ya está liquidado; su recibo no se puede reescribir'; end if;
 if w.version<>p_version then raise exception 'El trabajo cambió. Recarga la revisión antes de guardar'; end if;
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Explica el motivo del cambio (mínimo 5 caracteres)'; end if;
 if p_decision is null or p_decision not in ('PAY','HOLD','EXCLUDE') or p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') then raise exception 'Decisión o monto inválido'; end if;
 if w.reversal_of is null and p_amount<0 then raise exception 'La comisión no puede ser negativa'; end if;
 if w.reversal_of is null and (not exists(select 1 from public.payroll_accruals where id=w.accrual_id) or not exists(select 1 from public.payments where id=w.payment_id) or not exists(select 1 from public.orders where id=w.order_id and status='CLOSED')) then raise exception 'Este trabajo fue anulado o corregido y no puede pagarse'; end if;
 if w.reversal_of is not null and p_amount<>w.amount then raise exception 'La reversión conserva el monto originalmente liquidado'; end if;
 update public.payroll_work_items set decision=p_decision,amount=round(p_amount,2),reason=trim(p_reason),version=version+1 where id=p_id returning * into updated;
 insert into public.audit_events(event_type,entity_type,entity_id,data) values('payroll.work_reviewed','payroll_work_item',p_id,jsonb_build_object('reason',p_reason,'before',to_jsonb(w),'after',to_jsonb(updated),'actor',auth.uid()));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_review_work_v3(p_id uuid, p_version integer, p_decision text, p_obligation_usd numeric, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.payroll_work_items; updated public.payroll_work_items;
begin
 perform lubricenter_private.require_order_admin();
 perform pg_advisory_xact_lock(240924,1);
 select * into w from public.payroll_work_items where id=p_id for update;
 if not found then raise exception 'Trabajo no encontrado'; end if;
 if w.payroll_run_id is not null then raise exception 'Este trabajo ya está liquidado; su recibo no se puede reescribir'; end if;
 if w.version<>p_version then raise exception 'El trabajo cambió. Recarga la revisión antes de guardar'; end if;
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Explica el motivo del cambio (mínimo 5 caracteres)'; end if;
 if p_decision is null or p_decision not in ('PAY','HOLD','EXCLUDE')
    or p_obligation_usd is null or p_obligation_usd::text in ('NaN','Infinity','-Infinity')
 then raise exception 'Decisión o monto inválido'; end if;
 if w.reversal_of is null and p_obligation_usd<0 then raise exception 'La comisión no puede ser negativa'; end if;
 if w.reversal_of is null and (
   not exists(select 1 from public.payroll_accruals where id=w.accrual_id)
   or not exists(select 1 from public.payments where id=w.payment_id)
   or not exists(select 1 from public.orders where id=w.order_id and status='CLOSED')
 ) then raise exception 'Este trabajo fue anulado o corregido y no puede pagarse'; end if;
 if w.reversal_of is not null and p_obligation_usd<>w.obligation_usd then
   raise exception 'La reversión conserva el monto originalmente liquidado';
 end if;
 update public.payroll_work_items
 set decision=p_decision,
     obligation_usd=round(p_obligation_usd,2),
     reason=trim(p_reason),
     version=version+1
 where id=p_id
 returning * into updated;
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('payroll.work_reviewed_v3','payroll_work_item',p_id,
   jsonb_build_object('reason',p_reason,'before',to_jsonb(w),'after',to_jsonb(updated),'actor',auth.uid()));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_settle(p_employee_id uuid, p_period_start date, p_period_end date, p_expected jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  run_id uuid; fixed numeric:=0; variable numeric:=0; adjustments numeric:=0;
  hard_usd numeric:=0; bcv_usd numeric:=0; actual_work jsonb; actual_adjustments jsonb;
v_advance record; v_available numeric(18,2); v_apply numeric(18,2); v_remaining numeric(18,2);
begin
  perform lubricenter_private.payroll_sync();

  if p_period_start is null or p_period_end is null or p_period_end<p_period_start or p_period_end-p_period_start<>5 then
    raise exception 'Selecciona una semana de lunes a sábado';
  end if;
  if extract(isodow from p_period_start)<>1 or extract(isodow from p_period_end)<>6 then
    raise exception 'La nómina debe ir de lunes a sábado';
  end if;
  if p_period_end>timezone('America/Caracas',now())::date then
    raise exception 'No puedes liquidar una semana que todavía no ha terminado';
  end if;

  perform 1 from public.employees where id=p_employee_id and active for update;
  if not found then raise exception 'Empleado no disponible'; end if;

  if exists(
    select 1 from public.payroll_runs
    where employee_id=p_employee_id and status='SETTLED'
      and daterange(period_start,period_end,'[]')&&daterange(p_period_start,p_period_end,'[]')
  ) then
    raise exception 'Este empleado ya tiene una liquidación para ese período';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) order by id),'[]')
  into actual_work
  from public.payroll_work_items
  where employee_id=p_employee_id and payroll_run_id is null
    and decision in ('PAY','EXCLUDE')
    and (earned_at at time zone 'America/Caracas')::date <= p_period_end;

  if p_expected->'work' is distinct from actual_work then
    raise exception 'Cambió el detalle de trabajos. Revisa el resumen actualizado antes de liquidar';
  end if;

  select coalesce(value,0) into fixed
  from public.compensation_rules
  where employee_id=p_employee_id and rule_type='FIXED_WEEKLY'
    and valid_from<=p_period_end and (valid_to is null or valid_to>=p_period_end)
  order by valid_from desc limit 1;
  fixed:=coalesce(fixed,0);

  if p_expected->'fixed_ref' is distinct from to_jsonb(fixed) then
    raise exception 'Cambió el sueldo fijo. Recarga y revisa el resumen';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object('id',id,'version',version,'decision',decision,'amount_ref',amount_ref)
    order by id
  ),'[]')
  into actual_adjustments
  from public.payroll_adjustments
  where employee_id=p_employee_id
    and payroll_run_id is null
    and decision in ('PAY','EXCLUDE')
    and occurred_on<=p_period_end;

  if p_expected->'adjustments' is distinct from actual_adjustments then
    raise exception 'Cambiaron los ajustes. Recarga y revisa el resumen';
  end if;

  select
    coalesce(sum(obligation_usd),0),
    coalesce(sum(obligation_usd) filter(where payout_mode='HARD_USD'),0),
    coalesce(sum(obligation_usd) filter(where payout_mode='BCV_VES'),0)
  into variable,hard_usd,bcv_usd
  from public.payroll_work_items
  where employee_id=p_employee_id
    and payroll_run_id is null
    and decision='PAY'
    and (earned_at at time zone 'America/Caracas')::date <= p_period_end;

  select coalesce(sum(amount_ref),0) into adjustments
  from public.payroll_adjustments
  where employee_id=p_employee_id
    and payroll_run_id is null
    and decision='PAY'
    and occurred_on<=p_period_end;

  if fixed+variable+adjustments<0 then
    raise exception 'El saldo a favor del negocio supera esta liquidación; prorroga parte de los descuentos y revisa el detalle';
  end if;

  insert into public.payroll_runs(
    employee_id,period_start,period_end,fixed_ref,variable_ref,adjustments_ref,total_ref,
    commission_usd,commission_ves,commission_hard_usd,commission_bcv_usd,payroll_version
  )
  values(
    p_employee_id,p_period_start,p_period_end,fixed,variable,adjustments,fixed+variable+adjustments,
    hard_usd,null,hard_usd,bcv_usd,3
  )
  returning id into run_id;

  update public.payroll_work_items
  set payroll_run_id=run_id
  where employee_id=p_employee_id
    and payroll_run_id is null
    and decision in ('PAY','EXCLUDE')
    and (earned_at at time zone 'America/Caracas')::date <= p_period_end;

  update public.payroll_adjustments
  set payroll_run_id=run_id,updated_at=now()
  where employee_id=p_employee_id
    and payroll_run_id is null
    and decision in ('PAY','EXCLUDE')
    and occurred_on<=p_period_end;

  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values(
    'payroll.settled_v5','payroll_run',run_id,
    jsonb_build_object(
      'actor',auth.uid(),
      'period_start',p_period_start,
      'period_end',p_period_end,
      'commission_hard_usd',hard_usd,
      'commission_bcv_usd',bcv_usd,
      'fixed_ref',fixed,
      'adjustments_ref',adjustments,
      'work_items',actual_work,
      'adjustments',actual_adjustments
    )
  );


 -- Apply prepaid wages only to this employee's unsettled payroll. Never create a second cash outflow.
 v_remaining:=round(fixed+variable+adjustments,2);
 FOR v_advance IN
   SELECT pa.id,pa.usd_equivalent,
      coalesce((SELECT sum(x.usd_applied) FROM public.payroll_advance_applications x WHERE x.advance_id=pa.id),0) already_applied
   FROM public.payroll_advances pa
   WHERE pa.employee_id=p_employee_id AND pa.intended_period_end<=p_period_end
   ORDER BY pa.paid_on,pa.created_at,pa.id FOR UPDATE OF pa
 LOOP
   v_available:=round(v_advance.usd_equivalent-v_advance.already_applied,2);
   v_apply:=least(v_available,v_remaining);
   IF v_apply>0.009 THEN
     INSERT INTO public.payroll_advance_applications(advance_id,payroll_run_id,usd_applied)
     VALUES(v_advance.id,run_id,v_apply);
     v_remaining:=round(v_remaining-v_apply,2);
   END IF;
   EXIT WHEN v_remaining<=0.009;
 END LOOP;
 -- Persist audited inclusion, exclusion and deferred decisions at settlement time.
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 select 'payroll.settlement_admin_snapshot','payroll_run',run_id,
 jsonb_build_object(
   'employee_id',p_employee_id,'period_start',p_period_start,'period_end',p_period_end,
   'included_work',coalesce((select jsonb_agg(to_jsonb(w) order by w.earned_at,w.id)
     from public.payroll_work_items w where w.payroll_run_id=run_id),'[]'::jsonb),
   'deferred_work',coalesce((select jsonb_agg(to_jsonb(w) order by w.earned_at,w.id)
     from public.payroll_work_items w where w.employee_id=p_employee_id and w.payroll_run_id is null
       and w.decision='HOLD' and (w.earned_at at time zone 'America/Caracas')::date<=p_period_end),'[]'::jsonb),
   'included_adjustments',coalesce((select jsonb_agg(to_jsonb(a) order by a.occurred_on,a.id)
     from public.payroll_adjustments a where a.payroll_run_id=run_id),'[]'::jsonb),
   'deferred_adjustments',coalesce((select jsonb_agg(to_jsonb(a) order by a.occurred_on,a.id)
     from public.payroll_adjustments a where a.employee_id=p_employee_id and a.payroll_run_id is null
       and a.decision='HOLD' and a.occurred_on<=p_period_end),'[]'::jsonb),
   'fixed_ref',fixed,'commission_hard_usd',hard_usd,'commission_bcv_usd',bcv_usd,
   'adjustments_ref',adjustments,'total_ref',fixed+variable+adjustments,
   'snapshot_type','immutable_admin_audit');

  return run_id;
end
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.payroll_work_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if old.payroll_run_id is not null then raise exception 'Una comisión liquidada conserva su historial; registra una reversión'; end if;
 insert into public.payroll_work_history(work_item_id,reason,before_data,after_data)
 values(new.id,case when new.payroll_run_id is not null then 'Incluido en liquidación '||new.payroll_run_id::text else coalesce(new.reason,'Actualización de revisión') end,to_jsonb(old),to_jsonb(new));
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.prepare_quick_sale(p_request uuid, p_items jsonb, p_business_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.sale_operation_requests; payload jsonb:=jsonb_build_array(p_items,p_business_at); result jsonb;
begin
 perform public.require_auth();
 if p_request is null then raise exception 'Falta el identificador de la venta'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,99));
 select * into previous from public.sale_operation_requests where id=p_request;
 if found then
  if previous.actor_id<>auth.uid() or previous.kind<>'DRAFT' or previous.payload<>payload then raise exception 'Solicitud reutilizada con otros datos'; end if;
  return previous.result;
 end if;
 result:=lubricenter_private.quick_sale_dated(p_items,'DRAFT',p_business_at);
 insert into public.sale_operation_requests values(p_request,auth.uid(),'DRAFT',payload,result,now());
 return result;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.quick_sale_cashea_split(p_request uuid, p_items jsonb, p_business_at timestamp with time zone, p_initial_percent numeric, p_initial_payments jsonb, p_cashea_reference text, p_expected_total_ves numeric, p_expected_total_ref numeric, p_expected_bcv numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hash text; v_previous record; v_draft jsonb; v_order_id uuid;
  v_sale_id uuid; v_response jsonb; v_date date;
BEGIN
  PERFORM public.require_auth();
  IF p_request IS NULL THEN RAISE EXCEPTION 'Falta identificador de cobro. Reabre la venta'; END IF;
  v_hash:=md5(jsonb_build_array(p_items,p_business_at,p_initial_percent,p_initial_payments,
     p_cashea_reference,p_expected_total_ves,p_expected_total_ref,p_expected_bcv)::text);
  INSERT INTO public.cashea_split_requests(request_id,payload_hash)
    VALUES(p_request,v_hash) ON CONFLICT DO NOTHING;
  SELECT * INTO v_previous FROM public.cashea_split_requests WHERE request_id=p_request FOR UPDATE;
  IF v_previous.payload_hash<>v_hash THEN
    RAISE EXCEPTION 'Este intento de cobro corresponde a otro desglose. Usa una nueva operación';
  END IF;
  IF v_previous.order_id IS NOT NULL THEN
    SELECT jsonb_build_object(
      'order_id',o.id,'order_number',o.order_number,'total_ves',o.total_ves,
      'total_ref',o.total_ref,'initial_ref',s.initial_ref,
      'initial_ves',s.initial_ves_snapshot,'financed_ref',s.financed_ref,
      'commission_ref',s.commission_ref,'cashea_sale_id',s.id
    ) INTO v_response
    FROM public.orders o JOIN public.cashea_sales s ON s.order_id=o.id
    WHERE o.id=v_previous.order_id;
    IF v_response IS NULL THEN RAISE EXCEPTION 'La venta registrada no se pudo recuperar'; END IF;
    RETURN v_response;
  END IF;
  v_draft:=lubricenter_private.quick_sale_dated(
    p_items,'DRAFT',p_business_at,'TRANSFER_BDV',NULL,40,NULL);
  v_order_id:=(v_draft->>'order_id')::uuid;
  v_sale_id:=lubricenter_private.close_order_cashea_split(
    v_order_id,p_initial_percent,p_initial_payments,p_cashea_reference,
    p_expected_total_ves,p_expected_total_ref,p_expected_bcv);
  v_date:=(coalesce(p_business_at,now()) AT TIME ZONE 'America/Caracas')::date;
  UPDATE public.cashea_installments SET due_date=v_date+installment_no*14
    WHERE cashea_sale_id=v_sale_id;
  UPDATE public.cashea_split_requests SET order_id=v_order_id WHERE request_id=p_request;
  SELECT jsonb_build_object(
    'order_id',o.id,'order_number',o.order_number,'total_ves',o.total_ves,
    'total_ref',o.total_ref,'initial_ref',s.initial_ref,
    'initial_ves',s.initial_ves_snapshot,'financed_ref',s.financed_ref,
    'commission_ref',s.commission_ref,'cashea_sale_id',s.id
  ) INTO v_response
  FROM public.orders o JOIN public.cashea_sales s ON s.order_id=o.id
  WHERE o.id=v_order_id;
  RETURN v_response;
END;
$function$;

CREATE OR REPLACE FUNCTION lubricenter_private.quick_sale_dated(p_items jsonb, p_mode text, p_business_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_method text DEFAULT 'MOBILE_PAYMENT'::text, p_reference text DEFAULT NULL::text, p_initial_percent numeric DEFAULT 40, p_cashea_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; d date; begin
 perform public.require_auth(); perform set_config('lubricenter.business_at',coalesce(p_business_at::text,''),true);
 if p_mode='DIRECT' then select * into r from public.complete_quick_sale(p_items,p_method,p_reference);
 elsif p_mode='CASHEA' then
  select * into r from public.complete_quick_sale_cashea(p_items,p_initial_percent,p_method,p_reference,p_cashea_reference);
  d:=(coalesce(p_business_at,now()) at time zone 'America/Caracas')::date;
  update public.cashea_installments set due_date=d+installment_no*14 where cashea_sale_id=r.cashea_sale_id;
 elsif p_mode='DRAFT' then select * into r from public.build_quick_sale_order(p_items);
 else raise exception 'Tipo de venta inválido'; end if;
 return to_jsonb(r);
end $function$;

