CREATE OR REPLACE FUNCTION lubricenter_private.receivable_fill_currencies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rate numeric;
begin
  if new.principal_usd is null then
    v_rate := lubricenter_private.order_divisas_rate(new.order_id);
    if v_rate is not null and v_rate > 0 then
      new.principal_usd := round(new.principal_ves / v_rate, 2);
    end if;
  end if;
  if tg_op = 'INSERT' then
    new.outstanding_fraction := case
      when new.status = 'PAID' then 0
      when coalesce(new.principal_ves, 0) <= 0 then 1
      else least(1, greatest(0, coalesce(new.outstanding_ves, new.principal_ves) / new.principal_ves))
    end;
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.recompute_order_adjustments(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.orders; i record;
  v_total numeric; v_base numeric; v_discount numeric := 0; v_after numeric; v_target numeric;
  v_rounding numeric := 0; v_delta numeric; v_left numeric; v_share numeric; v_new numeric; v_count int; v_n int := 0;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found or o.status <> 'OPEN' then return null; end if;

  update public.order_items it
  set charged_ref_amount = it.list_ref_amount, charged_ves_amount = it.list_ves_amount,
      list_ref_amount = null, list_ves_amount = null
  where it.order_id = p_order_id and it.list_ref_amount is not null;

  select coalesce(sum(it.charged_ref_amount), 0) into v_total from public.order_items it where it.order_id = p_order_id;

  select coalesce(sum(greatest(it.charged_ref_amount - coalesce(it.worker_share_ref_snapshot, 0)
           - coalesce(it.assistant_bonus_ref_snapshot, 0), 0)), 0), count(*)
    into v_base, v_count
  from public.order_items it
  where it.order_id = p_order_id
    and lubricenter_private.effective_line_role(it) in ('PRODUCT','LABOR','OIL_LABOR')
    and greatest(it.charged_ref_amount - coalesce(it.worker_share_ref_snapshot, 0)
           - coalesce(it.assistant_bonus_ref_snapshot, 0), 0) > 0;

  if o.adjust_discount_percent > 0 then
    v_discount := round((v_total - coalesce((select sum(it.charged_ref_amount) from public.order_items it
      where it.order_id = p_order_id and lubricenter_private.effective_line_role(it) = 'CASHEA_SURCHARGE'), 0))
      * o.adjust_discount_percent / 100, 2);
  end if;
  v_after := v_total - v_discount;
  v_target := case o.adjust_rounding_mode
    when 'DOWN' then floor(v_after)
    when 'UP' then ceil(v_after)
    when 'HALF' then round(v_after * 2) / 2
    else round(v_after, 2) end;
  v_rounding := v_target - v_after;
  v_delta := v_target - v_total;

  if v_delta = 0 or v_count = 0 or v_base <= 0 then
    update public.orders set adjust_discount_ref = 0, adjust_rounding_ref = 0 where id = p_order_id;
    return jsonb_build_object('total_ref', v_total, 'discount_ref', 0, 'rounding_ref', 0);
  end if;
  if -v_delta > v_base then
    raise exception 'El descuento es mayor que la parte de Lubricenter en esta orden (% REF)', round(v_base, 2);
  end if;

  v_left := v_delta;
  for i in
    select it.id, it.charged_ref_amount, it.charged_ves_amount, it.bcv_rate_snapshot,
      greatest(it.charged_ref_amount - coalesce(it.worker_share_ref_snapshot, 0)
        - coalesce(it.assistant_bonus_ref_snapshot, 0), 0) as lc
    from public.order_items it
    where it.order_id = p_order_id
      and lubricenter_private.effective_line_role(it) in ('PRODUCT','LABOR','OIL_LABOR')
      and greatest(it.charged_ref_amount - coalesce(it.worker_share_ref_snapshot, 0)
        - coalesce(it.assistant_bonus_ref_snapshot, 0), 0) > 0
    order by it.charged_ref_amount desc, it.id
  loop
    v_n := v_n + 1;
    v_share := case when v_n = v_count then v_left else round(v_delta * i.lc / v_base, 4) end;
    v_left := v_left - v_share;
    v_new := round(i.charged_ref_amount + v_share, 4);
    update public.order_items it
    set list_ref_amount = i.charged_ref_amount, list_ves_amount = i.charged_ves_amount,
        charged_ref_amount = v_new, charged_ves_amount = round(v_new * i.bcv_rate_snapshot, 2)
    where it.id = i.id;
  end loop;

  update public.orders set adjust_discount_ref = v_discount, adjust_rounding_ref = v_rounding where id = p_order_id;
  return jsonb_build_object('total_ref', v_target, 'discount_ref', v_discount, 'rounding_ref', v_rounding);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.release_customer_balance_payment(p_payment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_use public.customer_balance_movements; v_entry uuid;
begin
  select * into v_use from public.customer_balance_movements
    where payment_id=p_payment_id and movement_type='USE';
  if not found then return; end if;
  perform 1 from public.customer_balance_accounts
    where customer_id=v_use.customer_id and pocket=v_use.pocket for update;
  if exists(select 1 from public.customer_balance_movements
    where related_movement_id=v_use.id and movement_type='RELEASE') then return; end if;
  update public.customer_balance_accounts set balance_usd=balance_usd-v_use.delta_usd,updated_at=now()
    where customer_id=v_use.customer_id and pocket=v_use.pocket;
  insert into public.customer_balance_movements(
    customer_id,pocket,movement_type,delta_usd,amount_original,currency,value_ves,
    bcv_rate_snapshot,operative_rate_snapshot,method,note,order_id,payment_id,related_movement_id
  ) values (
    v_use.customer_id,v_use.pocket,'RELEASE',-v_use.delta_usd,v_use.amount_original,v_use.currency,v_use.value_ves,
    v_use.bcv_rate_snapshot,v_use.operative_rate_snapshot,v_use.method,p_reason,v_use.order_id,p_payment_id,v_use.id
  ) returning id into v_entry;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('customer_balance.released','customer_balance_movement',v_entry,
    jsonb_build_object('customer_id',v_use.customer_id,'order_id',v_use.order_id,
      'payment_id',p_payment_id,'original_movement_id',v_use.id,'reason',p_reason));
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.return_order_change(p_request uuid, p_tender uuid, p_usd numeric, p_currency text, p_rate numeric, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.order_tenders; r public.order_change_returns; a uuid; m uuid; amount numeric; payload jsonb;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 payload:=jsonb_build_array(p_tender,p_usd,p_currency,p_rate,p_note);
 if p_request is null then raise exception 'Falta el identificador del cobro'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,0));
 select * into r from public.order_change_returns where id=p_request;
 if found then
  if r.request_payload<>payload then raise exception 'Solicitud reutilizada con otros datos'; end if;
  return r.id;
 end if;
 perform pg_advisory_xact_lock(220033);
 select * into t from public.order_tenders where id=p_tender for update;
 if not found then raise exception 'Vuelto no encontrado'; end if;
 if p_usd is null or p_usd<=0 or p_usd>t.change_usd-t.returned_usd or round(p_usd,2)<>p_usd or p_usd::text in ('NaN','Infinity','-Infinity') then raise exception 'Monto superior al vuelto pendiente o inválido'; end if;
 if p_currency is null or p_currency not in ('USD','VES') or p_rate is null or p_rate<=0 or p_rate::text in ('NaN','Infinity','-Infinity') or round(p_rate,6)<>p_rate then raise exception 'Moneda o tasa inválida'; end if;
 if length(trim(coalesce(p_note,'')))<3 then raise exception 'Confirma la entrega del vuelto con una nota'; end if;
 select id into a from public.financial_accounts where code=case when p_currency='USD' then 'CASH_USD' else 'CASH_VES' end and active and currency=p_currency and account_type='CASH';
 if a is null then raise exception 'Configura la caja de la moneda que vas a entregar'; end if;
 amount:=case when p_currency='USD' then p_usd else round(p_usd*p_rate,2) end;
 if amount<=0 then raise exception 'El vuelto redondea a cero; usa otra moneda'; end if;
 insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,note,finance_nature,finance_request_id,tender_id)
 values(a,'OUT','ADJUSTMENT',p_currency,amount,case when p_currency='USD' then round(amount*p_rate,2) else amount end,'Vuelto',p_note,'REFUND',p_request,t.id) returning id into m;
 insert into public.order_change_returns(id,tender_id,currency,amount_usd,amount_original,rate,movement_id,note,request_payload)
 values(p_request,t.id,p_currency,p_usd,amount,p_rate,m,p_note,payload);
 update public.order_tenders set returned_usd=returned_usd+p_usd where id=t.id;
 return p_request;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.return_order_stock(p_order_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m record; prior text:=coalesce(current_setting('lubricenter.inventory_lifecycle',true),'');
begin
 perform public.require_auth();
 -- Use the same lock order as a new sale: business counter, then stock.
 -- Corrections restore stock before creating their replacement order.
 perform 1 from lubricenter_private.order_number_counter where singleton for update;
 perform set_config('lubricenter.inventory_lifecycle','RETURN',true);
 for m in select im.* from public.inventory_movements im join public.order_items i on i.id=im.order_item_id
  where i.order_id=p_order_id and im.movement_type='SALE' order by im.inventory_item_id,im.location_id,im.id loop
  perform 1 from public.inventory_items where id=m.inventory_item_id for update;
  insert into public.inventory_movements(inventory_item_id,location_id,quantity_delta,movement_type,order_item_id,note,reversal_of)
  values(m.inventory_item_id,m.location_id,-m.quantity_delta,'RETURN',m.order_item_id,p_reason,m.id)
  on conflict(reversal_of) where reversal_of is not null do nothing;
 end loop;
 perform set_config('lubricenter.inventory_lifecycle',prior,true);
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.reverse_split_payment_credit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_deposit public.customer_balance_movements; v_cash public.account_movements;
  v_available numeric; v_out uuid; v_entry uuid;
begin
  select * into v_deposit from public.customer_balance_movements
    where payment_id=old.id and origin='OVERPAYMENT';
  if not found then return old; end if;
  select balance_usd into v_available from public.customer_balance_accounts
    where customer_id=v_deposit.customer_id and pocket=v_deposit.pocket for update;
  if v_available<v_deposit.delta_usd then
    raise exception 'El sobrante de este pago ya se usó. Revisa el historial del cliente antes de quitar el cobro';
  end if;
  select * into v_cash from public.account_movements where id=v_deposit.account_movement_id;
  if not found then raise exception 'No se encontró el movimiento de caja del sobrante'; end if;
  insert into public.account_movements(account_id,direction,movement_type,currency,
    amount_original,value_ves,category,note,reference,occurred_at,created_by)
  values(v_cash.account_id,'OUT','ADJUSTMENT',v_cash.currency,v_cash.amount_original,
    v_cash.value_ves,'CUSTOMER_BALANCE_OVERPAYMENT_REVERSAL',
    'Reversión del pago de orden '||old.order_id::text,v_cash.id::text,now(),auth.uid())
  returning id into v_out;
  update public.customer_balance_accounts set balance_usd=balance_usd-v_deposit.delta_usd,
    updated_at=now() where customer_id=v_deposit.customer_id and pocket=v_deposit.pocket;
  insert into public.customer_balance_movements(customer_id,pocket,movement_type,origin,
    delta_usd,amount_original,currency,value_ves,bcv_rate_snapshot,
    operative_rate_snapshot,method,reference,note,order_id,payment_id,
    account_movement_id,related_movement_id)
  values(v_deposit.customer_id,v_deposit.pocket,'REVERSAL','OVERPAYMENT_REVERSAL',
    -v_deposit.delta_usd,v_deposit.amount_original,v_deposit.currency,v_deposit.value_ves,
    v_deposit.bcv_rate_snapshot,v_deposit.operative_rate_snapshot,v_deposit.method,
    v_deposit.reference,'Se quitó el pago que generó este sobrante',old.order_id,
    old.id,v_out,v_deposit.id) returning id into v_entry;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('customer_balance.overpayment_reversed','customer_balance_movement',v_entry,
    jsonb_build_object('order_id',old.order_id,'payment_id',old.id,
      'original_credit_id',v_deposit.id,'account_movement_id',v_out));
  return old;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.set_order_date(p_order_id uuid, p_business_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b numeric; op numeric;
begin
 perform public.require_auth(); perform public.assert_order_open(p_order_id);
 if p_business_at is null or p_business_at>now()+interval '5 minutes' then raise exception 'Indica la fecha real de la venta, sin fechas futuras'; end if;
 if exists(select 1 from public.payments where order_id=p_order_id) then
  raise exception 'La orden ya tiene pagos. La fecha y tasas quedan protegidas; usa una corrección auditada'; end if;
 select r.bcv_rate,r.operative_rate into b,op from public.get_exchange_rates_for_date((p_business_at at time zone 'America/Caracas')::date) r;
 perform set_config('lubricenter.reason','Cambio de fecha y recálculo histórico antes del cobro',true);
 update public.orders set business_at=p_business_at,opened_at=p_business_at,sale_bcv_rate=b,sale_operative_rate=op where id=p_order_id;
 update public.order_items set
  charged_ves_amount=case when price_denomination='USD' then round(agreed_usd*op,2) else round(charged_ves_amount*b/bcv_rate_snapshot,2) end,
  charged_ref_amount=case when price_denomination='USD' then round(agreed_usd*op/b,4) else charged_ref_amount end,
  base_ref_amount=case when price_denomination='USD' then round(base_ref_amount*(op/b)/(operative_rate_snapshot/bcv_rate_snapshot),4) else base_ref_amount end,
  customer_ref_amount=case when price_denomination='USD' then round(customer_ref_amount*(op/b)/(operative_rate_snapshot/bcv_rate_snapshot),4) else customer_ref_amount end,
  worker_share_ref_snapshot=case when price_denomination='USD' then round(worker_share_ref_snapshot*(op/b)/(operative_rate_snapshot/bcv_rate_snapshot),4) else worker_share_ref_snapshot end,
  assistant_bonus_ref_snapshot=case when price_denomination='USD' then round(assistant_bonus_ref_snapshot*(op/b)/(operative_rate_snapshot/bcv_rate_snapshot),4) else assistant_bonus_ref_snapshot end,
  bcv_rate_snapshot=b,operative_rate_snapshot=op
 where order_id=p_order_id;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.staff_action_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid; v_data jsonb;
begin
 if auth.uid() is null then return null; end if;
 select id into v_user from public.staff_users where auth_user_id=auth.uid();
 if v_user is null then return null; end if;
 v_data:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 insert into public.staff_activity_events(staff_user_id,actor_user_id,event_key,entity_type,entity_id,details)
 values(v_user,auth.uid(),lower(tg_op),tg_table_name,
 coalesce(v_data->>'id',v_data->>'order_id',v_data->>'cash_closing_id'),
 jsonb_build_object('action',tg_op));
 return null;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.staff_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_permission text;
 v_new jsonb;
 v_old jsonb;
begin
 if auth.uid() is null then
  if tg_op = 'DELETE' then return old; end if;
  return new;
 end if;
 if tg_op <> 'DELETE' then v_new := to_jsonb(new); end if;
 if tg_op <> 'INSERT' then v_old := to_jsonb(old); end if;
 v_permission := case tg_table_name
 when 'orders' then case
   when tg_op='INSERT' then 'orders.create'
   when tg_op='DELETE' then 'orders.cancel'
   when tg_op='UPDATE' and v_new->>'status' = 'CANCELLED'
        and (v_old->>'status') is distinct from (v_new->>'status') then 'orders.cancel'
   else 'orders.edit' end
 when 'order_items' then 'orders.edit'
 when 'payments' then 'payments.manage'
 when 'order_tenders' then 'payments.manage'
 when 'customers' then 'customers.manage'
 when 'vehicles' then 'customers.manage'
 when 'inventory_movements' then 'inventory.count'
 when 'products' then 'catalog.manage'
 when 'account_movements' then 'cash.manage'
 when 'cash_closings' then 'cash.close'
 when 'crm_manual_cases' then 'crm.manage'
 when 'payroll_adjustments' then 'payroll.manage'
 else null end;
 if tg_table_name='inventory_movements' and tg_op='INSERT' then
  if v_new->>'movement_type'='SALE' and current_setting('lubricenter.inventory_lifecycle',true)='SALE' then v_permission:='orders.edit';
  elsif v_new->>'movement_type'='RETURN' and current_setting('lubricenter.inventory_lifecycle',true)='RETURN' then v_permission:='orders.cancel'; end if;
 end if;
 if v_permission is not null and not lubricenter_private.staff_can(v_permission) then
  raise exception 'PERMISO_DENEGADO: %',v_permission using errcode='42501';
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION lubricenter_private.upsert_vehicle_crm(p_order_id uuid, p_vehicle_id uuid, p_is_correction boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_o public.orders%rowtype;v_owner uuid;v_type text:='POST_SERVICE';
 v_last text;v_text text;v_start date;v_saved uuid;
BEGIN
 SELECT * INTO v_o FROM public.orders WHERE id=p_order_id;
 IF NOT FOUND OR v_o.status<>'CLOSED' THEN RAISE EXCEPTION 'El CRM requiere una venta cerrada'; END IF;
 SELECT coalesce(v.customer_id,v_o.customer_id) INTO v_owner
 FROM public.vehicles v WHERE v.id=p_vehicle_id;
 IF v_owner IS NULL THEN RAISE EXCEPTION 'Vehículo sin propietario: completa el CRM antes de continuar'; END IF;
 IF p_is_correction AND EXISTS(
   SELECT 1 FROM public.customer_followups f WHERE f.order_id=p_order_id
    AND f.vehicle_id=p_vehicle_id AND f.followup_type='POST_SERVICE' AND f.status='SENT'
 ) THEN v_type:='POST_SERVICE_CORRECTION'; END IF;
 v_text:=public.build_post_service_message_for_vehicle(p_order_id,p_vehicle_id);
 IF v_type='POST_SERVICE_CORRECTION' THEN
  v_text:='📝 *Corrección del historial de mantenimiento*'||chr(10)||chr(10)||v_text;
 END IF;
 SELECT coalesce((s.value #>> '{}')::date,date '2026-09-10') INTO v_start
 FROM public.app_settings s WHERE s.key='crm_operational_start_date';
 v_start:=coalesce(v_start,date '2026-09-10');
 INSERT INTO public.customer_followups(
   order_id,customer_id,vehicle_id,followup_type,channel,status,message,sent_at
 ) VALUES (
   p_order_id,v_owner,p_vehicle_id,v_type,'WHATSAPP',
   case when p_is_correction OR (coalesce(v_o.closed_at,v_o.created_at) AT TIME ZONE 'America/Caracas')::date>=v_start
        then 'PENDING' else 'SENT' end,
   v_text,
   case when not p_is_correction AND (coalesce(v_o.closed_at,v_o.created_at) AT TIME ZONE 'America/Caracas')::date<v_start
       then coalesce(v_o.closed_at,now()) else null end
 )
 ON CONFLICT(order_id,followup_type,vehicle_id) WHERE vehicle_id IS NOT NULL
 DO UPDATE SET customer_id=excluded.customer_id,message=excluded.message,
 status=excluded.status,sent_at=excluded.sent_at,snoozed_until=null,updated_at=now()
 WHERE public.customer_followups.status<>'SENT'
 RETURNING id INTO v_saved;
 RETURN coalesce(v_saved,(select f.id from public.customer_followups f
  where f.order_id=p_order_id AND f.vehicle_id=p_vehicle_id AND f.followup_type=v_type));
END $function$;

CREATE OR REPLACE FUNCTION public.add_catalog_product_item_override(p_order_id uuid, p_product_id uuid, p_quantity numeric, p_manual_unit_ref numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stock_item uuid; v_linked uuid;
  v_product public.products;
  v_bcv numeric;
  v_op numeric;
  v_step numeric;
  v_mode text;
  v_unit_ves numeric;
  v_unit_ref numeric;
  v_item_id uuid;
begin
  perform public.require_auth();
  perform public.assert_order_open(p_order_id);
  v_stock_item:=lubricenter_private.catalog_stock_item(p_order_id,p_product_id);
  if v_stock_item is not null then
    v_linked:=public.add_inventory_product_item(p_order_id,v_stock_item,p_quantity,p_manual_unit_ref,'STORE');
    return v_linked;
  end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'Cantidad inválida'; end if;

  select * into v_product from public.products where id=p_product_id and active=true and available=true;
  if v_product.id is null then raise exception 'Producto no encontrado o no disponible'; end if;
  perform lubricenter_private.assert_stock_sale_allowed('CATALOG', v_product.name);

  select bcv_rate, operative_rate into v_bcv, v_op from public.get_order_rates(p_order_id);
  if v_bcv is null or v_op is null then raise exception 'Debes registrar tasa BCV y operativa antes de vender'; end if;
  select coalesce((value #>> '{}')::numeric,10) into v_step from public.app_settings where key='price_rounding_step';
  select coalesce(value #>> '{}','nearest') into v_mode from public.app_settings where key='price_rounding_mode';

  if p_manual_unit_ref is not null then
    if p_manual_unit_ref <= 0 then raise exception 'El precio manual debe ser mayor que cero'; end if;
    v_unit_ref := p_manual_unit_ref;
    v_unit_ves := public.round_to_step(v_unit_ref*v_bcv,coalesce(v_step,10),coalesce(v_mode,'nearest'));
  else
    if v_product.catalog_source='Notion · Nuestros Productos' then perform public.assert_notion_pricing_fresh(); end if;
    v_unit_ves := public.round_to_step(v_product.cash_usd_base_price*v_op,coalesce(v_step,10),coalesce(v_mode,'nearest'));
    v_unit_ref := v_unit_ves/v_bcv;
  end if;

  insert into public.order_items(
    order_id,item_type,business_area,description,product_id,quantity,pricing_mode,
    base_ref_amount,customer_ref_amount,charged_ves_amount,charged_ref_amount,
    cash_usd_unit_snapshot,cash_usd_special_total,bcv_rate_snapshot,operative_rate_snapshot,cash_price_revealed
  ) values (
    p_order_id,'PRODUCT','STORE',v_product.name,v_product.id,p_quantity,
    case when p_manual_unit_ref is null then 'STANDARD' else 'MANUAL_OVERRIDE' end,
    round(v_unit_ref*p_quantity,4),round(v_unit_ref*p_quantity,4),
    round(v_unit_ves*p_quantity,2),round(v_unit_ref*p_quantity,4),
    v_product.cash_usd_base_price,round(v_product.cash_usd_base_price*p_quantity,4),
    v_bcv,v_op,false
  ) returning id into v_item_id;
  return v_item_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_inventory_bonus_item(p_order_id uuid, p_inventory_item_id uuid, p_quantity numeric, p_reason text DEFAULT NULL::text, p_business_area text DEFAULT 'STORE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item public.inventory_items;
  v_order public.orders;
  v_location uuid;
  v_stock numeric;
  v_bcv numeric;
  v_op numeric;
  v_order_item uuid;
  v_area text := upper(coalesce(p_business_area,'STORE'));
  v_reason text := nullif(trim(coalesce(p_reason,'')),'');
begin
  perform public.require_auth();
  perform public.assert_order_open(p_order_id);
  if p_quantity is null or p_quantity <= 0 then raise exception 'Cantidad inválida'; end if;
  if v_area not in ('STORE','OIL_CHANGE') then raise exception 'Área de bonificación inválida'; end if;

  select * into v_order from public.orders where id=p_order_id for update;
  select * into v_item from public.inventory_items where id=p_inventory_item_id and active=true;
  if v_item.id is null then raise exception 'Producto de inventario no encontrado'; end if;
  if v_item.needs_review then raise exception 'Este SKU requiere revisión de inventario antes de bonificarlo: %',v_item.sku; end if;

  v_location := v_order.location_id;
  if v_location is null then
    select id into v_location from public.locations where code='CABUDARE' and active=true limit 1;
    if v_location is null then select id into v_location from public.locations where active=true order by created_at limit 1; end if;
    update public.orders set location_id=v_location where id=p_order_id;
  end if;
  if v_location is null then raise exception 'No hay sede activa para descontar inventario'; end if;

  perform 1 from public.inventory_items where id=v_item.id for update;
  v_stock := public.inventory_quantity(v_item.id,v_location);
  if v_stock < p_quantity then
    raise exception 'Stock insuficiente para bonificar %: disponible %, solicitado %',v_item.sku,v_stock,p_quantity;
  end if;

  select bcv_rate,operative_rate into v_bcv,v_op from public.get_order_rates(p_order_id);
  if v_bcv is null or v_op is null then raise exception 'Debes registrar tasa BCV y operativa antes de registrar la cortesía'; end if;

  insert into public.order_items(
    order_id,item_type,business_area,description,product_id,inventory_item_id,inventory_location_id,
    quantity,pricing_mode,base_ref_amount,customer_ref_amount,
    charged_ves_amount,charged_ref_amount,cash_usd_unit_snapshot,cash_usd_special_total,
    bcv_rate_snapshot,operative_rate_snapshot,cash_price_revealed
  ) values (
    p_order_id,'PRODUCT',v_area,
    '🎁 Cortesía · '||v_item.sku||' · '||v_item.description||case when v_reason is not null then ' · '||v_reason else '' end,
    v_item.product_id,v_item.id,v_location,
    p_quantity,'BONUS',0,0,0,0,null,null,v_bcv,v_op,false
  ) returning id into v_order_item;

  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('order.bonus_product_added','order_item',v_order_item,
         jsonb_build_object('order_id',p_order_id,'inventory_item_id',v_item.id,'sku',v_item.sku,'quantity',p_quantity,'reason',v_reason));

  return v_order_item;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_inventory_product_item(p_order_id uuid, p_inventory_item_id uuid, p_quantity numeric, p_manual_unit_ref numeric DEFAULT NULL::numeric, p_business_area text DEFAULT 'OIL_CHANGE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item public.inventory_items; v_order public.orders; v_location uuid; v_stock numeric; v_bcv numeric; v_op numeric;
  v_step numeric; v_mode text; v_unit_ves numeric; v_unit_ref numeric; v_cash_usd numeric; v_order_item uuid;
  v_area text := upper(coalesce(p_business_area,'OIL_CHANGE'));
begin
  perform public.require_auth();
  perform public.assert_order_open(p_order_id);
  if p_quantity is null or p_quantity <= 0 then raise exception 'Cantidad de inventario inválida'; end if;
  if v_area not in ('OIL_CHANGE','STORE') then raise exception 'Área de inventario inválida'; end if;
  select * into v_order from public.orders where id=p_order_id for update;
  select * into v_item from public.inventory_items where id=p_inventory_item_id and active=true;
  if v_item.id is null then raise exception 'Producto de inventario no encontrado'; end if;
  if v_item.needs_review then raise exception 'Este SKU requiere revisión de inventario antes de venderse: %', v_item.sku; end if;
  v_location := v_order.location_id;
  if v_location is null then
    select id into v_location from public.locations where code='CABUDARE' and active=true limit 1;
    if v_location is null then select id into v_location from public.locations where active=true order by created_at limit 1; end if;
    update public.orders set location_id=v_location where id=p_order_id;
  end if;
  if v_location is null then raise exception 'No hay sede activa para descontar inventario'; end if;
  perform 1 from public.inventory_items where id=v_item.id for update;
  v_stock := public.inventory_quantity(v_item.id,v_location);
  if v_stock < p_quantity then raise exception 'Stock insuficiente para %: el sistema tiene %, pediste %. Si llegó mercancía nueva, cárgala primero en Inventario (Ajustar conteo) y vuelve a cobrar.', v_item.sku, v_stock, p_quantity; end if;
  select bcv_rate,operative_rate into v_bcv,v_op from public.get_order_rates(p_order_id);
  if v_bcv is null or v_op is null then raise exception 'Debes registrar tasa BCV y operativa antes de vender'; end if;
  select coalesce((value #>> '{}')::numeric,10) into v_step from public.app_settings where key='price_rounding_step';
  select coalesce(value #>> '{}','nearest') into v_mode from public.app_settings where key='price_rounding_mode';
  if p_manual_unit_ref is not null then
    if p_manual_unit_ref <= 0 then raise exception 'El precio manual debe ser mayor que cero'; end if;
    v_unit_ref := p_manual_unit_ref;
    v_unit_ves := public.round_to_step(v_unit_ref*v_bcv,coalesce(v_step,10),coalesce(v_mode,'nearest'));
    v_cash_usd := null;
  else
    if coalesce(v_item.price_usd,0) <= 0 then raise exception 'El artículo % no tiene precio. Cárgalo en Inventario o escribe el precio REF.', v_item.sku; end if;
    perform public.assert_notion_pricing_fresh();
    v_cash_usd := v_item.price_usd;
    v_unit_ves := public.round_to_step(v_item.price_usd*v_op,coalesce(v_step,10),coalesce(v_mode,'nearest'));
    v_unit_ref := v_unit_ves/v_bcv;
  end if;
  insert into public.order_items(
    order_id,item_type,business_area,description,product_id,inventory_item_id,inventory_location_id,
    quantity,pricing_mode,base_ref_amount,customer_ref_amount,
    charged_ves_amount,charged_ref_amount,cash_usd_unit_snapshot,cash_usd_special_total,
    bcv_rate_snapshot,operative_rate_snapshot,cash_price_revealed
  ) values (
    p_order_id,'PRODUCT',v_area,v_item.sku||' · '||coalesce(v_item.display_name,v_item.description),v_item.product_id,v_item.id,v_location,
    p_quantity,'STANDARD',round(v_unit_ref*p_quantity,4),round(v_unit_ref*p_quantity,4),
    round(v_unit_ves*p_quantity,2),round(v_unit_ref*p_quantity,4),v_cash_usd,
    case when v_cash_usd is not null then round(v_cash_usd*p_quantity,4) else null end,
    v_bcv,v_op,false
  ) returning id into v_order_item;
  return v_order_item;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_manual_product_item(p_order_id uuid, p_description text, p_quantity numeric, p_unit_ref numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bcv numeric;
  v_op numeric;
  v_step numeric;
  v_mode text;
  v_unit_ves numeric;
  v_item_id uuid;
begin
  perform public.require_auth();
  perform public.assert_order_open(p_order_id);
  if nullif(trim(p_description),'') is null then raise exception 'Escribe el producto'; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'Cantidad inválida'; end if;
  if p_unit_ref is null or p_unit_ref <= 0 then raise exception 'El precio REF debe ser mayor que cero'; end if;
  perform lubricenter_private.assert_stock_sale_allowed('MANUAL', trim(p_description));

  select bcv_rate, operative_rate into v_bcv, v_op from public.get_order_rates(p_order_id);
  if v_bcv is null or v_op is null then raise exception 'Debes registrar tasa BCV y operativa antes de vender'; end if;
  select coalesce((value #>> '{}')::numeric,10) into v_step from public.app_settings where key='price_rounding_step';
  select coalesce(value #>> '{}','nearest') into v_mode from public.app_settings where key='price_rounding_mode';
  v_unit_ves := public.round_to_step(p_unit_ref*v_bcv,coalesce(v_step,10),coalesce(v_mode,'nearest'));

  insert into public.order_items(
    order_id,item_type,business_area,description,quantity,pricing_mode,
    base_ref_amount,customer_ref_amount,charged_ves_amount,charged_ref_amount,
    bcv_rate_snapshot,operative_rate_snapshot,cash_price_revealed
  ) values (
    p_order_id,'PRODUCT','STORE',trim(p_description),p_quantity,'MANUAL_NO_STOCK',
    round(p_unit_ref*p_quantity,4),round(p_unit_ref*p_quantity,4),
    round(v_unit_ves*p_quantity,2),round(p_unit_ref*p_quantity,4),
    v_bcv,v_op,false
  ) returning id into v_item_id;
  return v_item_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_oil_change_item(p_order_id uuid, p_description text, p_base_ref numeric, p_customer_ref numeric, p_odometer integer, p_oil_brand text DEFAULT NULL::text, p_oil_viscosity text DEFAULT NULL::text, p_oil_quantity_liters numeric DEFAULT NULL::numeric, p_filter_code text DEFAULT NULL::text, p_next_km_interval integer DEFAULT NULL::integer, p_next_months integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_vehicle_id uuid;
  v_current_odometer integer;
  v_bcv numeric;
  v_op numeric;
  v_step numeric;
  v_mode text;
  v_default_km integer;
  v_default_months integer;
  v_interval_km integer;
  v_interval_months integer;
  v_item_id uuid;
begin
  perform public.require_auth();
  perform public.assert_order_open(p_order_id);

  select o.vehicle_id, v.current_odometer
    into v_vehicle_id, v_current_odometer
  from public.orders o
  left join public.vehicles v on v.id=o.vehicle_id
  where o.id=p_order_id;

  if v_vehicle_id is null then
    raise exception 'Para registrar un cambio de aceite debes asociar un vehículo a la orden';
  end if;
  if coalesce(trim(p_description),'')='' then
    raise exception 'Descripción requerida';
  end if;
  if p_base_ref < 0 or p_customer_ref < 0 then
    raise exception 'Montos inválidos';
  end if;
  if p_odometer is null or p_odometer < 0 then
    raise exception 'Kilometraje requerido';
  end if;
  if v_current_odometer is not null and p_odometer < v_current_odometer then
    raise exception 'El kilometraje % es menor al registrado actualmente (%)', p_odometer, v_current_odometer;
  end if;
  if p_oil_quantity_liters is not null and p_oil_quantity_liters <= 0 then
    raise exception 'Cantidad de aceite inválida';
  end if;

  select bcv_rate,operative_rate into v_bcv,v_op from public.get_order_rates(p_order_id);
  if v_bcv is null or v_op is null then
    raise exception 'Debes registrar tasa BCV y operativa antes de vender';
  end if;
  select coalesce((value #>> '{}')::numeric,10) into v_step from public.app_settings where key='price_rounding_step';
  select coalesce(value #>> '{}','nearest') into v_mode from public.app_settings where key='price_rounding_mode';
  select coalesce((value #>> '{}')::integer,5000) into v_default_km from public.app_settings where key='oil_change_default_km';
  select coalesce((value #>> '{}')::integer,3) into v_default_months from public.app_settings where key='oil_change_default_months';

  v_interval_km := coalesce(p_next_km_interval,v_default_km,5000);
  v_interval_months := coalesce(p_next_months,v_default_months,3);
  if v_interval_km < 0 or v_interval_km > 50000 then raise exception 'Intervalo de kilometraje inválido'; end if;
  if v_interval_months < 0 or v_interval_months > 24 then raise exception 'Intervalo de meses inválido'; end if;

  insert into public.order_items(
    order_id,item_type,business_area,description,quantity,pricing_mode,
    base_ref_amount,customer_ref_amount,charged_ves_amount,charged_ref_amount,
    bcv_rate_snapshot,operative_rate_snapshot,
    service_odometer,oil_brand,oil_viscosity,oil_quantity_liters,oil_filter_code,
    next_service_odometer,next_service_date
  ) values (
    p_order_id,'SERVICE','OIL_CHANGE',trim(p_description),1,'STANDARD',
    p_base_ref,p_customer_ref,
    round(public.round_to_step(p_customer_ref*v_bcv,coalesce(v_step,10),coalesce(v_mode,'nearest')),2),
    round(p_customer_ref,4),v_bcv,v_op,
    p_odometer,nullif(trim(p_oil_brand),''),nullif(trim(p_oil_viscosity),''),p_oil_quantity_liters,nullif(trim(p_filter_code),''),
    case when v_interval_km > 0 then p_odometer+v_interval_km else null end,
    case when v_interval_months > 0 then (select (coalesce(business_at,opened_at) at time zone 'America/Caracas')::date from public.orders where id=p_order_id) + make_interval(months=>v_interval_months) else null end
  ) returning id into v_item_id;

  return v_item_id;
end;
$function$;

