CREATE OR REPLACE FUNCTION public.normalize_ve_document(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d text;
begin
  d := regexp_replace(upper(coalesce(p_value,'')),'[^0-9]','','g');
  if d is null or d='' or d ~ '^0+$' or length(d)<5 or length(d)>9 then return null; end if;
  return d;
end $function$;

CREATE OR REPLACE FUNCTION public.normalize_ve_phone(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d text;
begin
  d := regexp_replace(coalesce(p_value,''),'\D','','g');
  if d ~ '^58[4][0-9]{9}$' and length(d)=12 then return d; end if;
  if d ~ '^0[4][0-9]{9}$' and length(d)=11 then return '58'||substr(d,2); end if;
  if d ~ '^[4][0-9]{9}$' and length(d)=10 then return '58'||d; end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.normalize_vehicle_plate(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare p text;
begin
  p := regexp_replace(upper(coalesce(p_value,'')),'[^A-Z0-9]','','g');
  if p in ('','NA','NM','NF','ND','00000','000000') then return null; end if;
  if length(p)<5 or length(p)>8 or p !~ '[A-Z]' or p !~ '[0-9]' then return null; end if;
  return p;
end $function$;

CREATE OR REPLACE FUNCTION public.order_change_history(p_order uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform lubricenter_private.finance_require('OPERATOR');
 if p_offset is null or p_offset<0 then raise exception 'Página inválida'; end if;
 return jsonb_build_object(
  'total',(select count(*) from public.order_tenders where p_order is null or order_id=p_order),
  'pending_usd',(select coalesce(sum(change_usd-returned_usd),0) from public.order_tenders where p_order is null or order_id=p_order),
