CREATE OR REPLACE FUNCTION public.payroll_adjustment_update(p_id uuid, p_version integer, p_type text, p_decision text, p_amount_ref numeric, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.payroll_adjustments%rowtype;updated public.payroll_adjustments%rowtype;
 v_type text:=upper(coalesce(p_type,''));v_decision text:=upper(coalesce(p_decision,''));
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 SELECT * INTO a FROM public.payroll_adjustments WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Ajuste no encontrado'; END IF;
 IF a.payroll_run_id IS NOT NULL THEN RAISE EXCEPTION 'Ajuste ya liquidado. No se puede reescribir'; END IF;
 IF a.transfer_id IS NOT NULL THEN
  RAISE EXCEPTION 'La reasignación está vinculada a dos empleados. Usa Aprobar o Descartar transferencia';
 END IF;
 IF a.version<>p_version THEN RAISE EXCEPTION 'Ajuste modificado por otro usuario; recarga'; END IF;
 IF v_type NOT IN('SUPPLIES','ADVANCE','DEBT','BONUS','OTHER') OR
    v_decision NOT IN('PAY','HOLD','EXCLUDE') THEN
    RAISE EXCEPTION 'Tipo o decisión inválidos';
 END IF;
 IF p_amount_ref IS NULL OR p_amount_ref::text IN('NaN','Infinity','-Infinity')
   OR p_amount_ref=0 OR abs(p_amount_ref)>100000 THEN RAISE EXCEPTION 'Monto de ajuste inválido'; END IF;
 IF v_type='BONUS' AND p_amount_ref<=0 THEN RAISE EXCEPTION 'Un bono debe ser positivo'; END IF;
 IF v_type IN('DEBT','ADVANCE','SUPPLIES') AND p_amount_ref>=0 THEN
  RAISE EXCEPTION 'Un descuento debe ser negativo. El empleado no puede recibirlo como bono';
 END IF;
 IF length(btrim(coalesce(p_note,'')))<8 OR length(p_note)>700 THEN
  RAISE EXCEPTION 'Escribe un motivo de al menos 8 caracteres';
 END IF;
 UPDATE public.payroll_adjustments SET
  adjustment_type=v_type,decision=v_decision,amount_ref=round(p_amount_ref,2),
  note=btrim(p_note),version=version+1,updated_at=now()
 WHERE id=p_id RETURNING * INTO updated;
 INSERT INTO public.audit_events(event_type,entity_type,entity_id,data)
 VALUES('payroll.adjustment_updated_v2','payroll_adjustment',p_id,
  jsonb_build_object('before',to_jsonb(a),'after',to_jsonb(updated),
    'actor',auth.uid()));
 RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.payroll_cashea_set_policy(p_accrual_id uuid, p_mode text, p_period_end date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 accrual public.payroll_accruals%ROWTYPE;
 sale public.cashea_sales%ROWTYPE;
 existing public.cashea_payroll_policies%ROWTYPE;
 extra public.payroll_adjustments%ROWTYPE;
 already numeric:=0; outstanding numeric:=0;
 v_mode text:=upper(coalesce(p_mode,'')); v_reason text:=btrim(coalesce(p_reason,''));
 target_adjustment uuid;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 PERFORM set_config('lubricenter.cashea_policy_edit','yes',true);
 PERFORM pg_advisory_xact_lock(240924,1);
 IF v_mode NOT IN ('AS_COLLECTED','FULL_UPFRONT') THEN
   RAISE EXCEPTION 'Modo Cashea inválido'; END IF;
 IF p_period_end IS NULL OR extract(isodow from p_period_end)<>6
   OR p_period_end<timezone('America/Caracas',now())::date
 THEN RAISE EXCEPTION 'Selecciona un sábado de nómina todavía abierto'; END IF;
 IF length(v_reason)<8 THEN RAISE EXCEPTION 'Indica el motivo del acuerdo con el mecánico'; END IF;
 PERFORM lubricenter_private.payroll_sync();
 SELECT * INTO accrual FROM public.payroll_accruals WHERE id=p_accrual_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Comisión original no encontrada'; END IF;
 SELECT cs.* INTO sale FROM public.cashea_sales cs
 JOIN public.order_items i ON i.order_id=cs.order_id
 JOIN public.orders o ON o.id=cs.order_id
 WHERE i.id=accrual.source_order_item_id AND o.status='CLOSED'
  AND cs.status IN ('ACTIVE','SETTLED') AND cs.ownership_status='OWN'
 FOR UPDATE OF cs;
 IF NOT FOUND THEN RAISE EXCEPTION 'La comisión no corresponde a una venta Cashea vigente de este local'; END IF;
 SELECT * INTO existing FROM public.cashea_payroll_policies WHERE accrual_id=p_accrual_id FOR UPDATE;
 IF FOUND AND existing.mode='FULL_UPFRONT'
   AND EXISTS(SELECT 1 FROM public.payroll_adjustments a WHERE a.id=existing.advance_adjustment_id
      AND a.payroll_run_id IS NOT NULL)
 THEN RAISE EXCEPTION 'La comisión adelantada ya fue liquidada. La política histórica está bloqueada'; END IF;
 IF existing.mode='FULL_UPFRONT' AND v_mode='AS_COLLECTED'
   AND EXISTS(SELECT 1 FROM public.payroll_work_items w WHERE w.accrual_id=p_accrual_id
       AND w.reason LIKE 'Comisión ya cubierta por adelanto Cashea%'
       AND w.decision='EXCLUDE')
 THEN RAISE EXCEPTION 'Ya hay cuotas cubiertas por esta decisión. Para revertirla se requiere una rectificación auditada'; END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_work_items w WHERE w.accrual_id=p_accrual_id
  AND w.reversal_of IS NULL AND w.decision IN ('HOLD','EXCLUDE') AND w.payroll_run_id IS NULL)
 THEN RAISE EXCEPTION 'Hay cuotas de esta comisión retenidas o excluidas; revísalas antes de adelantar el saldo'; END IF;
 -- Includes all collected commission tranches, including already settled ones.
 SELECT coalesce(sum(w.obligation_usd),0) INTO already
 FROM public.payroll_work_items w WHERE w.accrual_id=p_accrual_id
   AND w.reversal_of IS NULL AND w.decision='PAY';
 outstanding:=round(greatest(accrual.amount_ref-already,0),2);
 IF v_mode='FULL_UPFRONT' AND outstanding<0.01
 THEN RAISE EXCEPTION 'No queda comisión por adelantar'; END IF;
 IF v_mode='FULL_UPFRONT' THEN
   IF existing.advance_adjustment_id IS NOT NULL THEN
     UPDATE public.payroll_adjustments SET decision='PAY',amount_ref=outstanding,
       adjustment_type='BONUS',note='Adelanto comisión Cashea · '||v_reason,
       occurred_on=p_period_end,version=version+1,updated_at=now()
       WHERE id=existing.advance_adjustment_id AND payroll_run_id IS NULL
       RETURNING id INTO target_adjustment;
   ELSE
     INSERT INTO public.payroll_adjustments(employee_id,adjustment_type,amount_ref,note,
       occurred_on,decision)
     VALUES(accrual.employee_id,'BONUS',outstanding,
       'Adelanto comisión Cashea · '||v_reason,p_period_end,'PAY')
     RETURNING id INTO target_adjustment;
   END IF;
 ELSE
   target_adjustment:=existing.advance_adjustment_id;
   IF target_adjustment IS NOT NULL THEN
      UPDATE public.payroll_adjustments SET decision='EXCLUDE',
       note='Adelanto Cashea cancelado en borrador · '||v_reason,
       version=version+1,updated_at=now()
       WHERE id=target_adjustment AND payroll_run_id IS NULL;
   END IF;
 END IF;
 INSERT INTO public.cashea_payroll_policies(accrual_id,cashea_sale_id,employee_id,
   mode,advance_adjustment_id,decision_week_end,decision_reason)
 VALUES(p_accrual_id,sale.id,accrual.employee_id,v_mode,target_adjustment,p_period_end,v_reason)
 ON CONFLICT(accrual_id) DO UPDATE SET mode=EXCLUDED.mode,
  advance_adjustment_id=EXCLUDED.advance_adjustment_id,
  decision_week_end=EXCLUDED.decision_week_end,
  decision_reason=EXCLUDED.decision_reason,selected_at=now(),selected_by=auth.uid(),
  version=cashea_payroll_policies.version+1;
 INSERT INTO public.audit_events(event_type,entity_type,entity_id,data)
 VALUES ('payroll.cashea_commission_policy','payroll_accrual',p_accrual_id,jsonb_build_object(
 'mode',v_mode,'commission_full_ref',accrual.amount_ref,'already_collected_commission',already,
 'advance_ref',CASE WHEN v_mode='FULL_UPFRONT' THEN outstanding ELSE 0 END,
 'adjustment_id',target_adjustment,'decision_week_end',p_period_end,
 'reason',v_reason,'actor',auth.uid(),'no_cash_movement',true));
 RETURN jsonb_build_object('ok',true,'mode',v_mode,'full_ref',accrual.amount_ref,
   'collected_ref',already,'advance_ref',CASE WHEN v_mode='FULL_UPFRONT' THEN outstanding ELSE 0 END,
   'adjustment_id',target_adjustment);
END
$function$;

CREATE OR REPLACE FUNCTION public.payroll_record_advance(p_employee_id uuid, p_paid_on date, p_intended_period_end date, p_account_id uuid, p_amount_original numeric, p_reference text, p_note text, p_expected_usd numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.financial_accounts%ROWTYPE; e public.employees%ROWTYPE;
 v_bcv public.exchange_rates%ROWTYPE; v_op public.exchange_rates%ROWTYPE;
 v_usd numeric(18,2);v_ves numeric(18,2);v_movement uuid;v_advance uuid;v_ref text;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 PERFORM pg_advisory_xact_lock(220034);
 IF p_paid_on IS NULL OR p_paid_on>timezone('America/Caracas',now())::date
   OR p_intended_period_end IS NULL OR extract(isodow from p_intended_period_end)<>6
   OR p_paid_on>p_intended_period_end
 THEN RAISE EXCEPTION 'Fecha de pago o semana destino inválida'; END IF;
 IF p_amount_original IS NULL OR p_amount_original<=0
   OR round(p_amount_original,2)<>p_amount_original
   OR p_amount_original::text IN ('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'Indica el monto real entregado en la moneda de la cuenta'; END IF;
 IF length(btrim(coalesce(p_note,'')))<8 THEN RAISE EXCEPTION 'Explica el anticipo y sus trabajos (mínimo 8 caracteres)'; END IF;
 SELECT * INTO e FROM public.employees WHERE id=p_employee_id AND active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Empleado activo no encontrado'; END IF;
 SELECT * INTO a FROM public.financial_accounts
   WHERE id=p_account_id AND active AND currency IN ('VES','USD') AND account_type IN ('BANK','CASH','CLEARING')
     AND code<>'MOBILE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Selecciona la cuenta real desde la que entregaste el dinero'; END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_runs r
    WHERE r.employee_id=e.id AND r.period_end=p_intended_period_end AND r.status='SETTLED')
 THEN RAISE EXCEPTION 'La semana seleccionada ya fue liquidada; no insertes un anticipo después del cierre'; END IF;
 v_ref:=nullif(btrim(p_reference),'');
 IF a.account_type='BANK' AND length(regexp_replace(coalesce(v_ref,''),'\D','','g'))<4
 THEN RAISE EXCEPTION 'El pago bancario debe incluir al menos cuatro dígitos de referencia'; END IF;
 -- Reference collision with any recorded outgoing bank/cash ledger (not just advances).
 IF v_ref IS NOT NULL AND EXISTS(
   SELECT 1 FROM public.account_movements m WHERE m.account_id=a.id AND m.direction='OUT'
   AND m.reference=v_ref AND (m.occurred_at AT TIME ZONE 'America/Caracas')::date
         BETWEEN p_paid_on-interval '1 day' AND p_paid_on+interval '1 day')
 THEN RAISE EXCEPTION 'Ya existe una salida de esta cuenta con esa referencia en una fecha cercana; evita duplicar caja'; END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_advances pa
   WHERE pa.employee_id=e.id AND pa.account_id=a.id AND pa.paid_on=p_paid_on
   AND pa.amount_original=p_amount_original AND pa.reference IS NOT DISTINCT FROM v_ref)
 THEN RAISE EXCEPTION 'Este anticipo ya fue registrado'; END IF;
 SELECT * INTO v_bcv FROM public.exchange_rates
 WHERE rate_type='BCV' AND effective_at<((p_paid_on+1)::timestamp AT TIME ZONE 'America/Caracas')
 ORDER BY effective_at DESC LIMIT 1;
 IF NOT FOUND OR v_bcv.value<=0 THEN RAISE EXCEPTION 'Falta BCV para el día del anticipo'; END IF;
 IF a.currency='VES' THEN
   v_ves:=round(p_amount_original,2);v_usd:=round(v_ves/v_bcv.value,2);
 ELSE
   v_usd:=round(p_amount_original,2);
   SELECT * INTO v_op FROM public.exchange_rates
   WHERE rate_type='OPERATIVE' AND effective_at<((p_paid_on+1)::timestamp AT TIME ZONE 'America/Caracas')
   ORDER BY effective_at DESC LIMIT 1;
   IF NOT FOUND OR v_op.value<=0 THEN RAISE EXCEPTION 'Falta tasa operativa para calcular el equivalente en bolívares'; END IF;
   v_ves:=round(v_usd*v_op.value,2);
 END IF;
 IF v_usd<=0 THEN RAISE EXCEPTION 'Equivalente USD del anticipo inválido'; END IF;
 IF p_expected_usd IS NOT NULL AND abs(v_usd-p_expected_usd)>0.51
 THEN RAISE EXCEPTION 'El importe real corresponde a $%, no a los $% indicados; revisa cuenta y tasa del día',v_usd,p_expected_usd; END IF;
 INSERT INTO public.account_movements(account_id,direction,movement_type,currency,amount_original,
  value_ves,category,payee,note,reference,occurred_at,finance_nature)
 VALUES (a.id,'OUT','EXPENSE',a.currency,round(p_amount_original,2),v_ves,'Nómina',e.name,
  'Anticipo real de nómina · '||btrim(p_note),v_ref,
  (p_paid_on::timestamp+time '12:00') AT TIME ZONE 'America/Caracas','PAYROLL')
 RETURNING id INTO v_movement;
 INSERT INTO public.payroll_advances(employee_id,paid_on,intended_period_end,account_id,account_movement_id,
  currency,amount_original,usd_equivalent,bcv_rate,bcv_effective_at,reference,note)
 VALUES(e.id,p_paid_on,p_intended_period_end,a.id,v_movement,a.currency,round(p_amount_original,2),
   v_usd,v_bcv.value,v_bcv.effective_at,v_ref,btrim(p_note))
 RETURNING id INTO v_advance;
 INSERT INTO public.audit_events(event_type,entity_type,entity_id,data)
 VALUES('payroll.advance_recorded','payroll_advance',v_advance,
    jsonb_build_object('employee_id',e.id,'paid_on',p_paid_on,
      'target_week_end',p_intended_period_end,'amount_original',round(p_amount_original,2),
      'currency',a.currency,'usd_equivalent',v_usd,'account_movement_id',v_movement,
      'account_id',a.id,'reference',v_ref,'note',p_note,'actor',auth.uid()));
 RETURN jsonb_build_object('id',v_advance,'recorded',true,'paid_on',p_paid_on,'usd_equivalent',v_usd,
   'account_code',a.code,'movement_id',v_movement);
END $function$;

CREATE OR REPLACE FUNCTION public.payroll_transfer_decide(p_transfer_id uuid, p_action text, p_evidence text, p_authorization_verified boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_from public.payroll_adjustments%rowtype;v_to public.payroll_adjustments%rowtype;
 v_from_run boolean;v_to_run boolean;
BEGIN
 PERFORM lubricenter_private.require_order_admin();
 PERFORM pg_advisory_xact_lock(hashtextextended(p_transfer_id::text,5419));
 SELECT * INTO v_from FROM public.payroll_adjustments
  WHERE transfer_id=p_transfer_id AND transfer_role='FROM' FOR UPDATE;
 SELECT * INTO v_to FROM public.payroll_adjustments
  WHERE transfer_id=p_transfer_id AND transfer_role='TO' FOR UPDATE;
 IF v_from.id IS NULL OR v_to.id IS NULL THEN RAISE EXCEPTION 'No se encontró la transferencia completa'; END IF;
 IF v_from.payroll_run_id IS NOT NULL OR v_to.payroll_run_id IS NOT NULL THEN
  RAISE EXCEPTION 'Esta reasignación ya está en una liquidación; no se puede cambiar';
 END IF;
 IF v_from.decision<>'HOLD' OR v_to.decision<>'HOLD' THEN
  RAISE EXCEPTION 'La propuesta ya fue tramitada'; END IF;
 IF v_from.amount_ref>=0 OR v_to.amount_ref<=0 OR v_from.amount_ref+v_to.amount_ref<>0 THEN
  RAISE EXCEPTION 'La transferencia debe sumar exactamente cero'; END IF;
 IF p_action NOT IN('APPROVE','REJECT') THEN RAISE EXCEPTION 'Acción inválida'; END IF;
 IF length(btrim(coalesce(p_evidence,'')))<12 OR length(p_evidence)>800 THEN
   RAISE EXCEPTION 'Registra motivo, acuerdo y documentación revisada (mínimo 12 caracteres)'; END IF;
 IF p_action='APPROVE' AND p_authorization_verified IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'No se puede descontar salario sin verificar previamente autorización y legalidad';
 END IF;
 UPDATE public.payroll_adjustments
 SET decision=CASE WHEN p_action='APPROVE' THEN 'PAY' ELSE 'EXCLUDE' END,
     note=note||' · Decisión: '||btrim(p_evidence),
     version=version+1,updated_at=now()
 WHERE transfer_id=p_transfer_id;
 INSERT INTO public.audit_events(event_type,entity_type,entity_id,data)
 VALUES('payroll.transfer_decided','payroll_transfer',p_transfer_id,
   jsonb_build_object('action',p_action,'evidence',btrim(p_evidence),
    'consent_and_legality_verified',p_authorization_verified,'actor',auth.uid(),
    'negative_adjustment_id',v_from.id,'positive_adjustment_id',v_to.id,
    'net_change',v_from.amount_ref+v_to.amount_ref));
END $function$;

CREATE OR REPLACE FUNCTION public.purchasing_dashboard(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_from date:=coalesce(p_from,date_trunc('month',timezone('America/Caracas',now()))::date); v_to date:=coalesce(p_to,timezone('America/Caracas',now())::date); v_result jsonb;
begin
  perform public.require_auth();
  if v_from>v_to or v_to-v_from>366 then raise exception 'Rango de fechas inválido'; end if;
  select jsonb_build_object(
    'period',jsonb_build_object('from',v_from,'to',v_to),
    'summary',jsonb_build_object(
      'invoiced_ref',coalesce((select sum(case when currency='USD' then total_original else total_original/bcv_rate_snapshot end) from public.supplier_invoices where status<>'VOID' and invoice_date between v_from and v_to),0),
      'paid_ves',coalesce((select sum(value_ves) from public.supplier_payments where paid_on between v_from and v_to),0),
      'payable_ref',coalesce((select sum(case when currency='USD' then total_original-paid_original else (total_original-paid_original)/bcv_rate_snapshot end) from public.supplier_invoices where status in ('OPEN','PARTIAL')),0),
      'overdue',coalesce((select count(*) from public.supplier_invoices where status in ('OPEN','PARTIAL') and due_date<timezone('America/Caracas',now())::date),0),
      'suppliers',coalesce((select count(*) from public.suppliers where active),0)
    ),
    'suppliers',coalesce((select jsonb_agg(to_jsonb(x) order by x.name) from (select s.*,count(i.id) invoice_count,coalesce(sum(case when i.status in ('OPEN','PARTIAL') then case when i.currency='USD' then i.total_original-i.paid_original else (i.total_original-i.paid_original)/i.bcv_rate_snapshot end else 0 end),0) payable_ref from public.suppliers s left join public.supplier_invoices i on i.supplier_id=s.id group by s.id) x),'[]'::jsonb),
    'invoices',coalesce((select jsonb_agg(to_jsonb(x) order by x.invoice_date desc,x.created_at desc) from (select i.*,s.name supplier_name,greatest(i.total_original-i.paid_original,0) outstanding_original,coalesce((select sum(si.received_quantity) from public.supplier_invoice_items si where si.supplier_invoice_id=i.id and si.line_type='INVENTORY'),0) received_units,coalesce((select sum(si.quantity) from public.supplier_invoice_items si where si.supplier_invoice_id=i.id and si.line_type='INVENTORY'),0) invoiced_units from public.supplier_invoices i join public.suppliers s on s.id=i.supplier_id where i.invoice_date between v_from and v_to order by i.invoice_date desc limit 200) x),'[]'::jsonb),
    'accounts',coalesce((select jsonb_agg(to_jsonb(a) order by a.account_type,a.name) from public.account_balances_current a where a.active and a.account_type not in ('RELATED','CLEARING')),'[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.queue_post_service_followup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE rec record;v_has_services boolean;
BEGIN
 IF new.status='CLOSED' AND old.status IS DISTINCT FROM 'CLOSED' AND new.customer_id IS NOT NULL THEN
  v_has_services:=false;
  FOR rec IN
   SELECT DISTINCT coalesce(i.service_vehicle_id,new.vehicle_id) vehicle_id
   FROM public.order_items i WHERE i.order_id=new.id AND i.item_type='SERVICE'
      AND coalesce(i.service_vehicle_id,new.vehicle_id) IS NOT NULL
  LOOP
   v_has_services:=true;
   PERFORM lubricenter_private.upsert_vehicle_crm(new.id,rec.vehicle_id,false);
  END LOOP;
  -- Legacy product-only orders still receive one generic message.
  IF NOT v_has_services THEN
   INSERT INTO public.customer_followups(
    order_id,customer_id,vehicle_id,followup_type,channel,status,message,sent_at
   ) VALUES(new.id,new.customer_id,new.vehicle_id,'POST_SERVICE','WHATSAPP',
    'PENDING',public.build_post_service_message(new.id),null)
   ON CONFLICT(order_id,followup_type,vehicle_id) WHERE vehicle_id IS NOT NULL
   DO NOTHING;
  END IF;
 END IF;
 RETURN new;
END $function$;

CREATE OR REPLACE FUNCTION public.quick_sale_partial_credit(p_items jsonb, p_customer_id uuid, p_method text, p_amount_original numeric, p_reference text DEFAULT NULL::text, p_due_date date DEFAULT NULL::date, p_business_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sale record;
  v_credit record;
begin
  perform public.require_auth();
  if p_customer_id is null or not exists(select 1 from public.customers where id = p_customer_id) then
    raise exception 'Selecciona un cliente para dejar el saldo en Crédito LC';
  end if;

  perform set_config('lubricenter.business_at', coalesce(p_business_at::text, ''), true);
  select * into v_sale from public.build_quick_sale_order(p_items);
  perform public.set_order_party(v_sale.order_id, p_customer_id, null);
  select * into v_credit from public.close_order_with_partial_credit(
    v_sale.order_id, p_method, p_amount_original, p_reference, p_due_date
  );

  return jsonb_build_object(
    'order_id', v_sale.order_id,
    'order_number', v_credit.order_number,
    'total_ves', v_credit.total_ves,
    'total_ref', v_credit.total_ref,
    'payment_id', v_credit.payment_id,
    'receivable_id', v_credit.receivable_id,
    'outstanding_ves', v_credit.outstanding_ves,
    'outstanding_ref', v_credit.outstanding_ref
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.quick_sale_with_tender(p_request uuid, p_items jsonb, p_method text, p_received numeric, p_return_usd numeric, p_return_currency text, p_change_rate numeric, p_reference text DEFAULT NULL::text, p_customer_label text DEFAULT NULL::text, p_business_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_agreed_usd numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; previous public.quick_tender_requests; sale record; item public.order_items; op numeric; b numeric; weight numeric; allocated numeric:=0; part numeric; n integer:=0; count_items integer; result jsonb;
begin
 perform lubricenter_private.finance_require('OPERATOR');
 if p_request is null then raise exception 'Falta el identificador de la venta'; end if;
 payload:=jsonb_build_array(p_items,p_method,p_received,p_return_usd,p_return_currency,p_change_rate,p_reference,p_customer_label,p_business_at,p_agreed_usd);
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,1));
 select * into previous from public.quick_tender_requests where id=p_request;
 if found then
  if previous.payload<>payload then raise exception 'Solicitud reutilizada con otros datos'; end if;
  return previous.result;
 end if;
 if p_agreed_usd is not null and (p_agreed_usd<=0 or p_agreed_usd::text in ('NaN','Infinity','-Infinity') or round(p_agreed_usd,2)<>p_agreed_usd) then raise exception 'Total pactado USD inválido'; end if;
 perform set_config('lubricenter.business_at',coalesce(p_business_at::text,''),true);
 select * into sale from public.build_quick_sale_order(p_items);
 if p_agreed_usd is not null then
  select bcv_rate,operative_rate into b,op from public.get_order_rates(sale.order_id);
  if b is null or b<=0 or op is null or op<=0 then raise exception 'Faltan tasas válidas'; end if;
  select sum(charged_ref_amount),count(*) into weight,count_items from public.order_items where order_id=sale.order_id;
  for item in select * from public.order_items where order_id=sale.order_id order by id loop
   n:=n+1;
   part:=case when n=count_items then p_agreed_usd-allocated else round(p_agreed_usd*item.charged_ref_amount/weight,4) end;
   allocated:=allocated+part;
   update public.order_items set price_denomination='USD',agreed_usd=part,charged_ves_amount=round(part*op,2),charged_ref_amount=round(part*op/b,4),customer_ref_amount=round(part*op/b,4) where id=item.id;
  end loop;
 end if;
 perform lubricenter_private.collect_order_tender(p_request,sale.order_id,p_method,p_received,p_return_usd,p_return_currency,p_change_rate,p_reference,p_customer_label);
 perform public.close_order(sale.order_id);
 select jsonb_build_object('order_id',id,'order_number',order_number,'total_ves',total_ves,'total_ref',total_ref) into result from public.orders where id=sale.order_id;
 insert into public.quick_tender_requests values(p_request,payload,result,now());
 return result;
end $function$;

CREATE OR REPLACE FUNCTION public.reassign_vehicle_customer(p_vehicle_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_previous uuid;
  v_reason text := nullif(trim(p_reason), '');
begin
  perform public.require_auth();
  if v_reason is null or length(v_reason) < 3 then
    raise exception 'Indica el motivo del cambio';
  end if;

  select customer_id into v_previous from public.vehicles where id = p_vehicle_id for update;
  if not found then raise exception 'Vehículo no encontrado'; end if;
  if p_customer_id is not null and not exists(select 1 from public.customers where id = p_customer_id) then
    raise exception 'Cliente no encontrado';
  end if;
  if v_previous is not distinct from p_customer_id then
    raise exception 'El vehículo ya tiene esa asociación';
  end if;

  update public.vehicles set customer_id = p_customer_id where id = p_vehicle_id;

  if v_previous is not null then
    update public.vehicle_customer_history
    set last_seen_at = now()
    where vehicle_id = p_vehicle_id and customer_id = v_previous and source_system = 'LUBRICENTER_OS';
  end if;
  if p_customer_id is not null then
    insert into public.vehicle_customer_history(vehicle_id, customer_id, source_system, first_seen_at, last_seen_at)
    values (p_vehicle_id, p_customer_id, 'LUBRICENTER_OS', now(), now())
    on conflict (vehicle_id, customer_id, source_system)
    do update set last_seen_at = excluded.last_seen_at;
  end if;

  insert into public.audit_events(event_type, entity_type, entity_id, data)
  values (
    case when p_customer_id is null then 'vehicle.customer_unlinked' else 'vehicle.customer_reassigned' end,
    'vehicle', p_vehicle_id,
    jsonb_build_object('previous_customer_id', v_previous, 'customer_id', p_customer_id, 'reason', v_reason)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.receive_supplier_invoice(p_invoice_id uuid, p_received_on date, p_items jsonb DEFAULT NULL::jsonb, p_location_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_invoice public.supplier_invoices; v_receipt uuid; v_location uuid; v_line public.supplier_invoice_items; v_payload jsonb; v_qty numeric; v_old_qty numeric; v_old_cost numeric; v_new_cost numeric; v_receipt_item uuid; v_count integer:=0;
begin
  perform public.require_auth();
  select * into v_invoice from public.supplier_invoices where id=p_invoice_id for update;
  if not found or v_invoice.status='VOID' then raise exception 'Factura de proveedor no disponible'; end if;
  if p_received_on is null or p_received_on>timezone('America/Caracas',now())::date then raise exception 'Fecha de recepción inválida'; end if;
  if p_location_id is null then select id into v_location from public.locations where active order by created_at limit 1; else v_location:=p_location_id; end if;
  if not exists(select 1 from public.locations where id=v_location and active) then raise exception 'Ubicación no disponible'; end if;
  insert into public.supplier_receipts(supplier_invoice_id,location_id,received_on,notes) values(p_invoice_id,v_location,p_received_on,nullif(trim(p_notes),'')) returning id into v_receipt;
  for v_line in select * from public.supplier_invoice_items where supplier_invoice_id=p_invoice_id and line_type='INVENTORY' order by created_at loop
    if p_items is null then v_qty:=v_line.quantity-v_line.received_quantity;
    else select value into v_payload from jsonb_array_elements(p_items) where value->>'line_id'=v_line.id::text limit 1; v_qty:=coalesce((v_payload->>'quantity')::numeric,0); end if;
    if v_qty<=0 then continue; end if;
    if v_line.received_quantity+v_qty>v_line.quantity then raise exception 'La recepción supera la cantidad facturada para %',v_line.description; end if;
    select coalesce(sum(quantity_delta),0) into v_old_qty from public.inventory_movements where inventory_item_id=v_line.inventory_item_id;
    select average_cost_ref into v_old_cost from public.inventory_items where id=v_line.inventory_item_id for update;
    v_new_cost:=case when v_old_qty>0 then round((v_old_qty*v_old_cost+v_qty*v_line.unit_cost_ref)/(v_old_qty+v_qty),4) else v_line.unit_cost_ref end;
    update public.inventory_items set average_cost_ref=v_new_cost,last_purchase_cost_ref=v_line.unit_cost_ref,last_purchased_at=((p_received_on::timestamp+time '12:00') at time zone 'America/Caracas'),updated_at=now() where id=v_line.inventory_item_id;
    insert into public.supplier_receipt_items(supplier_receipt_id,supplier_invoice_item_id,inventory_item_id,quantity,unit_cost_ref) values(v_receipt,v_line.id,v_line.inventory_item_id,v_qty,v_line.unit_cost_ref) returning id into v_receipt_item;
    insert into public.inventory_movements(inventory_item_id,location_id,quantity_delta,movement_type,note,occurred_at,supplier_receipt_item_id) values(v_line.inventory_item_id,v_location,v_qty,'PURCHASE','Recepción factura '||v_invoice.invoice_number,((p_received_on::timestamp+time '12:00') at time zone 'America/Caracas'),v_receipt_item);
    update public.supplier_invoice_items set received_quantity=received_quantity+v_qty where id=v_line.id;
    v_count:=v_count+1;
  end loop;
  if v_count=0 then delete from public.supplier_receipts where id=v_receipt; raise exception 'No hay cantidades pendientes para recibir'; end if;
  insert into public.audit_events(event_type,entity_type,entity_id,data) values('supplier_receipt.posted','supplier_receipt',v_receipt,jsonb_build_object('invoice_id',p_invoice_id,'received_on',p_received_on,'lines',v_count));
  return v_receipt;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reclassify_order_item(p_order_item_id uuid, p_role text, p_cost_ref numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.order_items; v_role text := upper(nullif(trim(coalesce(p_role, '')), ''));
begin
  perform public.require_auth();
  if not coalesce(public.can_administer_orders(), false) then raise exception 'Solo el dueño puede reclasificar'; end if;
  select * into i from public.order_items where id = p_order_item_id for update;
  if not found then raise exception 'Línea no encontrada'; end if;
  if v_role is not null and v_role not in ('PRODUCT','PASS_THROUGH','CASHEA_SURCHARGE','OIL_LABOR','LABOR') then
    raise exception 'Rol inválido';
  end if;
  if v_role = 'PASS_THROUGH' and (p_cost_ref is null or p_cost_ref < 0 or p_cost_ref > i.charged_ref_amount + 0.01) then
    raise exception 'Indica lo que pagaste (entre 0 y % REF)', round(i.charged_ref_amount, 2);
  end if;
  update public.order_items
  set line_role = v_role,
      pass_through_cost_ref = case when v_role = 'PASS_THROUGH' then round(p_cost_ref, 4) else null end
  where id = p_order_item_id;
  insert into public.audit_events(event_type, entity_type, entity_id, data)
  values ('order_item.reclassified', 'order_item', p_order_item_id, jsonb_build_object(
    'order_id', i.order_id, 'from', i.line_role, 'to', v_role, 'cost_ref', p_cost_ref));
end $function$;

CREATE OR REPLACE FUNCTION public.record_account_expense(p_account_id uuid, p_amount numeric, p_category text, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account public.financial_accounts;
  v_op numeric;
  v_value_ves numeric;
  v_id uuid;
begin
  perform public.require_auth();
  select * into v_account from public.financial_accounts where id=p_account_id and active=true;
  if not found then raise exception 'Cuenta no encontrada'; end if;
  if p_amount <= 0 then raise exception 'Monto inválido'; end if;
  if coalesce(trim(p_category),'')='' then raise exception 'Categoría requerida'; end if;
  select operative_rate into v_op from public.current_exchange_rates;
  v_value_ves := case when v_account.currency='USD' then p_amount*v_op else p_amount end;
  insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,note,reference,occurred_at)
  values(p_account_id,'OUT','EXPENSE',v_account.currency,p_amount,round(v_value_ves,2),trim(p_category),nullif(trim(p_note),''),nullif(trim(p_reference),''),now())
  returning id into v_id;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('cash.expense_recorded','account_movement',v_id,jsonb_build_object('account_id',p_account_id,'amount',p_amount,'currency',v_account.currency,'category',p_category));
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_account_expense_v2(p_account_id uuid, p_amount numeric, p_category text, p_payee text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_occurred_on date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account public.financial_accounts;
  v_day date := coalesce(p_occurred_on, timezone('America/Caracas',now())::date);
  v_op numeric;
  v_value_ves numeric;
  v_id uuid;
  v_occurred_at timestamptz;
begin
  perform public.require_auth();
  select * into v_account from public.financial_accounts where id=p_account_id and active=true;
  if not found then raise exception 'Cuenta no encontrada'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Monto inválido'; end if;
  if coalesce(trim(p_category),'')='' then raise exception 'Categoría requerida'; end if;
  if v_day > timezone('America/Caracas',now())::date then raise exception 'La fecha del gasto no puede ser futura'; end if;
  if v_day < timezone('America/Caracas',now())::date - 1825 then raise exception 'La fecha del gasto es demasiado antigua'; end if;

  select value into v_op from public.exchange_rates
  where rate_type='OPERATIVE' and timezone('America/Caracas',effective_at)::date <= v_day
  order by effective_at desc limit 1;
  if v_op is null then select operative_rate into v_op from public.current_exchange_rates; end if;
  v_value_ves := case when v_account.currency='USD' then p_amount*v_op else p_amount end;
  v_occurred_at := ((v_day::timestamp + time '12:00') at time zone 'America/Caracas');

  insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,payee,note,reference,occurred_at)
  values(p_account_id,'OUT','EXPENSE',v_account.currency,p_amount,round(v_value_ves,2),trim(p_category),nullif(trim(p_payee),''),nullif(trim(p_note),''),nullif(trim(p_reference),''),v_occurred_at)
  returning id into v_id;

  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('cash.expense_recorded','account_movement',v_id,jsonb_build_object(
    'account_id',p_account_id,'amount',p_amount,'currency',v_account.currency,
    'category',trim(p_category),'payee',nullif(trim(p_payee),''),'occurred_on',v_day
  ));
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_cashea_installment_payment(p_installment_id uuid, p_method text, p_amount_original numeric, p_reference text DEFAULT NULL::text)
 RETURNS TABLE(payment_id uuid, installment_status text, remaining_sale_ref numeric, sale_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inst public.cashea_installments;
  v_sale public.cashea_sales;
  v_bcv numeric; v_op numeric; v_method text := upper(coalesce(p_method,''));
  v_currency text; v_value_ves numeric; v_value_ref numeric; v_remaining_inst_ref numeric; v_applied_ref numeric;
  v_payment_id uuid; v_remaining_ref numeric; v_inst_status text; v_sale_status text;
begin
  perform public.require_auth();
  select * into v_inst from public.cashea_installments where id=p_installment_id for update;
  if v_inst.id is null then raise exception 'Cuota Cashea no encontrada'; end if;
  if v_inst.status='PAID' then raise exception 'Esta cuota Cashea ya está pagada'; end if;
  select * into v_sale from public.cashea_sales where id=v_inst.cashea_sale_id for update;
  if v_sale.status<>'ACTIVE' then raise exception 'La venta Cashea no está activa'; end if;
  if v_method not in ('CASH_USD','CASH_VES','MOBILE_PAYMENT','TRANSFER_BDV','TRANSFER_BNC') then raise exception 'Método de pago inválido'; end if;
  if p_amount_original is null or p_amount_original<=0 then raise exception 'Monto inválido'; end if;
  select bcv_rate,operative_rate into v_bcv,v_op from public.current_exchange_rates;
  if v_bcv is null or v_bcv<=0 or v_op is null or v_op<=0 then raise exception 'Debes registrar tasas antes de cobrar'; end if;

  v_currency := case when v_method='CASH_USD' then 'USD' else 'VES' end;
  if v_currency='USD' then
    v_value_ref := p_amount_original;
    v_value_ves := round(p_amount_original*v_bcv,2);
  else
    v_value_ves := p_amount_original;
    v_value_ref := round(p_amount_original/v_bcv,4);
  end if;
  v_remaining_inst_ref := greatest(v_inst.amount_ref-v_inst.paid_ref,0);
  if v_value_ref > v_remaining_inst_ref + 0.05 then raise exception 'El pago excede esta cuota Cashea por REF %', round(v_value_ref-v_remaining_inst_ref,2); end if;
  v_applied_ref := least(v_value_ref,v_remaining_inst_ref);

  insert into public.payments(order_id,receivable_id,method,currency,amount_original,bcv_rate_snapshot,operative_rate_snapshot,value_ves,value_ref,reference,paid_at)
  values(v_sale.order_id,null,v_method,v_currency,p_amount_original,v_bcv,v_op,round(v_value_ves,2),round(v_value_ref,4),nullif(trim(p_reference),''),now())
  returning id into v_payment_id;

  v_inst_status := case when v_inst.paid_ref+v_applied_ref >= v_inst.amount_ref-0.05 then 'PAID' else 'PARTIAL' end;
  update public.cashea_installments
  set paid_ref=case when v_inst_status='PAID' then amount_ref else round(paid_ref+v_applied_ref,4) end,
      paid_ves_actual=round(paid_ves_actual+v_value_ves,2),status=v_inst_status,
      paid_at=case when v_inst_status='PAID' then now() else paid_at end,updated_at=now()
  where id=p_installment_id;

  select coalesce(sum(greatest(amount_ref-paid_ref,0)),0) into v_remaining_ref
  from public.cashea_installments where cashea_sale_id=v_sale.id;
  v_sale_status := case when v_remaining_ref<=0.05 then 'SETTLED' else 'ACTIVE' end;
  update public.cashea_sales set status=v_sale_status,settled_at=case when v_sale_status='SETTLED' then now() else null end where id=v_sale.id;

  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('cashea.installment_payment_recorded','cashea_installment',p_installment_id,
    jsonb_build_object('payment_id',v_payment_id,'method',v_method,'value_ref',v_value_ref,'remaining_sale_ref',v_remaining_ref,'installment_status',v_inst_status,'sale_status',v_sale_status));

  payment_id:=v_payment_id; installment_status:=v_inst_status; remaining_sale_ref:=round(v_remaining_ref,4); sale_status:=v_sale_status;
  return next;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_crm_maintenance_activity(p_service_record_id uuid, p_event_type text, p_stage text DEFAULT NULL::text, p_message_text text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_permission text;
  v_latest uuid;
  v_count int;
  v_last timestamptz;
  v_last_customer timestamptz;
  v_stage text;
  v_days int;
  v_id uuid;
  v_today date := (now() AT TIME ZONE 'America/Caracas')::date;
BEGIN
  PERFORM public.require_auth();
  IF p_event_type NOT IN
    ('SENT','REPLIED','BOOKED','DECLINED','CLOSED_NO_REPLY','REACTIVATED') THEN
    RAISE EXCEPTION 'Acción CRM no válida';
  END IF;
  IF length(coalesce(p_message_text,''))>1800 OR length(coalesce(p_notes,''))>500 THEN
    RAISE EXCEPTION 'Mensaje o nota demasiado extensa';
  END IF;
  SELECT * INTO r FROM public.maintenance_reminders_current
    WHERE service_record_id=p_service_record_id;
  IF NOT FOUND OR r.customer_id IS NULL THEN
    RAISE EXCEPTION 'El servicio ya no es el último cambio del vehículo actual';
  END IF;
  -- Serializa los envíos de distintos carros a una misma persona.
  PERFORM pg_advisory_xact_lock(hashtextextended(r.customer_id::text, 0));
  SELECT status INTO v_permission FROM public.crm_contact_permissions
    WHERE customer_id=r.customer_id;
  SELECT sr.id INTO v_latest
    FROM public.service_records sr
    WHERE sr.vehicle_id=r.vehicle_id AND sr.service_type='OIL_CHANGE'
      AND sr.customer_id=r.customer_id
      AND NOT EXISTS (
        SELECT 1 FROM public.orders o WHERE o.id=sr.order_id AND o.status='CANCELLED'
      )
    ORDER BY sr.performed_at DESC,sr.created_at DESC,sr.id DESC LIMIT 1;
  IF v_latest IS DISTINCT FROM p_service_record_id THEN
    RAISE EXCEPTION 'El cliente ya tiene un cambio de aceite más reciente';
  END IF;

  IF p_event_type='REACTIVATED' THEN
    IF v_permission IS DISTINCT FROM 'OPT_IN' THEN
      RAISE EXCEPTION 'Debes comprobar la autorización de contacto antes de reactivar';
    END IF;
    IF r.reminder_status<>'SENT' OR EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id
         AND event_type IN ('REACTIVATED','SENT')
    ) THEN
      RAISE EXCEPTION 'Este registro no es un archivo histórico reactivable';
    END IF;
    PERFORM public.set_maintenance_reminder_status(p_service_record_id,'PENDING',NULL);
  ELSIF p_event_type='SENT' THEN
    IF v_permission IS DISTINCT FROM 'OPT_IN' THEN
      RAISE EXCEPTION 'No se puede contactar por WhatsApp sin autorización comprobada';
    END IF;
    IF length(btrim(coalesce(p_message_text,'')))<25 THEN
      RAISE EXCEPTION 'Guarda el texto real del mensaje antes de marcarlo enviado';
    END IF;
    IF p_stage NOT IN ('PREVENTIVE','DUE','LATE','RECOVERY','WINBACK') THEN
      RAISE EXCEPTION 'Selecciona la etapa real de seguimiento';
    END IF;
    v_days := v_today-r.next_service_date;
    v_stage := CASE
      WHEN v_days < -14 THEN 'NOT_READY'
      WHEN v_days < -4 THEN 'PREVENTIVE'
      WHEN v_days <= 7 THEN 'DUE'
      WHEN v_days <= 30 THEN 'LATE'
      WHEN v_days <= 90 THEN 'RECOVERY'
      ELSE 'WINBACK'
    END;
    IF p_stage<>v_stage THEN
      RAISE EXCEPTION 'La etapa cambió; actualiza el recordatorio antes de registrar el envío';
    END IF;
    IF r.reminder_status='SNOOZED' AND r.snoozed_until > v_today THEN
      RAISE EXCEPTION 'El contacto está pospuesto';
    END IF;
    IF r.reminder_status='SENT' AND NOT EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id AND event_type='SENT'
    ) AND NOT EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id AND event_type='REACTIVATED'
    ) THEN
      RAISE EXCEPTION 'El historial antiguo debe revisarse y reactivarse de forma explícita';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id AND event_type IN
          ('BOOKED','REPLIED','DECLINED','CLOSED_NO_REPLY')
    ) THEN
      RAISE EXCEPTION 'El cliente ya respondió o se cerró el seguimiento';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id AND event_type='SENT' AND stage=p_stage
    ) THEN
      RAISE EXCEPTION 'Ya se envió un mensaje durante esta misma etapa';
    END IF;
    SELECT count(*)::int,max(recorded_at) INTO v_count,v_last
      FROM public.crm_maintenance_events
      WHERE service_record_id=p_service_record_id AND event_type='SENT';
    IF v_count>=3 THEN
      RAISE EXCEPTION 'El máximo es de tres contactos por ciclo de mantenimiento';
    END IF;
    IF v_last IS NOT NULL AND v_last > now()-interval '10 days' THEN
      RAISE EXCEPTION 'Espera al menos diez días desde el contacto anterior';
    END IF;
    SELECT max(recorded_at) INTO v_last_customer
      FROM public.crm_maintenance_events
      WHERE customer_id=r.customer_id AND event_type='SENT';
    IF v_last_customer IS NOT NULL AND v_last_customer>now()-interval '14 days' THEN
      RAISE EXCEPTION 'Este cliente recibió otro recordatorio en los últimos catorce días';
    END IF;
  ELSE
    -- Las respuestas se registran aunque el consentimiento se haya retirado posteriormente.
    IF NOT EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id AND event_type='SENT'
    ) THEN
      RAISE EXCEPTION 'Todavía no hay un contacto confirmado para este mantenimiento';
    END IF;
    IF p_event_type IN ('REPLIED','BOOKED') AND EXISTS (
      SELECT 1 FROM public.crm_maintenance_events
       WHERE service_record_id=p_service_record_id AND event_type=p_event_type
    ) THEN
      RAISE EXCEPTION 'Esta respuesta ya fue registrada';
    END IF;
  END IF;

  INSERT INTO public.crm_maintenance_events
    (service_record_id,vehicle_id,customer_id,event_type,stage,
     message_text,notes,recorded_by)
  VALUES (p_service_record_id,r.vehicle_id,r.customer_id,p_event_type,
    CASE WHEN p_event_type='SENT' THEN p_stage ELSE NULL END,
    CASE WHEN p_event_type='SENT' THEN btrim(p_message_text) ELSE NULL END,
    nullif(btrim(coalesce(p_notes,'')),''),auth.uid())
  RETURNING id INTO v_id;
  IF p_event_type='SENT' THEN
    PERFORM public.set_maintenance_reminder_status(p_service_record_id,'SENT',NULL);
  END IF;
  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_customer_balance_deposit(p_customer_id uuid, p_method text, p_amount_original numeric, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_method text := upper(coalesce(p_method,''));
  v_pocket text; v_currency text; v_account_code text; v_account_id uuid;
  v_bcv numeric; v_op numeric; v_units numeric(18,2); v_value_ves numeric(20,2);
  v_movement_id uuid; v_entry_id uuid; v_existing public.customer_balance_movements;
begin
  perform public.require_auth();
  if p_request_id is null then raise exception 'Falta el identificador de esta operación'; end if;
  select * into v_existing from public.customer_balance_movements where request_id=p_request_id;
  if found then
    if v_existing.movement_type='DEPOSIT' and v_existing.customer_id=p_customer_id
       and v_existing.method=v_method and v_existing.amount_original=p_amount_original then return v_existing.id; end if;
    raise exception 'Este identificador ya corresponde a otra operación';
  end if;
  if not exists(select 1 from public.customers where id=p_customer_id) then raise exception 'Cliente no encontrado'; end if;
  if p_amount_original is null or p_amount_original::text in ('NaN','Infinity','-Infinity')
     or p_amount_original<=0 or round(p_amount_original,2)<>p_amount_original then
    raise exception 'Indica un monto positivo con máximo dos decimales';
  end if;
  v_account_code := case v_method
    when 'CASH_USD' then 'CASH_USD' when 'CASH_VES' then 'CASH_VES'
    when 'TRANSFER_BDV' then 'BDV' when 'TRANSFER_BNC' then 'BNC'
    when 'ZELLE' then 'ZELLE' when 'BINANCE' then 'BINANCE' else null end;
  if v_account_code is null then raise exception 'Método de ingreso inválido'; end if;
  if v_method in ('TRANSFER_BDV','TRANSFER_BNC')
     and coalesce(trim(p_reference),'') !~ '^[0-9]{4}$' then
    raise exception 'Escribe los últimos 4 dígitos de referencia del pago móvil';
  end if;
  select id into v_account_id from public.financial_accounts
    where code=v_account_code and active=true;
  if v_account_id is null then raise exception 'Cuenta financiera % no disponible',v_account_code; end if;
  select bcv_rate,operative_rate into v_bcv,v_op from public.current_exchange_rates;
  if v_bcv is null or v_bcv<=0 or v_op is null or v_op<=0 then
    raise exception 'Debes tener tasas BCV y operativa vigentes antes de registrar el saldo';
  end if;
  v_pocket := case when v_method in ('CASH_USD','ZELLE','BINANCE') then 'USD' else 'VES_BCV' end;
  v_currency := case when v_pocket='USD' then 'USD' else 'VES' end;
  v_units := case when v_pocket='USD' then p_amount_original else round(p_amount_original/v_bcv,2) end;
  if v_units<=0 then raise exception 'El importe es menor a un centavo de saldo a favor'; end if;
  v_value_ves := case when v_pocket='USD' then round(p_amount_original*v_op,2) else p_amount_original end;
  insert into public.account_movements(
    account_id,direction,movement_type,currency,amount_original,value_ves,
    category,note,reference,occurred_at,created_by
  ) values (
    v_account_id,'IN','ADJUSTMENT',v_currency,p_amount_original,v_value_ves,
    'CUSTOMER_BALANCE_DEPOSIT','Anticipo de cliente · '||coalesce(nullif(trim(p_note),''),'saldo a favor'),
    nullif(trim(p_reference),''),now(),auth.uid()
  ) returning id into v_movement_id;
  insert into public.customer_balance_accounts(customer_id,pocket)
    values(p_customer_id,v_pocket) on conflict do nothing;
  perform 1 from public.customer_balance_accounts
    where customer_id=p_customer_id and pocket=v_pocket for update;
  update public.customer_balance_accounts set balance_usd=balance_usd+v_units,updated_at=now()
    where customer_id=p_customer_id and pocket=v_pocket;
  insert into public.customer_balance_movements(
    customer_id,pocket,movement_type,delta_usd,amount_original,currency,value_ves,
    bcv_rate_snapshot,operative_rate_snapshot,method,reference,note,account_movement_id,request_id
  ) values (
    p_customer_id,v_pocket,'DEPOSIT',v_units,p_amount_original,v_currency,v_value_ves,
    v_bcv,v_op,v_method,nullif(trim(p_reference),''),coalesce(nullif(trim(p_note),''),'Anticipo de cliente'),
    v_movement_id,p_request_id
  ) returning id into v_entry_id;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('customer_balance.deposit','customer_balance_movement',v_entry_id,
    jsonb_build_object('customer_id',p_customer_id,'pocket',v_pocket,'amount_original',p_amount_original,
      'currency',v_currency,'units_usd',v_units,'bcv_rate',v_bcv,'account_movement_id',v_movement_id));
  return v_entry_id;
end $function$;

CREATE OR REPLACE FUNCTION public.record_internal_transfer(p_from_account_id uuid, p_to_account_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_from public.financial_accounts;
  v_to public.financial_accounts;
  v_op numeric;
  v_value_ves numeric;
  v_group uuid := gen_random_uuid();
begin
  perform public.require_auth();
  if p_from_account_id=p_to_account_id then raise exception 'Las cuentas deben ser distintas'; end if;
  if p_amount <= 0 then raise exception 'Monto inválido'; end if;
  select * into v_from from public.financial_accounts where id=p_from_account_id and active=true;
  select * into v_to from public.financial_accounts where id=p_to_account_id and active=true;
  if v_from.id is null or v_to.id is null then raise exception 'Cuenta no encontrada'; end if;
  if v_from.currency<>v_to.currency then raise exception 'En esta versión las transferencias internas deben usar la misma moneda'; end if;
  select operative_rate into v_op from public.current_exchange_rates;
  v_value_ves := case when v_from.currency='USD' then p_amount*v_op else p_amount end;
  insert into public.account_movements(account_id,direction,movement_type,transfer_group,currency,amount_original,value_ves,note,reference,occurred_at)
  values
    (p_from_account_id,'OUT','TRANSFER',v_group,v_from.currency,p_amount,round(v_value_ves,2),nullif(trim(p_note),''),nullif(trim(p_reference),''),now()),
    (p_to_account_id,'IN','TRANSFER',v_group,v_to.currency,p_amount,round(v_value_ves,2),nullif(trim(p_note),''),nullif(trim(p_reference),''),now());
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('cash.internal_transfer','transfer',v_group,jsonb_build_object('from_account_id',p_from_account_id,'to_account_id',p_to_account_id,'amount',p_amount,'currency',v_from.currency));
  return v_group;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_receivable_payment(p_receivable_id uuid, p_method text, p_amount_original numeric, p_reference text DEFAULT NULL::text)
 RETURNS TABLE(payment_id uuid, status text, outstanding_fraction numeric, remaining_ref numeric, remaining_usd numeric, remaining_ves_today numeric, outstanding_ves numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_r public.receivables;
  v_method text := upper(coalesce(p_method, ''));
  v_currency text;
  v_bcv numeric;
  v_order_usd numeric;
  v_rem_ref numeric;
  v_rem_usd numeric;
  v_rem_pay numeric;
  v_share numeric;
  v_new_fraction numeric;
  v_value_ves numeric;
  v_payment_id uuid;
  v_status text;
begin
  perform public.require_auth();

  select * into v_r from public.receivables where id = p_receivable_id for update;
  if not found then raise exception 'Cuenta por cobrar no encontrada'; end if;
  if v_r.status <> 'OPEN' then raise exception 'La cuenta por cobrar no está abierta'; end if;

  if v_method not in ('CASH_USD','CASH_VES','MOBILE_PAYMENT','TRANSFER_BDV','TRANSFER_BNC','ZELLE','BINANCE') then
    raise exception 'Método de pago inválido';
  end if;
  if p_amount_original is null or p_amount_original::text in ('NaN','Infinity','-Infinity')
     or p_amount_original <= 0 or round(p_amount_original, 2) <> p_amount_original then
    raise exception 'Indica un monto positivo con máximo dos decimales';
  end if;

  select bcv_rate into v_bcv from public.current_exchange_rates;
  if v_bcv is null or v_bcv <= 0 then raise exception 'Debes registrar la tasa BCV antes de cobrar'; end if;
  v_order_usd := public.order_usd_rate(v_r.order_id);
  if v_r.principal_usd is null or v_r.principal_usd <= 0 then
    raise exception 'La deuda no tiene monto en $ divisas; revisa la orden';
  end if;

  v_currency := case when v_method in ('CASH_USD','ZELLE','BINANCE') then 'USD' else 'VES' end;
  v_rem_ref := v_r.outstanding_fraction * v_r.principal_ref;
  v_rem_usd := v_r.outstanding_fraction * v_r.principal_usd;
  v_rem_pay := case when v_currency = 'USD' then round(v_rem_usd, 2) else round(v_rem_ref * v_bcv, 2) end;

  if p_amount_original > v_rem_pay + 0.01 then
    raise exception 'El abono excede lo que falta. Falta % % (o % REF)',
      case when v_currency = 'USD' then '$' else 'Bs' end, v_rem_pay, round(v_rem_ref, 2);
  end if;

  v_share := case when v_currency = 'USD'
    then p_amount_original / v_r.principal_usd
    else (p_amount_original / v_bcv) / v_r.principal_ref end;
  v_new_fraction := greatest(v_r.outstanding_fraction - v_share, 0);
  if p_amount_original >= v_rem_pay - 0.01
     or (case when v_currency = 'USD' then v_new_fraction * v_r.principal_usd
              else v_new_fraction * v_r.principal_ref * v_bcv end) < 0.01 then
    v_new_fraction := 0;
  end if;
  v_status := case when v_new_fraction = 0 then 'PAID' else 'OPEN' end;

  v_value_ves := case when v_currency = 'USD' then p_amount_original * v_order_usd else p_amount_original end;

  insert into public.payments(
    order_id, receivable_id, method, currency, amount_original,
    bcv_rate_snapshot, operative_rate_snapshot, value_ves, value_ref,
    applied_ref, applied_usd, reference, paid_at
  ) values (
    v_r.order_id, p_receivable_id, v_method, v_currency, p_amount_original,
    v_bcv, v_order_usd, round(v_value_ves, 2), round(v_value_ves / v_bcv, 4),
    round((v_r.outstanding_fraction - v_new_fraction) * v_r.principal_ref, 4),
    round((v_r.outstanding_fraction - v_new_fraction) * v_r.principal_usd, 2),
    nullif(trim(p_reference), ''), now()
  ) returning id into v_payment_id;

  update public.receivables
  set outstanding_fraction = v_new_fraction,
      outstanding_ves = round(v_new_fraction * principal_ves, 2),
      status = v_status,
      closed_at = case when v_status = 'PAID' then now() else null end
  where id = p_receivable_id;

  insert into public.integration_events(event_type, aggregate_type, aggregate_id, payload)
  values (
    case when v_status = 'PAID' then 'receivable.paid' else 'receivable.payment_recorded' end,
    'receivable', p_receivable_id,
    jsonb_build_object('order_id', v_r.order_id, 'payment_id', v_payment_id, 'method', v_method,
      'currency', v_currency, 'amount_original', p_amount_original,
      'outstanding_fraction', v_new_fraction, 'status', v_status));
  insert into public.audit_events(event_type, entity_type, entity_id, data)
  values ('receivable.payment_recorded', 'receivable', p_receivable_id,
    jsonb_build_object('payment_id', v_payment_id, 'method', v_method, 'currency', v_currency,
      'amount_original', p_amount_original, 'bcv', v_bcv,
      'fraction_before', v_r.outstanding_fraction, 'fraction_after', v_new_fraction,
      'status', v_status));

  return query select
    v_payment_id, v_status, v_new_fraction,
    round(v_new_fraction * v_r.principal_ref, 4),
    round(v_new_fraction * v_r.principal_usd, 2),
    round(v_new_fraction * v_r.principal_ref * v_bcv, 2),
    round(v_new_fraction * v_r.principal_ves, 2);
end $function$;

CREATE OR REPLACE FUNCTION public.record_supplier_payment(p_invoice_id uuid, p_account_id uuid, p_amount numeric, p_paid_on date, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_invoice public.supplier_invoices; v_account public.financial_accounts; v_bcv numeric; v_op numeric; v_value_ves numeric; v_value_ref numeric; v_applied numeric; v_remaining numeric; v_movement uuid; v_id uuid; v_status text;
begin
  perform lubricenter_private.require_order_admin();
  select * into v_invoice from public.supplier_invoices where id=p_invoice_id for update;
  if not found or v_invoice.status in ('VOID','PAID') then raise exception 'La factura no tiene saldo pendiente'; end if;
  select * into v_account from public.financial_accounts where id=p_account_id and active and account_type<>'RELATED';
  if not found then raise exception 'Cuenta de pago no disponible'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'Monto inválido'; end if;
  if p_paid_on is null or p_paid_on>timezone('America/Caracas',now())::date then raise exception 'Fecha de pago inválida'; end if;
  select value into v_bcv from public.exchange_rates where rate_type='BCV' and timezone('America/Caracas',effective_at)::date<=p_paid_on order by effective_at desc limit 1;
  select value into v_op from public.exchange_rates where rate_type='OPERATIVE' and timezone('America/Caracas',effective_at)::date<=p_paid_on order by effective_at desc limit 1;
  if v_bcv is null or v_op is null then select bcv_rate,operative_rate into v_bcv,v_op from public.current_exchange_rates; end if;
  v_value_ves:=case when v_account.currency='USD' then round(p_amount*v_op,2) else round(p_amount,2) end;
  v_value_ref:=round(v_value_ves/v_bcv,4);
  v_applied:=case when v_invoice.currency='USD' then v_value_ref else v_value_ves end;
  v_remaining:=greatest(v_invoice.total_original-v_invoice.paid_original,0);
  if v_applied > (v_remaining + (case when v_invoice.currency='USD' then 0.05 else 1 end)) then raise exception 'El pago supera el saldo pendiente'; end if;
  v_applied:=least(v_applied,v_remaining);
  insert into public.account_movements(account_id,direction,movement_type,currency,amount_original,value_ves,category,payee,note,reference,occurred_at)
  select p_account_id,'OUT','SUPPLIER_PAYMENT',v_account.currency,p_amount,v_value_ves,'Pago a proveedor',s.name,nullif(trim(p_note),''),nullif(trim(p_reference),''),((p_paid_on::timestamp+time '12:00') at time zone 'America/Caracas') from public.suppliers s where s.id=v_invoice.supplier_id returning id into v_movement;
  insert into public.supplier_payments(supplier_invoice_id,account_id,account_movement_id,currency,amount_original,amount_applied_invoice,value_ves,value_ref,paid_on,reference,note)
  values(p_invoice_id,p_account_id,v_movement,v_account.currency,p_amount,v_applied,v_value_ves,v_value_ref,p_paid_on,nullif(trim(p_reference),''),nullif(trim(p_note),'')) returning id into v_id;
  v_status:=case when v_invoice.paid_original+v_applied >= (v_invoice.total_original - (case when v_invoice.currency='USD' then 0.05 else 1 end)) then 'PAID' else 'PARTIAL' end;
  update public.supplier_invoices set paid_original=case when v_status='PAID' then total_original else round(paid_original+v_applied,2) end,status=v_status,updated_at=now() where id=p_invoice_id;
  insert into public.audit_events(event_type,entity_type,entity_id,data) values('supplier_payment.recorded','supplier_payment',v_id,jsonb_build_object('invoice_id',p_invoice_id,'movement_id',v_movement,'amount',p_amount,'currency',v_account.currency,'applied',v_applied));
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.refund_customer_balance(p_customer_id uuid, p_pocket text, p_amount_usd numeric, p_method text, p_reference text, p_reason text, p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing public.customer_balance_movements; v_method text:=upper(coalesce(p_method,''));
  v_account_code text; v_account_id uuid; v_available numeric(18,2);
  v_bcv numeric; v_op numeric; v_currency text; v_original numeric(18,2);
  v_value_ves numeric(20,2); v_movement_id uuid; v_entry_id uuid;
begin
  perform lubricenter_private.finance_require('ADMIN');
  if p_request_id is null then raise exception 'Falta el identificador de esta operación'; end if;
  select * into v_existing from public.customer_balance_movements where request_id=p_request_id;
  if found then
    if v_existing.movement_type='REFUND' and v_existing.customer_id=p_customer_id
       and v_existing.pocket=p_pocket and v_existing.delta_usd=-p_amount_usd then return v_existing.id; end if;
    raise exception 'Este identificador ya corresponde a otra operación';
  end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Explica el motivo de la devolución'; end if;
  if p_amount_usd is null or p_amount_usd::text in ('NaN','Infinity','-Infinity')
    or p_amount_usd<=0 or round(p_amount_usd,2)<>p_amount_usd then
    raise exception 'Indica un monto positivo con máximo dos decimales';
  end if;
  if p_pocket='USD' then
    if v_method not in ('CASH_USD','ZELLE','BINANCE') then raise exception 'El saldo en divisas debe devolverse en divisas'; end if;
  elsif p_pocket='VES_BCV' then
    if v_method not in ('CASH_VES','TRANSFER_BDV','TRANSFER_BNC') then raise exception 'El saldo recibido en Bs se devuelve en Bs a la BCV de hoy'; end if;
  else raise exception 'Saldo no reconocido'; end if;
  if v_method in ('TRANSFER_BDV','TRANSFER_BNC')
    and coalesce(trim(p_reference),'') !~ '^[0-9]{4}$' then
    raise exception 'Escribe los últimos 4 dígitos de referencia del pago móvil';
  end if;
  v_account_code := case v_method when 'CASH_USD' then 'CASH_USD'
    when 'CASH_VES' then 'CASH_VES' when 'TRANSFER_BDV' then 'BDV'
    when 'TRANSFER_BNC' then 'BNC' when 'ZELLE' then 'ZELLE'
    when 'BINANCE' then 'BINANCE' end;
  select id into v_account_id from public.financial_accounts where code=v_account_code and active=true;
  if v_account_id is null then raise exception 'Cuenta financiera % no disponible',v_account_code; end if;
  select bcv_rate,operative_rate into v_bcv,v_op from public.current_exchange_rates;
  if v_bcv is null or v_bcv<=0 or v_op is null or v_op<=0 then raise exception 'Faltan tasas vigentes'; end if;
  select balance_usd into v_available from public.customer_balance_accounts
    where customer_id=p_customer_id and pocket=p_pocket for update;
  if v_available is null or p_amount_usd>v_available then
    raise exception 'Saldo insuficiente: disponible % USD',coalesce(v_available,0);
  end if;
  v_currency := case when p_pocket='USD' then 'USD' else 'VES' end;
  v_original := case when p_pocket='USD' then p_amount_usd else round(p_amount_usd*v_bcv,2) end;
  v_value_ves := case when p_pocket='USD' then round(p_amount_usd*v_op,2) else v_original end;
  insert into public.account_movements(
    account_id,direction,movement_type,currency,amount_original,value_ves,
    category,note,reference,occurred_at,created_by,finance_nature
  ) values (
    v_account_id,'OUT','ADJUSTMENT',v_currency,v_original,v_value_ves,
    'CUSTOMER_BALANCE_REFUND','Devolución de saldo a favor · '||trim(p_reason),
    nullif(trim(p_reference),''),now(),auth.uid(),'REFUND'
  ) returning id into v_movement_id;
  update public.customer_balance_accounts set balance_usd=balance_usd-p_amount_usd,updated_at=now()
    where customer_id=p_customer_id and pocket=p_pocket;
  insert into public.customer_balance_movements(
    customer_id,pocket,movement_type,delta_usd,amount_original,currency,value_ves,
    bcv_rate_snapshot,operative_rate_snapshot,method,reference,note,account_movement_id,request_id
  ) values (
    p_customer_id,p_pocket,'REFUND',-p_amount_usd,v_original,v_currency,v_value_ves,
    v_bcv,v_op,v_method,nullif(trim(p_reference),''),trim(p_reason),v_movement_id,p_request_id
  ) returning id into v_entry_id;
  insert into public.audit_events(event_type,entity_type,entity_id,data)
  values('customer_balance.refunded','customer_balance_movement',v_entry_id,
    jsonb_build_object('customer_id',p_customer_id,'pocket',p_pocket,'units_usd',p_amount_usd,
      'amount_original',v_original,'currency',v_currency,'bcv_rate',v_bcv,'account_movement_id',v_movement_id));
  return v_entry_id;
end $function$;

CREATE OR REPLACE FUNCTION public.regenerate_customer_followup_message(p_followup_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f public.customer_followups%rowtype;v_message text;
BEGIN
 PERFORM public.require_auth();
 SELECT * INTO f FROM public.customer_followups
 WHERE id=p_followup_id AND followup_type IN('POST_SERVICE','POST_SERVICE_CORRECTION')
  AND status<>'SENT' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Seguimiento no encontrado o ya enviado'; END IF;
 IF f.vehicle_id IS NULL THEN
  v_message:=public.build_post_service_message(f.order_id);
 ELSE
  v_message:=public.build_post_service_message_for_vehicle(f.order_id,f.vehicle_id);
 END IF;
 IF f.followup_type='POST_SERVICE_CORRECTION' THEN
  v_message:='📝 *Corrección del historial de mantenimiento*'||chr(10)||chr(10)||v_message;
 END IF;
 UPDATE public.customer_followups SET message=v_message,updated_at=now() WHERE id=p_followup_id;
 RETURN v_message;
END $function$;

CREATE OR REPLACE FUNCTION public.reopen_cash_day(p_business_date date, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_location uuid; v_id uuid;
begin
 perform public.require_auth();
 if not exists(select 1 from public.finance_cash_owner_locations o
   join public.locations l on l.id=o.location_id
   where o.user_id=auth.uid() and l.active
     and o.location_id=(select id from public.locations where active order by created_at limit 1)) then
   raise exception 'Solo el propietario de esta sucursal puede reabrir este cierre'; end if;
 if length(trim(coalesce(p_reason,''))) < 8 then raise exception 'Indica el motivo de reapertura'; end if;
 select id into v_location from public.locations where active order by created_at limit 1;
 if exists (
  select 1 from public.finance_reconciliation_periods rp
   where rp.location_id=v_location and p_business_date between rp.period_start and rp.period_end
     and rp.status in ('CLOSED','CLOSED_WITH_EXCEPTION')
 ) then raise exception 'La semana está conciliada. Primero debe reabrirse la conciliación semanal'; end if;
 update public.cash_closings
 set status='REOPENED',reopened_by=auth.uid(),reopened_at=now(),
     reopen_reason=trim(p_reason),updated_at=now()
 where business_date=p_business_date and location_id=v_location and status in ('CLOSED','REVIEW')
 returning id into v_id;
 if v_id is null then raise exception 'No hay un cierre presentado para reabrir'; end if;
 insert into public.audit_events(event_type,entity_type,entity_id,data)
 values('cash_close.reopened','cash_closing',v_id,
  jsonb_build_object('business_date',p_business_date,'reason',trim(p_reason)));
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.round_to_step(p_value numeric, p_step numeric, p_mode text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p_step is null or p_step <= 0 then return p_value; end if;
  if p_mode = 'up' then return ceil(p_value / p_step) * p_step; end if;
  if p_mode = 'down' then return floor(p_value / p_step) * p_step; end if;
  return round(p_value / p_step) * p_step;
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_vehicles_for_customer(p_customer_id uuid, p_query text, p_limit integer DEFAULT 12)
 RETURNS TABLE(id uuid, customer_id uuid, plate text, make text, model text, year integer, engine text, current_odometer integer, customer_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_query text := nullif(trim(p_query), '');
  v_limit integer := least(greatest(coalesce(p_limit, 12), 1), 50);
begin
  perform public.require_auth();
  if v_query is null then return; end if;
  return query
  select v.id, v.customer_id, v.plate, v.make, v.model, v.year, v.engine, v.current_odometer, c.name
  from public.vehicles v
  left join public.customers c on c.id = v.customer_id
  where v.customer_id is distinct from p_customer_id
    and concat_ws(' ', v.plate, v.make, v.model, v.year::text, c.name) ilike '%' || v_query || '%'
  order by case when upper(coalesce(v.plate,'')) = upper(v_query) then 0 else 1 end, v.updated_at desc
  limit v_limit;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_billing_settings(p_discount_free_limit_percent numeric, p_cashea_opportunity_monthly_percent numeric, p_cashea_financing_days numeric, p_store_markup_percent numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.require_auth();
  if not coalesce(public.can_administer_orders(), false) then
    raise exception 'Solo el dueño puede cambiar esta configuración';
  end if;
  if p_discount_free_limit_percent is null or p_discount_free_limit_percent < 0 or p_discount_free_limit_percent > 50 then
    raise exception 'El tope de descuento debe estar entre 0 y 50%%'; end if;
  if p_cashea_opportunity_monthly_percent is null or p_cashea_opportunity_monthly_percent < 0 or p_cashea_opportunity_monthly_percent > 30 then
    raise exception 'El rendimiento mensual debe estar entre 0 y 30%%'; end if;
  if p_cashea_financing_days is null or p_cashea_financing_days < 0 or p_cashea_financing_days > 120 then
    raise exception 'Los días de financiamiento deben estar entre 0 y 120'; end if;
  if p_store_markup_percent is null or p_store_markup_percent < 0 or p_store_markup_percent > 300 then
    raise exception 'El recargo de tienda debe estar entre 0 y 300%%'; end if;
  insert into public.app_settings(key, value, updated_at) values
    ('discount_free_limit_percent', to_jsonb(p_discount_free_limit_percent), now()),
    ('cashea_opportunity_monthly_percent', to_jsonb(p_cashea_opportunity_monthly_percent), now()),
    ('cashea_financing_days', to_jsonb(p_cashea_financing_days), now()),
    ('store_markup_percent', to_jsonb(p_store_markup_percent), now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end $function$;

CREATE OR REPLACE FUNCTION public.set_cashea_surcharge(p_order_id uuid, p_initial_percent numeric)
 RETURNS TABLE(surcharge_percent numeric, surcharge_ref numeric, total_ref numeric, total_ves numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_bcv numeric; v_op numeric; v_labor numeric; v_pct numeric := 0; v_ref numeric := 0;
begin
  perform public.require_auth();
  perform public.assert_order_open(p_order_id);
  perform 1 from public.orders where id = p_order_id for update;

  delete from public.order_items where order_id = p_order_id and line_role = 'CASHEA_SURCHARGE';

  if p_initial_percent is not null then
    if p_initial_percent <= 0 or p_initial_percent > 100 then raise exception 'Inicial inválida'; end if;
    select coalesce(sum(i.charged_ref_amount), 0) into v_labor
    from public.order_items i
    where i.order_id = p_order_id and lubricenter_private.effective_line_role(i) = 'LABOR';
    if v_labor > 0 then
      v_pct := public.cashea_surcharge_percent(p_initial_percent);
      v_ref := round(v_labor * v_pct / 100, 2);
      select r.bcv_rate, r.operative_rate into v_bcv, v_op from public.get_order_rates(p_order_id) r;
      if v_bcv is null or v_op is null then raise exception 'Debes registrar tasas antes de cobrar'; end if;
      if v_ref > 0 then
        insert into public.order_items(order_id, item_type, business_area, description, quantity, pricing_mode,
          base_ref_amount, customer_ref_amount, charged_ves_amount, charged_ref_amount,
          bcv_rate_snapshot, operative_rate_snapshot, line_role)
        values (p_order_id, 'SERVICE', 'WORKSHOP',
          'Recargo Cashea ' || to_char(v_pct, 'FM990.00') || '% sobre mano de obra', 1, 'STANDARD',
          v_ref, v_ref, round(v_ref * v_bcv, 2), v_ref, v_bcv, v_op, 'CASHEA_SURCHARGE');
      end if;
    end if;
  end if;

  return query
  select v_pct, v_ref,
    round(coalesce(sum(i.charged_ref_amount), 0), 4), round(coalesce(sum(i.charged_ves_amount), 0), 2)
  from public.order_items i where i.order_id = p_order_id;
end $function$;

CREATE OR REPLACE FUNCTION public.set_crm_contact_permission(p_customer_id uuid, p_status text, p_evidence text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.require_auth();
  IF p_status NOT IN ('OPT_IN','OPT_OUT') THEN
    RAISE EXCEPTION 'Estado de consentimiento no válido';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=p_customer_id) THEN
    RAISE EXCEPTION 'Cliente no encontrado';
  END IF;
  IF p_status='OPT_IN' AND length(btrim(coalesce(p_evidence,'')))<8 THEN
    RAISE EXCEPTION 'Indica dónde y cómo autorizó el cliente estos recordatorios';
  END IF;
  IF length(coalesce(p_evidence,''))>400 THEN
    RAISE EXCEPTION 'La nota de consentimiento no puede superar 400 caracteres';
  END IF;
  INSERT INTO public.crm_contact_permissions(customer_id,status,evidence,recorded_by,updated_at)
  VALUES (p_customer_id,p_status,btrim(coalesce(p_evidence,'')),auth.uid(),now())
  ON CONFLICT (customer_id) DO UPDATE SET
    status=EXCLUDED.status,evidence=EXCLUDED.evidence,
    recorded_by=auth.uid(),updated_at=now();
END;
$function$;

