CREATE OR REPLACE FUNCTION public.set_exchange_rates(p_bcv numeric, p_operative numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_now timestamptz := now();
begin
