CREATE OR REPLACE FUNCTION public.set_owner_pin(p_current text, p_new text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_check text;
begin
  perform public.require_auth();
  if not coalesce(public.can_administer_orders(), false) then
    raise exception 'Solo el dueño puede cambiar el PIN';
  end if;
  if p_new is null or p_new !~ '^\d{4,8}$' then raise exception 'El PIN debe tener de 4 a 8 números'; end if;
  if public.owner_pin_configured() then
    v_check := lubricenter_private.owner_pin_check(p_current);
    if v_check = 'LOCKED' then raise exception 'PIN bloqueado por intentos fallidos. Espera 15 minutos.'; end if;
    if v_check <> 'OK' then raise exception 'El PIN actual no coincide'; end if;
  end if;
  insert into lubricenter_private.owner_secrets(key, secret_hash, updated_at, updated_by)
  values ('discount_pin', extensions.crypt(p_new, extensions.gen_salt('bf')), now(), auth.uid())
  on conflict (key) do update set secret_hash = excluded.secret_hash, updated_at = now(),
    updated_by = auth.uid(), failed_attempts = 0, locked_until = null;
  insert into public.audit_events(event_type, entity_type, entity_id, data)
  values ('owner_pin.changed', 'app_settings', null, jsonb_build_object('by', auth.uid()));
end $function$;

CREATE OR REPLACE FUNCTION public.set_pricing_settings(p_rounding_step numeric, p_rounding_mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.require_auth();
  if p_rounding_step <= 0 then raise exception 'Paso de redondeo inválido'; end if;
  if p_rounding_mode not in ('nearest','up','down') then raise exception 'Modo de redondeo inválido'; end if;
  insert into public.app_settings(key,value) values ('price_rounding_step',to_jsonb(p_rounding_step))
    on conflict(key) do update set value=excluded.value, updated_at=now();
  insert into public.app_settings(key,value) values ('price_rounding_mode',to_jsonb(p_rounding_mode))
    on conflict(key) do update set value=excluded.value, updated_at=now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.snapshot_order_item_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cost numeric;
begin
  if new.movement_type='SALE' and new.order_item_id is not null then
    select average_cost_ref into v_cost from public.inventory_items where id=new.inventory_item_id;
    update public.order_items set unit_cost_ref_snapshot=coalesce(unit_cost_ref_snapshot,v_cost),total_cost_ref_snapshot=coalesce(total_cost_ref_snapshot,round(abs(new.quantity_delta)*v_cost,4)) where id=new.order_item_id;
  end if;
  return new;
end;
$function$;

